-- ============================================================
-- 织梦绮谭 - 数据库初始化脚本
-- 根据模板 JSON 文件自动生成
-- 包含: 11张表 + 12个分类 + 34个模板 + 78条分类映射
-- ============================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

CREATE DATABASE IF NOT EXISTS `narrator_engine`
  DEFAULT CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

USE `narrator_engine`;

-- ------------------------------------------------------------
-- 表: users - 用户表
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `users` (
  `id` VARCHAR(32) NOT NULL COMMENT '用户唯一ID（UUID）',
  `username` VARCHAR(64) NOT NULL COMMENT '用户登录名（唯一）',
  `password_hash` VARCHAR(255) NOT NULL COMMENT '密码哈希值',
  `display_name` VARCHAR(64) DEFAULT NULL COMMENT '用户显示名称/昵称',
  `email` VARCHAR(128) DEFAULT NULL COMMENT '用户邮箱',
  `role` VARCHAR(16) NOT NULL DEFAULT 'user' COMMENT '用户角色：user / admin',
  `avatar_url` VARCHAR(512) DEFAULT NULL COMMENT '用户头像 URL（MinIO 存储地址）',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '账号创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_username` (`username`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户表';

-- ------------------------------------------------------------
-- 表: template_categories - 模板分类表
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `template_categories` (
  `id` INT NOT NULL AUTO_INCREMENT COMMENT '分类自增主键',
  `code` VARCHAR(32) NOT NULL COMMENT '分类编码（唯一标识，如 xianxia、wuxia）',
  `name` VARCHAR(64) NOT NULL COMMENT '分类显示名称（如 仙侠修真、武侠江湖）',
  `description` TEXT DEFAULT NULL COMMENT '分类描述',
  `icon` VARCHAR(64) DEFAULT NULL COMMENT '分类图标名称（前端图标组件名）',
  `sort_order` INT DEFAULT 0 COMMENT '排序序号（越小越靠前）',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='模板分类表';

-- ------------------------------------------------------------
-- 表: templates - 模板表（世界观/角色/剧本）
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `templates` (
  `id` INT NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `template_id` VARCHAR(64) NOT NULL COMMENT '模板业务ID（唯一标识，如 world_xianxia）',
  `template_type` VARCHAR(16) NOT NULL COMMENT '模板类型：world=世界观, character=角色, scenario=剧本',
  `name` VARCHAR(128) NOT NULL COMMENT '模板名称',
  `description` TEXT DEFAULT NULL COMMENT '模板描述',
  `tags` JSON DEFAULT NULL COMMENT '标签列表（JSON数组，如 ["仙侠","修真"]）',
  `is_preset` BOOLEAN DEFAULT FALSE COMMENT '是否为预设模板（TRUE=系统预设对所有用户可见，FALSE=用户自建仅自己可见）',
  `creator_id` VARCHAR(32) DEFAULT NULL COMMENT '创建者用户ID（预设模板为NULL，关联 users 表）',
  `data` JSON NOT NULL COMMENT '模板详细数据（JSON格式，存放世界观/角色/剧本的具体配置）',
  `avatar_url` VARCHAR(512) DEFAULT NULL COMMENT '角色头像/立绘 或 世界封面图 URL',
  `bg_url` VARCHAR(512) DEFAULT NULL COMMENT '背景图 URL（世界观模板的场景背景）',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_template_id` (`template_id`),
  INDEX `idx_type` (`template_type`),
  INDEX `idx_preset` (`is_preset`),
  CONSTRAINT `fk_templates_creator` FOREIGN KEY (`creator_id`) REFERENCES `users`(`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='模板表（世界观/角色/剧本）';

-- ------------------------------------------------------------
-- 表: template_category_mapping - 模板与分类关联表（多对多中间表）
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `template_category_mapping` (
  `template_id` INT NOT NULL COMMENT '模板ID（关联 templates.id）',
  `category_id` INT NOT NULL COMMENT '分类ID（关联 template_categories.id）',
  PRIMARY KEY (`template_id`, `category_id`),
  CONSTRAINT `fk_mapping_template` FOREIGN KEY (`template_id`) REFERENCES `templates`(`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_mapping_category` FOREIGN KEY (`category_id`) REFERENCES `template_categories`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='模板与分类关联表（多对多）';

-- ------------------------------------------------------------
-- 表: game_sessions - 游戏会话表
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `game_sessions` (
  `id` VARCHAR(32) NOT NULL COMMENT '会话唯一ID（UUID）',
  `user_id` VARCHAR(32) DEFAULT NULL COMMENT '所属用户ID（关联 users 表）',
  `world_template_id` VARCHAR(64) NOT NULL COMMENT '选择的世界观模板ID',
  `scenario_template_id` VARCHAR(64) NOT NULL COMMENT '选择的剧本模板ID',
  `player_name` VARCHAR(64) NOT NULL DEFAULT '主角' COMMENT '玩家角色名称',
  `player_data` JSON DEFAULT NULL COMMENT '玩家自定义数据（年龄/背景/外观等）',
  `chapter` INT NOT NULL DEFAULT 1 COMMENT '当前章节编号',
  `total_chapters` INT NOT NULL DEFAULT 4 COMMENT '剧本预估总章节数',
  `current_scene` TEXT DEFAULT NULL COMMENT '当前场景描述',
  `world_state` JSON DEFAULT NULL COMMENT '世界状态标志（地点、时间、全局flag等）',
  `total_turns` INT NOT NULL DEFAULT 0 COMMENT '总对话轮次计数',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '会话创建时间',
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  PRIMARY KEY (`id`),
  INDEX `idx_user` (`user_id`),
  CONSTRAINT `fk_sessions_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='游戏会话表';

-- ------------------------------------------------------------
-- 表: dialogue_logs - 对话日志表
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `dialogue_logs` (
  `id` VARCHAR(32) NOT NULL COMMENT '对话记录唯一ID（UUID）',
  `session_id` VARCHAR(32) NOT NULL COMMENT '所属游戏会话ID（关联 game_sessions 表）',
  `turn_number` INT NOT NULL COMMENT '对话轮次序号（从1开始递增）',
  `speaker` VARCHAR(64) NOT NULL COMMENT '说话人标识（player=玩家, narrator=旁白, 或角色名）',
  `content` MEDIUMTEXT NOT NULL COMMENT '对话内容（玩家输入或AI生成的文本）',
  `input_type` VARCHAR(16) NOT NULL DEFAULT 'choice' COMMENT '输入类型：choice=选择选项, free=自由输入',
  `emotion` VARCHAR(64) DEFAULT NULL COMMENT '情感标签（中文，如 温和、冷淡、害羞）',
  `action` TEXT DEFAULT NULL COMMENT '动作/表情描写',
  `choices_offered` JSON DEFAULT NULL COMMENT '本轮提供的选项列表（JSON数组）',
  `choice_made` TEXT DEFAULT NULL COMMENT '玩家的选择内容（选项文本或自由输入）',
  `metadata` JSON DEFAULT NULL COMMENT '附加元数据（场景状态、好感度变化等）',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  PRIMARY KEY (`id`),
  INDEX `idx_session_turn` (`session_id`, `turn_number`),
  CONSTRAINT `fk_dialogues_session` FOREIGN KEY (`session_id`) REFERENCES `game_sessions`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='对话日志表';

-- ------------------------------------------------------------
-- 表: affection_states - 角色好感度状态表（五维模型）
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `affection_states` (
  `id` VARCHAR(32) NOT NULL COMMENT '好感度记录唯一ID（UUID）',
  `session_id` VARCHAR(32) NOT NULL COMMENT '所属游戏会话ID',
  `character_id` VARCHAR(64) NOT NULL COMMENT '角色模板ID（关联 templates.template_id）',
  `character_name` VARCHAR(64) NOT NULL COMMENT '角色显示名称',
  `intimacy` FLOAT NOT NULL DEFAULT 0 COMMENT '亲密度维度（权重0.3，0-100）',
  `trust` FLOAT NOT NULL DEFAULT 0 COMMENT '信任维度（权重0.25，0-100）',
  `respect` FLOAT NOT NULL DEFAULT 0 COMMENT '尊重维度（权重0.2，0-100）',
  `curiosity` FLOAT NOT NULL DEFAULT 0 COMMENT '好奇维度（权重0.15，0-100）',
  `fear` FLOAT NOT NULL DEFAULT 0 COMMENT '畏惧维度（权重0.1，0-100）',
  `current_rank` VARCHAR(32) NOT NULL DEFAULT '陌生' COMMENT '当前好感度等级（陌生/熟悉/友好/亲密/挚爱等）',
  `triggered_events` JSON DEFAULT NULL COMMENT '已触发的好感度事件列表',
  `known_secrets` JSON DEFAULT NULL COMMENT '角色已知秘密列表',
  `relationship_label` VARCHAR(128) NOT NULL DEFAULT '陌生人' COMMENT '关系标签文本（如 陌生人、知己、恋人）',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  PRIMARY KEY (`id`),
  INDEX `idx_session` (`session_id`),
  CONSTRAINT `fk_affection_session` FOREIGN KEY (`session_id`) REFERENCES `game_sessions`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='角色好感度状态表（五维模型）';

-- ------------------------------------------------------------
-- 表: scene_summaries - 场景摘要表（情景记忆层）
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `scene_summaries` (
  `id` VARCHAR(32) NOT NULL COMMENT '摘要唯一ID（UUID）',
  `session_id` VARCHAR(32) NOT NULL COMMENT '所属游戏会话ID',
  `chapter` INT NOT NULL COMMENT '所属章节编号',
  `scene_name` VARCHAR(128) DEFAULT NULL COMMENT '场景名称（如「月夜庭院初遇」）',
  `summary_text` TEXT DEFAULT NULL COMMENT '场景摘要文本（200-500 tokens 的压缩描述）',
  `characters_present` JSON DEFAULT NULL COMMENT '在场角色列表（JSON数组）',
  `key_events` JSON DEFAULT NULL COMMENT '关键事件列表（JSON数组）',
  `turn_range_start` INT DEFAULT NULL COMMENT '该场景起始对话轮次',
  `turn_range_end` INT DEFAULT NULL COMMENT '该场景结束对话轮次',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '摘要创建时间',
  PRIMARY KEY (`id`),
  INDEX `idx_session_chapter` (`session_id`, `chapter`),
  CONSTRAINT `fk_summaries_session` FOREIGN KEY (`session_id`) REFERENCES `game_sessions`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='场景摘要表（情景记忆层）';

-- ------------------------------------------------------------
-- 表: memories - 语义记忆表（关键事实，配合 ChromaDB 向量检索）
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `memories` (
  `id` VARCHAR(32) NOT NULL COMMENT '记忆唯一ID（UUID）',
  `session_id` VARCHAR(32) NOT NULL COMMENT '所属游戏会话ID',
  `content` TEXT NOT NULL COMMENT '记忆内容文本',
  `importance` INT NOT NULL DEFAULT 5 COMMENT '重要度评分（1-10，低于阈值的不会被存入长期记忆）',
  `category` VARCHAR(32) DEFAULT 'other' COMMENT '记忆分类（如 character_trait、plot_event、world_fact 等）',
  `related_characters` JSON DEFAULT NULL COMMENT '相关角色列表（JSON数组）',
  `chapter` INT DEFAULT 1 COMMENT '记忆产生的章节编号',
  `embedding_id` VARCHAR(64) DEFAULT NULL COMMENT 'ChromaDB 向量索引ID（用于语义检索）',
  `metadata` JSON DEFAULT NULL COMMENT '附加元数据（JSON格式）',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '记忆创建时间',
  PRIMARY KEY (`id`),
  INDEX `idx_session_importance` (`session_id`, `importance`),
  CONSTRAINT `fk_memories_session` FOREIGN KEY (`session_id`) REFERENCES `game_sessions`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='语义记忆表（关键事实，配合 ChromaDB 向量检索）';

-- ------------------------------------------------------------
-- 表: player_profiles - 玩家画像表
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `player_profiles` (
  `id` VARCHAR(32) NOT NULL COMMENT '画像记录唯一ID（UUID）',
  `session_id` VARCHAR(32) NOT NULL COMMENT '所属游戏会话ID（每个会话最多一条画像）',
  `name` VARCHAR(64) NOT NULL COMMENT '玩家角色名称',
  `age` VARCHAR(16) DEFAULT NULL COMMENT '玩家角色年龄',
  `background` TEXT DEFAULT NULL COMMENT '玩家角色背景故事',
  `observed_traits` JSON DEFAULT NULL COMMENT 'AI观察到的玩家性格特征列表（JSON数组）',
  `play_style` VARCHAR(64) DEFAULT NULL COMMENT '玩家游玩风格标签（如 谨慎型、冒险型）',
  `key_decisions` JSON DEFAULT NULL COMMENT '玩家做出的重要决定列表（JSON数组，记录关键选择及其影响）',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '画像创建时间',
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '画像最后更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_session` (`session_id`),
  CONSTRAINT `fk_profiles_session` FOREIGN KEY (`session_id`) REFERENCES `game_sessions`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='玩家画像表';

-- ------------------------------------------------------------
-- 表: save_slots - 存档位表
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `save_slots` (
  `id` VARCHAR(32) NOT NULL COMMENT '存档唯一ID（UUID）',
  `user_id` VARCHAR(32) DEFAULT NULL COMMENT '所属用户ID（关联 users 表）',
  `session_id` VARCHAR(32) NOT NULL COMMENT '所属游戏会话ID',
  `slot_number` INT NOT NULL COMMENT '存档位编号（1-20为用户手动存档，101-103为自动存档）',
  `auto_save` BOOLEAN NOT NULL DEFAULT FALSE COMMENT '是否为自动存档（TRUE=自动存档）',
  `title` VARCHAR(128) NOT NULL DEFAULT '' COMMENT '存档标题（用户自定义或自动生成）',
  `description` TEXT DEFAULT NULL COMMENT '存档描述（如场景摘要、进度信息等）',
  `state_snapshot` JSON NOT NULL COMMENT '游戏状态快照（JSON格式，保存完整游戏状态用于恢复）',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '存档创建时间',
  PRIMARY KEY (`id`),
  INDEX `idx_session` (`session_id`),
  INDEX `idx_user` (`user_id`),
  CONSTRAINT `fk_saves_session` FOREIGN KEY (`session_id`) REFERENCES `game_sessions`(`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_saves_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='存档位表';

SET FOREIGN_KEY_CHECKS = 1;

-- ------------------------------------------------------------
-- 表: user_game_settings - 用户游戏设置表（一对一关联用户）
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `user_game_settings` (
  `id` INT NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `user_id` VARCHAR(32) NOT NULL COMMENT '用户ID（一对一关联 users 表）',
  `bgm_url` VARCHAR(512) DEFAULT NULL COMMENT '自定义 BGM 文件 URL',
  `bgm_volume` FLOAT NOT NULL DEFAULT 0.7 COMMENT 'BGM 音量 (0.0 ~ 1.0)',
  `bgm_enabled` BOOLEAN NOT NULL DEFAULT TRUE COMMENT '是否启用 BGM',
  `sfx_volume` FLOAT NOT NULL DEFAULT 0.8 COMMENT '音效音量 (0.0 ~ 1.0)',
  `bg_url` VARCHAR(512) DEFAULT NULL COMMENT '自定义游戏背景图 URL',
  `text_speed` VARCHAR(16) NOT NULL DEFAULT 'normal' COMMENT '文字显示速度: slow / normal / fast / instant',
  `theme` VARCHAR(16) NOT NULL DEFAULT 'dark' COMMENT '界面主题: dark / light / custom',
  `font_size` INT NOT NULL DEFAULT 16 COMMENT '对话文字字号 (px)',
  `auto_advance` BOOLEAN NOT NULL DEFAULT FALSE COMMENT '是否自动推进对话',
  `show_affection_popup` BOOLEAN NOT NULL DEFAULT TRUE COMMENT '是否显示好感度变化弹窗',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_id` (`user_id`),
  CONSTRAINT `fk_settings_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户游戏设置表（一对一关联用户）';

