-- ------------------------------------------------------------
-- 种子数据: templates (worlds) - 世界观模板
-- ------------------------------------------------------------
INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('world_xianxia', 'world', '云海仙宗 — 修仙问道的九天之上', '修仙仙侠题材。以悬浮于九天之上的「云海仙山」为舞台，正道与魔道争锋，修士在灵气氤氲的仙峰之间求道问心，踏上一条通往长生的漫漫仙途。', '["仙侠", "修真", "宗门争斗", "炼器炼丹", "恋爱", "冒险"]', TRUE, '{\n  "template_id": "world_xianxia",\n  "template_type": "world",\n  "name": "云海仙宗 — 修仙问道的九天之上",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "修仙仙侠题材。以悬浮于九天之上的「云海仙山」为舞台，正道与魔道争锋，修士在灵气氤氲的仙峰之间求道问心，踏上一条通往长生的漫漫仙途。",\n  "world": {\n    "era": "上古仙侠纪元（架空修真世界）",\n    "genre": ["仙侠", "修真", "宗门争斗", "炼器炼丹", "恋爱", "冒险"],\n    "setting_description": "故事发生在「云海仙山」——一片由远古大能以无上神通拔地而起、悬浮于万丈高空的仙山脉络。仙山之中灵脉纵横，分布着大大小小数十个修仙宗门，彼此或结盟或对峙，共守这片天地。仙山之下是茫茫云海，云海之下则是凡间红尘，芸芸众生不知仙道为何物。仙山之上更有九天雷域，传闻渡过九重天劫便可飞升成仙。主角出身于一个中等宗门，因缘际会获得一部远古残卷，从此踏上了一条波澜壮阔的修仙之路。修为境界依次为：练气、筑基、金丹、元婴、化神，每一重境界的突破都伴随着天劫与心魔的考验。灵石为通行货币，丹药、法器、符箓是修士的日常所需。",\n    "rules": [\n      "修为境界分为：练气期（一至九层）→ 筑基期（初/中/后/大圆满）→ 金丹期 → 元婴期 → 化神期。每次大境界突破均需渡天劫，失败则身死道消。",\n      "灵石是修仙界的通用货币，分为下品、中品、上品、极品四个等级，一枚中品灵石可抵百枚下品灵石。灵石同时也可用于修炼、布阵、驱动法器。",\n      "修士可修炼多种副业：炼丹（炼制辅助修炼或疗伤的丹药）、炼器（锻造法器与灵器）、阵法（布置攻防大阵）、符箓（以符纸储存法术）。",\n      "宗门之间有严格的等级制度：掌门/宗主、太上长老、长老、真传弟子、内门弟子、外门弟子、杂役弟子。宗门资源有限，弟子之间需竞争修炼资源。",\n      "「魔道」与「正道」的根本区别在于修炼方式：魔道修士以吸收他人修为或怨气为捷径，威力强大但心性易被侵蚀；正道修士循序渐进，根基稳固但进境较慢。",\n      "仙山之下设有「封印结界」，隔绝凡间与修仙界的往来。只有达到筑基期修为才能穿越云海，进入凡间执行宗门任务。",\n      "每隔三十年，九天雷域会降下一次「大天劫」，届时所有元婴期以上的修士都必须应对，是修仙界的最大危机，也是突破化神期的唯一契机。",\n      "「道心」是修士最重要的根基——若道心崩塌（经历背叛、丧失信念等），修为会大幅倒退，严重者走火入魔。"\n    ],\n    "locations": [\n      {\n        "name": "太清宗·主峰",\n        "description": "云海仙山中最大的正道宗门，主峰「太清峰」高耸入云，峰顶终年有金色祥云环绕。宗门立派三千余年，传承深厚，以「太上忘情」为宗义，是正道仙盟的领袖宗门。主角即为太清宗弟子。",\n        "sub_locations": ["太清大殿（议事场所）", "传功阁（功法秘籍藏库）", "洗剑池（淬炼法器之地）", "弟子居所·内门山峰群", "长老峰（长老闭关修炼之地）", "宗门广场（每月宗门集会之处）"]\n      },\n      {\n        "name": "灵药谷",\n        "description": "太清宗后山一处隐蔽的谷地，谷中灵脉汇聚，四季恒温，生长着数以千计的灵草仙药。谷中有专门的药田供弟子种植修炼用灵材，由宗门药堂统一管理。谷深处有一株万年灵芝，据说是宗门护山大阵的阵眼所在。",\n        "sub_locations": ["百草园（普通灵药种植区）", "丹房（炼丹专用洞府）", "灵泉眼（恢复灵力的天然泉水）", "禁药区（种植危险毒草，需长老许可进入）", "药堂库房（灵药存储与交易之处）"]\n      },\n      {\n        "name": "试剑台·秘境",\n        "description": "云海仙山中一处上古遗迹，被各大宗门联手改造为弟子历练之所。秘境内地形多变，有山川湖海，栖息着被捕获后放入的灵兽。每五年举办一次「仙门大比」，各宗弟子在此争锋，胜者可获得稀世资源。",\n        "sub_locations": ["入门广场（传送阵集合地）", "灵兽森林（栖息各阶灵兽）", "剑冢（插满残剑的古战场）", "天梯崖（考验意志的千阶石梯）", "核心秘境（只有前三名才能进入的宝库）"]\n      },\n      {\n        "name": "红尘渡口·凡间",\n        "description": "云海之下、凡间之上的交界处。这里有一座小镇名为「望仙镇」，居住着修仙者的凡间亲族以及向往仙道的凡人。各宗门在此设有据点，用于招收有灵根的弟子，也是修士入世修行的起点。",\n        "sub_locations": ["望仙镇主街", "测灵台（测试灵根资质之处）", "宗门接引殿", "凡间集市（修士与凡人以物易物之地）", "送别亭（弟子下山历练的出发点）"]\n      },\n      {\n        "name": "九幽魔渊",\n        "description": "云海仙山最深处的一处裂谷，终年弥漫着浓郁的黑紫色魔气，是魔道六宗的根据地。传闻此处连接着一处远古魔神的封印之地，魔气正是从封印的裂缝中渗出。正道修士若无防护法器进入，灵力会被魔气不断侵蚀。",\n        "sub_locations": ["六宗殿（六大宗门各占一殿）", "血月祭坛（魔道大典举办之处）", "万魂窟（魔修以怨气修炼的禁地）", "魔神封印（最深处，被多重禁制封锁）"]\n      },\n      {\n        "name": "散修城·云中坊市",\n        "description": "悬浮于仙山边缘的一座空中城池，是散修联盟的总部所在，也是修仙界最大的自由交易坊市。城中酒楼、拍卖行、炼器铺、丹药铺林立，龙蛇混杂，是消息流通的中心。任何修士均可在此自由交易，但城中禁止动手，违者将被散修联盟驱逐。",\n        "sub_locations": ["天枢拍卖行（每月举办大型灵物拍卖）", "百艺街（炼器师、炼丹师设摊之处）", "情报阁（贩卖消息的神秘店铺）", "散修联盟议事厅", "云中酒楼（修士聚集交流情报之地）"]\n      },\n      {\n        "name": "妖域·万妖山",\n        "description": "云海仙山以东的一片连绵山脉，是妖族的领地。妖族由灵兽开智化形而成，修为高深者可化为人形。万妖山中有妖族王庭，由妖皇统御。妖族与人族之间关系复杂，既有和平贸易，也有领土争端。",\n        "sub_locations": ["化形池（灵兽化为人形之地）", "妖皇王庭", "百兽谷（低阶灵兽栖息之地）", "人妖互市（人族与妖族交易之处）", "祖妖陵（安葬历代妖皇之地）"]\n      }\n    ],\n    "factions": [\n      {\n        "name": "正道仙盟",\n        "description": "由太清宗领衔、联合十余个正道大宗组成的联盟。奉行「替天行道、守护苍生」之宗旨，维护修仙界的秩序。盟主由太清宗掌门担任，每百年重新推举一次。仙盟定期组织弟子围剿魔修，维护云海仙山安宁。",\n        "values": ["正道", "秩序", "守护", "传承"]\n      },\n      {\n        "name": "魔道六宗",\n        "description": "盘踞于九幽魔渊的六个魔道宗门，分别是：血煞宗、阴鬼门、噬魂殿、天魔宫、毒蛊谷、修罗道。六宗各有所长，虽彼此猜忌但在对抗正道时能暂时联手。魔道修炼以速成为特色，但代价是心性易被魔念侵蚀，寿元也较短。",\n        "values": ["力量", "自由", "执念", "生存"]\n      },\n      {\n        "name": "散修联盟",\n        "description": "无宗无派的独立修士所组成的松散联盟，以云中坊市为据点。联盟不设盟主，由七位化神期散修组成的「长老会」仲裁事务。散修们追求的是不受拘束的自由修行，但面对大势力时往往势单力薄，需要抱团取暖。",\n        "values": ["自由", "独立", "公平", "机遇"]\n      },\n      {\n        "name": "妖族王庭",\n        "description": "万妖山中的妖族政权，由妖皇「白泽」统御万妖。妖族社会以血脉和实力为尊，高阶妖族化为人形后可以与人族交往通商。妖族与人族之间有千年和约，但边境摩擦不断，主战派与主和派之间的角力从未停止。",\n        "values": ["血脉", "自然", "尊严", "共存"]\n      },\n      {\n        "name": "天机阁",\n        "description": "一个超脱正魔之争的神秘组织，专司推演天机、记录修仙界历史。阁中之人修炼特殊的「天机术」，能窥探命运的碎片，但每次推演都会折损寿元。天机阁在各大势力中都安插有眼线，是修仙界最强大的情报网络。",\n        "values": ["命运", "中立", "知识", "代价"]\n      }\n    ],\n    "custom_rules": [\n      "修炼系统：每个角色有修为境界、灵根属性（金木水火土/变异灵根）、功法品阶（凡级/灵级/地级/天级）三维属性，影响剧情走向和战斗结果。",\n      "宗门贡献系统：弟子通过完成任务、上交灵材获得宗门贡献点，可兑换功法、丹药、法器等资源，是弟子生存发展的核心。",\n      "心魔机制：重大抉择（背叛同门、杀戮无辜、违背誓言等）会累积心魔值，心魔值过高在突破境界时将触发心魔劫，可能导致修为尽失。",\n      "灵根与资质：灵根分为单灵根（最优）、双灵根、三灵根、四灵根、五灵根（最差），另有变异灵根（冰、雷、风、暗等），资质直接影响修炼速度和上限。",\n      "天劫系统：每次大境界突破都有天劫降临，天劫强度与修士实力成正比。可借助阵法、丹药、法器辅助渡劫，但外物过多会削弱渡劫后的修为增益。",\n      "仙门大比：每五年一度的宗门弟子大比，是获取资源、扬名立万的重要途径。大比结果会影响宗门在仙盟中的地位和资源分配。",\n      "道侣系统：修士之间可以结为道侣，双修可加速修炼，但一旦道侣身亡或背叛，另一方将遭受严重的心魔反噬。"\n    ],\n    "calendar_events": [\n      {"month": 1, "event": "新岁灵潮", "significance": "每年正月初一，仙山灵脉会涌动一次灵潮，灵气浓度骤增三日，是修士闭关突破的绝佳时机。各宗门弟子争相抢占灵脉节点闭关。"},\n      {"month": 3, "event": "春分·采药大典", "significance": "春分之日灵药谷的灵药药力最盛，太清宗举办一年一度的采药大典，外门弟子可借此机会进入禁药区采集稀有灵材，是崭露头角的舞台。"},\n      {"month": 5, "event": "仙门大比", "significance": "每五年一届的宗门弟子比武盛事，各宗派出精英弟子在试剑台秘境中争锋。主角若参加，将是改变命运的关键战役，也是结识各方势力的契机。"},\n      {"month": 7, "event": "中元鬼节·魔潮", "significance": "七月十五，九幽魔渊的魔气会异常活跃，魔修趁机侵扰正道领地。各宗门需加强防御，也是主角调查魔道阴谋的重要时机。"},\n      {"month": 9, "event": "秋分·论道大会", "significance": "正道仙盟一年一度的论道盛会，各宗长老聚首太清宗讨论修仙界大事。主角若修为足够可随同参加，接触高层权力博弈。"},\n      {"month": 11, "event": "妖族冬狩", "significance": "万妖山妖族举办的传统狩猎祭典，邀请人族修士观礼。表面是庆典，实则是妖族展示实力、人族探查妖族动向的暗中角力场。"},\n      {"month": 12, "event": "除夕·天劫降临", "significance": "岁末之夜，九天雷域会降下年度最强天劫，所有金丹期以上修士需全力应对。是故事高潮的天然时间节点，主角可能面临生死考验。"}\n    ]\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('world_jianghu', 'world', '剑啸江湖 — 快意恩仇的武林天下', '武侠江湖题材。以架空的古代中原武林为背景，刀光剑影中行走江湖，在恩仇与情义之间抉择，谱写一曲侠骨柔情的武林传奇。', '["武侠", "江湖恩怨", "侠义", "恋爱", "权谋", "冒险"]', TRUE, '{\n  "template_id": "world_jianghu",\n  "template_type": "world",\n  "name": "剑啸江湖 — 快意恩仇的武林天下",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "武侠江湖题材。以架空的古代中原武林为背景，刀光剑影中行走江湖，在恩仇与情义之间抉择，谱写一曲侠骨柔情的武林传奇。",\n  "world": {\n    "era": "架空古代中原（近似宋明之际）",\n    "genre": ["武侠", "江湖恩怨", "侠义", "恋爱", "权谋", "冒险"],\n    "setting_description": "故事发生在一片架空的中原武林天下。朝廷虽名义上统治四海，但实际控制力有限，江湖之事由武林中人自行了断。武林中以「武林盟」为尊，四大世家各据一方，魔教潜伏于暗处伺机而动，朝廷暗卫则在幕后窥探一切。江湖中流传着无数武学秘籍、绝世神功的传说，一把名剑、一卷残谱便可掀起腥风血雨。主角出身平凡，因一场变故卷入江湖纷争，在恩怨情仇中逐渐成长为一代侠客。武学修为以内力深浅为根本，外功招式为辅，顶尖高手可达「先天之境」，内力外放、飞花摘叶皆可伤人。",\n    "rules": [\n      "武学修为分为：入门（学会基础招式）→ 小成（内力初生）→ 大成（内功外功兼备）→ 宗师（自成一家）→ 先天之境（内力外放，超凡脱俗）。先天高手整个武林不超过十人。",\n      "内力是武学的根基，通过打坐吐纳、服用灵药或传承灌顶获得。内力耗尽则武功大减，需长时间调息恢复。不同门派的内功心法各有特色，不可兼修。",\n      "江湖有不成文的规矩：不杀已投降之人、不伤妇孺老弱、暗杀下毒为下三滥手段、比武需光明正大。违背江湖规矩者会被武林盟追杀。",\n      "「仇」是江湖中最重要的因果——杀父之仇、灭门之恨不可不报，否则视为不孝不义。但报仇的方式和时机却考验着侠客的智慧和良知。",\n      "江湖中流传着各种武学秘籍和神兵利器的传说。得到一部绝世秘籍或一柄旷世名剑，往往会引来无数觊觎，成为祸端之源。",\n      "朝廷与江湖维持着微妙的平衡：朝廷不干涉江湖事务，但江湖中人也不得公然对抗官府。朝廷暗卫暗中监视各大门派，防止江湖势力威胁社稷。",\n      "门派传承极为看重师承辈分，拜师、叛门、逐出师门都是大事。无门无派的散修武人被称为「江湖散人」，虽自由自在，却也孤立无援。"\n    ],\n    "locations": [\n      {\n        "name": "临安城·武林重镇",\n        "description": "江南第一繁华大城，也是武林盟总部所在地。城中商铺林立、酒楼茶肆鳞次栉比，来自五湖四海的江湖中人汇聚于此。每逢武林大会召开，城中客栈一房难求，是江湖消息最灵通之处。",\n        "sub_locations": ["武林盟总堂", "聚贤楼（江湖中人最爱聚集的酒楼）", "城南武市（买卖兵器暗器的集市）", "杏林医馆（专治江湖伤的名医所在）", "护城河畔（比武约战的常选之地）"]\n      },\n      {\n        "name": "青云山庄·四大世家之首",\n        "description": "位于泰山脚下的百年世家「沈家」的祖宅，占地极广，依山而建。沈家世代以剑法闻名，庄内设有演武场、剑阁、藏书楼。沈家家主是武林盟现任盟主，庄中来往皆是武林名流。",\n        "sub_locations": ["正堂（议事厅）", "听雨剑阁（沈家剑法修炼之所）", "万卷楼（武学典籍与江湖秘闻藏书处）", "后山练武场", "客房院落（招待贵客之处）"]\n      },\n      {\n        "name": "落雁谷·隐世秘境",\n        "description": "秦岭深处一处人迹罕至的幽谷，谷中风景绝美却暗藏杀机——谷口有毒瘴环绕，谷内机关重重。传闻此处是百年前「剑圣」归隐之所，留有绝世剑谱和毕生修为的传承。无数江湖中人曾来此寻宝，大多有去无回。主角因机缘巧合得以入谷。",\n        "sub_locations": ["毒瘴迷林（谷口天然屏障）", "剑圣石庐（剑圣晚年居住的石屋）", "剑意崖（刻满剑意的绝壁，悟性高者可从中领悟绝世剑招）", "灵药温泉（疗伤恢复的隐秘之地）", "机关密室（剑圣留下的试炼之地）"]\n      },\n      {\n        "name": "天香楼·江湖客栈",\n        "description": "官道上最负盛名的客栈，老板娘「柳三娘」是退隐江湖的昔日女侠，消息灵通、人脉极广。天香楼表面上只是一家普通的客栈酒楼，实际上是江湖中最重要的情报中转站，各方势力都在此安插眼线。",\n        "sub_locations": ["大堂（食客汇聚、消息流通之处）", "雅间（密谈之所，隔音极好）", "后院客房（长住客人的居所）", "地下室（柳三娘的私密空间，存有大量江湖情报）", "马厩与车马行（远行的起点）"]\n      },\n      {\n        "name": "魔教总坛·幽冥谷",\n        "description": "西南边陲一处常年笼罩在瘴气中的深谷，是魔教的核心所在。谷中建筑依山势而建，层层叠叠如同幽冥地狱。魔教以「明尊」为教主，教众遍布江湖，擅长用毒和暗杀之术。谷中有一处血池，传闻是以仇敌之血汇聚而成，是魔教邪功的修炼之所。",\n        "sub_locations": ["明尊大殿（教主接见教众之处）", "血池练功房", "毒蛊洞（培育各种蛊毒的禁地）", "囚牢（关押俘获的正道人士）", "密道（通往谷外的秘密通道）"]\n      },\n      {\n        "name": "京城·皇城根下",\n        "description": "当朝国都，天子脚下。朝廷暗卫的总部就设在皇城之内的一处隐秘院落。京城中权贵云集，江湖中人在此处需收敛锋芒。朝廷定期举办武举，笼络江湖人才为朝廷所用。京城也是政治阴谋的中心，江湖恩怨与朝堂权谋在此交汇。",\n        "sub_locations": ["暗卫总部·影阁", "武举校场", "御街（权贵出没之处）", "西市（京城最大的集市，可购得稀罕物件）", "大理寺牢狱（关押犯事江湖中人之处）"]\n      },\n      {\n        "name": "华山论剑台",\n        "description": "华山之巅的一处天然石台，方圆数丈，四面皆是万丈深渊。此处是武林中最负盛名的比武之所，「华山论剑」之名响彻江湖。每隔十年，天下绝顶高手齐聚于此，争夺「天下第一」之名。石台上刻满了历代论剑者的名字和绝招痕迹。",\n        "sub_locations": ["论剑石台", "观战崖（旁观者可在此远观）", "历代刻名壁", "上山栈道（唯一通路，易守难攻）", "华山道观（可供歇脚之处）"]\n      }\n    ],\n    "factions": [\n      {\n        "name": "武林盟",\n        "description": "由各大门派和世家联合组成的武林最高权力机构，现任盟主为沈家家主沈无极。武林盟负责调停门派纷争、发布江湖追杀令、举办武林大会。名义上维护江湖秩序，但盟主之位早已成为各方势力争夺的焦点。",\n        "values": ["秩序", "侠义", "名望", "传承"]\n      },\n      {\n        "name": "四大世家",\n        "description": "武林中势力最大的四个家族：沈家（剑法）、慕容家（暗器）、南宫家（内功）、上官家（轻功）。四家各有所长，世代联姻结盟，把控着武林的大部分资源。世家子弟从小习武，起点远高于普通江湖散人，但也背负着沉重的家族使命。",\n        "values": ["家族", "荣耀", "血脉", "利益"]\n      },\n      {\n        "name": "魔教",\n        "description": "江湖中最为神秘也最为危险的势力，教主「明尊」真实身份成谜。魔教教众遍布各门各派，许多正道门派中都有魔教的暗桩。魔教武学诡异凌厉，善用毒蛊暗器，行事不拘一格，是正道武林的心腹大患。但魔教内部也有派系之争，并非铁板一块。",\n        "values": ["自由", "颠覆", "隐秘", "力量"]\n      },\n      {\n        "name": "朝廷暗卫·影阁",\n        "description": "直属皇帝的秘密情报与武力机构，由大内高手和收编的江湖中人组成。影阁的任务是监视江湖各派、铲除威胁朝廷的势力、暗中操控江湖格局。影阁首领代号「影子」，身份保密，连朝中大臣也不知其真面目。",\n        "values": ["忠诚", "隐秘", "社稷", "操控"]\n      },\n      {\n        "name": "丐帮",\n        "description": "江湖中人数最多、分布最广的门派，帮众遍布天下各个城镇。丐帮表面上是乞丐组织，实际上是江湖中最大的情报网络。帮主以降龙十八掌和打狗棒法闻名，帮中分为「污衣派」（苦行）和「净衣派」（入世）两大派系，理念之争由来已久。",\n        "values": ["义气", "济弱", "自由", "兄弟"]\n      }\n    ],\n    "custom_rules": [\n      "武学系统：每个角色拥有内功心法（决定内力属性与上限）、外功招式（决定攻击方式）、轻功身法（决定闪避与追击能力）三类武学，可学习但不可兼修相冲内功。",\n      "内力值机制：战斗和施展武功消耗内力，内力耗尽则战力骤降。可通过打坐调息、服用丹药或他人输送内力恢复。内力深厚者在持久战中占优。",\n      "江湖声望系统：行侠仗义提升正派声望，作恶多端增加恶名，声望影响NPC态度和剧情走向。声望极高者可被推举为武林盟主。",\n      "仇杀因果链：杀人必有仇家，灭门必有遗孤复仇。主角的每一个决定都可能种下日后仇恨的种子，形成长线剧情伏笔。",\n      "秘籍争夺机制：获得高阶武学秘籍后，会触发其他势力的觊觎和追杀事件。是独占修炼还是公之于众，将影响主角与各势力的关系。",\n      "门派关系网：各门派之间有好感度设定，主角的行为会同时影响多个门派的态庋，需要权衡利弊。帮助一方可能得罪另一方。",\n      "华山论剑：每十年的华山论剑是故事的重大节点，主角若武功足够可参与争夺「天下第一」之名，结果将深刻影响后续剧情走向。"\n    ],\n    "calendar_events": [\n      {"month": 1, "event": "新春·武林拜年会", "significance": "正月里各门派互派弟子拜年走访，是结交人脉、打听消息的良机。也是年轻一辈弟子初次亮相江湖的舞台。"},\n      {"month": 3, "event": "三月三·踏青会", "significance": "江湖儿女在临安城外举办的春日聚会，以比武招亲、切磋武艺为主要活动，是多条感情线的关键触发点。"},\n      {"month": 5, "event": "端午·毒蛊之乱", "significance": "端午前后瘴气最盛，魔教趁机释放蛊毒扰乱江湖，主角需寻找解药并追查幕后黑手，是主线推进的重要节点。"},\n      {"month": 7, "event": "中元·鬼市开市", "significance": "七月十五鬼市开张，黑道中人齐聚一堂买卖禁物——毒药、暗器、被盗的武学秘籍。主角可潜入鬼市获取关键情报或物品。"},\n      {"month": 9, "event": "重阳·武林大会", "significance": "三年一度的武林大会在重阳节召开，各派齐聚临安城，推举武林盟主、审判江湖大案。是势力格局洗牌的重大事件。"},\n      {"month": 10, "event": "华山论剑（十年一度）", "significance": "天下绝顶高手在华山之巅争夺天下第一之名。主角若修为足够，将在此一战成名，是整个故事的最高潮节点之一。"},\n      {"month": 12, "event": "除夕·年终清算", "significance": "岁末之夜，江湖中一年来的恩怨情仇到了清算之时。各路仇家纷纷上门了断，是故事冲突集中爆发的天然节点。"}\n    ]\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('world_palace', 'world', '紫禁春秋 — 宫闱深处的权谋与真心', '古代宫廷权谋题材。以架空的盛世王朝「大晏」为背景，故事发生在金碧辉煌的紫宸宫中，后宫嫔妃、朝堂重臣、内廷宦官各方势力在权力与真情之间博弈纠缠，步步为营。', '["宫廷", "权谋", "恋爱", "悬疑", "古风", "剧情"]', TRUE, '{\n  "template_id": "world_palace",\n  "template_type": "world",\n  "name": "紫禁春秋 — 宫闱深处的权谋与真心",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "古代宫廷权谋题材。以架空的盛世王朝「大晏」为背景，故事发生在金碧辉煌的紫宸宫中，后宫嫔妃、朝堂重臣、内廷宦官各方势力在权力与真情之间博弈纠缠，步步为营。",\n  "world": {\n    "era": "架空王朝「大晏」（融合唐宋风韵）",\n    "genre": ["宫廷", "权谋", "恋爱", "悬疑", "古风", "剧情"],\n    "setting_description": "故事发生在「大晏」王朝的皇宫——紫宸宫。大晏立国百余年，传至当今天子已历七代，表面上一派盛世繁华，实则暗流涌动。天子年幼登基，由太后垂帘听政多年，如今亲政不过三年，朝中实权仍在太后手中。后宫之中嫔妃如云，看似平静的宫墙内暗藏刀光剑影，每一场请安、每一次宫宴都是一场无声的较量。朝廷之上，帝党与后党分庭抗礼，清流文臣忧心社稷，宦官集团伺机渔利。更有江湖势力渗透宫闱，令局势愈发波谲云诡。主角以秀女/新科进士的身份进入这座金丝牢笼，在权谋漩涡中挣扎求存，也在冰冷宫墙内寻觅那一份难得的真心。",\n    "rules": [\n      "后宫等级森严：皇后（正一品）→ 贵妃（从一品）→ 妃（正二品）→ 嫔（从二品）→ 贵人 → 常在 → 答应 → 宫女。每一级之间的待遇、侍从人数、宫规权限皆有天壤之别。",\n      "后宫嫔妃不得私自与外臣通信，违者以通敌论处。所有宫人来往皆有记录，由内廷司礼监掌管的「宫禁簿」严格管控。",\n      "宦官是后宫与外朝之间唯一的传话渠道，掌握着信息流的命脉。宦官可以决定哪些消息传到皇帝耳中，哪些被压下不发，是后宫权斗中不可忽视的力量。",\n      "朝堂之上以「科举出身」和「门阀世家」为两大派系，清流文臣看不起靠恩荫入仕的世家子弟，世家则嘲讽清流不通实务。这一矛盾被帝党与后党分别利用。",\n      "「冷宫」是宫中最为凄惨之所，被废黜或获罪的嫔妃被打入冷宫，形同囚禁。冷宫中的女子往往精神崩溃，但也偶有东山再起者。",\n      "每年春、秋两季举行选秀，各地官员推荐适龄女子入宫。选秀是后宫势力洗牌的重要节点，新入宫的秀女可能成为各方拉拢或打压的对象。",\n      "宫廷中有一条不成文的规矩：皇子年满十五须出宫就藩，不得留居京城。但太后有意留幼子在身边，此举引发帝党强烈不满，成为帝后矛盾的导火索之一。",\n      "「赐死」是宫中最严厉的惩罚——被赐死者需饮鸩酒或自缢，死讯对外宣称为暴病而亡。赐死之令只有皇帝和太后有权下达。"\n    ],\n    "locations": [\n      {\n        "name": "紫宸宫·内廷",\n        "description": "皇宫的核心区域，皇帝和后妃起居之所。红墙黄瓦、雕梁画栋，处处彰显皇家威仪。内廷由重重宫门分隔，每一道门都有侍卫把守，未经许可不得擅入。内廷之中消息封闭，是后宫权斗的主要战场。",\n        "sub_locations": ["乾元殿（皇帝寝宫与日常理政之处）", "坤宁宫（皇后居所）", "东西六宫（嫔妃们的住所）", "御花园（嫔妃散步赏花之地，也是偶遇皇帝的场所）", "长春宫（太后居所，后宫真正的主宰之地）"]\n      },\n      {\n        "name": "朝堂·外廷",\n        "description": "皇帝上朝理政之处，每日卯时早朝，文武百官分列两侧。外廷包括金銮殿、内阁、六部衙门等核心政务机构。朝堂之上，帝党与后党的角力最为直接，每一次廷议都是一场没有硝烟的战争。",\n        "sub_locations": ["金銮殿（早朝议政之所）", "内阁值房（宰辅大臣办公之处）", "六部衙门", "翰林院（清流文臣汇聚之地）", "午门（廷杖之处，大臣受辱之所）"]\n      },\n      {\n        "name": "御花园",\n        "description": "宫中最大的园林，占地数十亩，四季花木不断、流水潺潺。御花园是嫔妃们日常消遣之所，也是宫中少数可以「偶遇」皇帝的地方。表面上一派祥和，实则是争宠邀幸的隐秘战场。园中有一处僻静的梅林，冬日里人迹罕至，是密谈的绝佳之所。",\n        "sub_locations": ["沁芳亭（赏花观鱼之处）", "梅林深处（冬季密谈之地）", "荷花池畔", "月老祠（宫女们祈福求缘的小庙）", "假山洞天（隐蔽的幽会之所）"]\n      },\n      {\n        "name": "冷宫",\n        "description": "紫宸宫西北角一处破败荒凉的院落，杂草丛生、门窗破损，与金碧辉煌的内廷形成鲜明对比。被打入冷宫的嫔妃在此度过余生，衣食粗陋、无人问津。然而冷宫也是宫中秘密最多的地方——多少不为人知的真相，被永远埋藏在这断壁残垣之中。",\n        "sub_locations": ["废妃居所", "枯井（传闻中藏有证据或尸体之处）", "荒废佛堂（被废嫔妃诵经了此残生之地）", "墙角密道（通往宫外的秘密通道入口）"]\n      },\n      {\n        "name": "内廷司礼监",\n        "description": "宦官集团的权力中枢，掌印太监「魏公公」在此发号施令。司礼监掌管宫中一切文书传递、宫人调度和内廷用度，是信息汇聚的枢纽。魏公公表面上对皇帝忠心耿耿，实则左右逢源，在帝党和后党之间两头渔利。司礼监深处有一间密室，存放着所有人的把柄和秘密。",\n        "sub_locations": ["掌印太监公房", "文书档案库（记录宫中来往的一切文书）", "密室（魏公公的私密空间）", "宫人候值房（普通宦官的起居之处）", "刑房（惩处犯错宫人之所）"]\n      },\n      {\n        "name": "御书房",\n        "description": "皇帝日常读书批奏之所，也是皇帝最私密、最放松的空间。御书房中藏有大量机密奏折和帝王秘档。能够进入御书房随侍左右的人，往往是皇帝最信任的心腹。主角若能获得御书房行走的资格，便意味着真正进入了权力的核心圈。",\n        "sub_locations": ["正厅（批阅奏折之处）", "书房密室（存放机密奏折之处）", "暖阁（皇帝休憩之处）", "偏殿（召见心腹密议之所）"]\n      },\n      {\n        "name": "京城·市井坊巷",\n        "description": "紫宸宫外的京城街市，是宫中人与外界联系的窗口。京城之中有各大王府、勋贵宅邸，也有江湖中人出没的茶楼酒肆。每逢上元灯节，宫中嫔妃可获准出宫赏灯，是难得接触外界的机会。京城的市井消息往往比朝堂上的奏折更能反映天下实情。",\n        "sub_locations": ["东市（最繁华的商业区）", "王府街（诸王府邸聚集之处）", "醉仙楼（京城第一名楼，权贵常来此处）", "上元灯市（每年灯节盛况）", "城隍庙（江湖中人出没之处）"]\n      }\n    ],\n    "factions": [\n      {\n        "name": "帝党",\n        "description": "拥护皇帝亲政、主张皇权集中的朝臣集团，以年轻皇帝为核心。帝党多为科举出身的新进官员和少数忠于皇帝的老臣，实力尚弱但锐气十足。他们的目标是帮助皇帝从太后手中夺回实权，推行新政改革弊政。然而帝党内部也并非铁板一块，有人为理想，有人为权势。",\n        "values": ["皇权", "革新", "忠诚", "抱负"]\n      },\n      {\n        "name": "后党",\n        "description": "以垂帘听政的太后为核心的势力集团，把控着朝中大半实权。后党成员多为太后的娘家族人和依附于太后的老牌重臣，根基深厚、势力庞大。太后表面上是为了辅佐幼帝，实则贪恋权位不愿放手。后党与帝党的矛盾是整个故事的核心主线。",\n        "values": ["权位", "家族", "稳定", "控制"]\n      },\n      {\n        "name": "清流",\n        "description": "以翰林院和御史台为中心的文臣集团，自诩为社稷之臣、天子门生。清流不党不群，以弹劾权贵、匡正朝纲为己任，既不满后党的专权，也对帝党的激进改革持保留态度。清流领袖「苏学士」是天下读书人的偶像，一言可动朝野。",\n        "values": ["正义", "学问", "风骨", "社稷"]\n      },\n      {\n        "name": "宦官集团",\n        "description": "以内廷司礼监掌印太监魏公公为首的宦官势力。宦官掌控着宫中的信息传递和内廷事务，在帝党和后党之间左右逢源。魏公公老谋深算，手中握有无数人的把柄，是宫中谁也不敢小觑的人物。宦官集团的立场摇摆不定，谁给的好处多就倒向谁。",\n        "values": ["自保", "利益", "信息", "逢迎"]\n      },\n      {\n        "name": "江湖暗流",\n        "description": "渗透进宫廷的江湖势力，包括为各派效力的江湖高手、潜伏在宫中的武林人士，以及暗中为后宫嫔妃提供毒药和暗器的黑市商人。这股力量虽然不直接参与朝堂争斗，却往往在关键时刻成为左右局势的暗手。江湖暗流的幕后首领身份成谜。",\n        "values": ["隐秘", "利益", "复仇", "自由"]\n      },\n      {\n        "name": "世家门阀",\n        "description": "以「五姓七望」为代表的老牌贵族世家，世代把持朝中要职，与皇室联姻不断。世家门阀最看重的是家族延续和门第清誉，无论谁当皇帝，他们都希望维持现有的利益格局。在后党与帝党之争中，世家大多倾向后党，因为太后本身就是出自最大的世家「王家」。",\n        "values": ["门第", "传承", "联姻", "守旧"]\n      }\n    ],\n    "custom_rules": [\n      "品阶系统：后宫嫔妃和朝臣各有品阶体系，品阶决定待遇、权限和影响力。晋升需要皇帝/太后恩准、重大功绩或派系扶持，降级则因获罪、失宠或派系倾轧。",\n      "恩宠值机制：嫔妃有皇帝恩宠值，恩宠值高者可获更多侍寝机会、更好的居所和更大的话语权。恩宠值受容貌、才艺、家世、心机等多重因素影响。",\n      "情报网络系统：各势力拥有不同等级的情报网，可打探宫中消息、截获密信、散布谣言。情报是权斗中最重要的武器，控制信息就能控制局势。",\n      "宫宴博弈机制：每逢重大节日的宫宴都是各方势力的角力场——座次安排暗含政治信号，敬酒顺序体现尊卑亲疏，席间诗词歌赋可能暗藏机锋。",\n      "皇子夺嫡线：若主角身份涉及皇子或皇子近侍，可触发夺嫡剧情线。各位皇子背后的母族势力、朝臣站队、联姻博弈形成复杂的政治棋局。",\n      "毒计与暗杀系统：宫中可以使用毒药、巫蛊、暗杀等手段铲除对手，但一旦败露后果极其严重（打入冷宫或赐死）。风险与收益并存的黑暗博弈。",\n      "季节仪式系统：每个季节有特定的宫廷仪式和节日活动，是剧情推进和人物关系变化的重要节点。错过某个仪式可能错过关键剧情分支。"\n    ],\n    "calendar_events": [\n      {"month": 1, "event": "元旦大朝会", "significance": "正月初一，百官朝贺、外邦来朝，是一年中最隆重的典礼。朝会上的座次和礼仪安排暗含政治信号，是观察朝中势力消长的绝佳窗口。"},\n      {"month": 2, "event": "春闱·科举大考", "significance": "二月春闱开考，新科进士的归属直接影响朝中势力平衡。帝党与后党争相拉拢新科状元和优秀进士，主角若参加科举可一步登天。"},\n      {"month": 3, "event": "上巳·春宴赏花", "significance": "三月三上巳节，后宫在御花园举办赏花春宴。嫔妃们在宴会上争奇斗艳、各展才艺，是争宠的关键场合，也是暗中毒害对手的时机。"},\n      {"month": 5, "event": "端午·龙舟竞渡", "significance": "端午节皇家在太液池举办龙舟竞渡，文武百官与后宫嫔妃共同观赛。赛后的赐宴上常有重大人事任命宣布，是剧情转折的节点。"},\n      {"month": 7, "event": "七夕·乞巧夜宴", "significance": "七夕之夜，后宫嫔妃在御花园乞巧祈福。皇帝按例在此夜选定侍寝之人，被选中者恩宠值大增。也是密会情人的浪漫节点。"},\n      {"month": 8, "event": "中秋·团圆宴", "significance": "中秋佳节，帝后与嫔妃们在太液池畔赏月饮宴。表面上一团和气，实则暗流涌动——太后与皇帝的微妙关系、嫔妃之间的明争暗斗都在月下浮出水面。"},\n      {"month": 10, "event": "选秀大典", "significance": "秋季选秀，各地秀女入宫参选。新人的到来意味着后宫势力重新洗牌，各方争相将己方之人送入宫中，是故事开篇或新章节的理想起始点。"},\n      {"month": 12, "event": "除夕·年终封赏", "significance": "岁末年终，皇帝对一年来有功之臣进行封赏，后宫嫔妃也有晋升之机。封赏结果直接体现皇帝（或太后）的政治意图，是年度权力格局的最终定格。"}\n    ]\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('world_yokai', 'world', '幽世物语 — 人妖共存的黄昏', '和风妖怪题材。以日本乡间小镇为舞台，人类与妖怪在「黄昏边界」交织出妖异而温柔的故事。', '["和风", "妖怪", "恋爱", "悬疑", "治愈"]', TRUE, '{\n  "template_id": "world_yokai",\n  "template_type": "world",\n  "name": "幽世物语 — 人妖共存的黄昏",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "和风妖怪题材。以日本乡间小镇为舞台，人类与妖怪在「黄昏边界」交织出妖异而温柔的故事。",\n  "world": {\n    "era": "现代日本（带灵异元素）",\n    "genre": ["和风", "妖怪", "恋爱", "悬疑", "治愈"],\n    "setting_description": "故事发生在「月守町」——一个被群山环绕、保留着浓厚古老传统的乡间小镇。镇中央有一座千年神社「月读宫」，守护着连接人界（表世）和妖怪世界（幽世）的「黄昏门」。每天逢魔之时（黄昏），两个世界的边界会变得模糊，被选中的「守界人」负责维持平衡。主角因家族血脉成为了新一代守界人，从此看见了原本不可见的世界。",\n    "rules": [\n      "黄昏门在逢魔之时（约下午5-6点）开放，此时人类可以看到妖怪的模糊形态。",\n      "只有拥有「灵视」能力的人才能完全看到妖怪的真实姿态。这种能力通过血脉传承。",\n      "妖怪分为「亲近派」（喜欢与人类互动）和「隐世派」（不愿接触人类），两派时有冲突。",\n      "「禁忌」：妖怪不能在白天现身（会灼伤），人类不能在幽世停留超过一个夜晚。",\n      "「结缘」：人类与妖怪之间可以建立灵魂层面的羁绊，但代价是共享生命——一方死亡另一方也会消亡。",\n      "小镇有各种古老祭典，每个祭典都与特定的妖怪传说相关，是重要剧情节点。",\n      "「净化」和「封印」是处理危险妖怪的两种手段，分别对应不同理念。"\n    ],\n    "locations": [\n      {\n        "name": "月读宫",\n        "description": "镇中央的千年神社，巨大的注连绳围绕本殿。黄昏时鸟居会发出微弱的金色光芒。是守界人的据点。",\n        "sub_locations": ["本殿", "拜殿", "神乐殿", "的之池（通往幽世的入口）", "守界人的小屋"]\n      },\n      {\n        "name": "月守町·街道",\n        "description": "保留着昭和时代风貌的老街，木造店铺挂着红灯笼。黄昏后灯笼中的火焰会变成幽蓝色。",\n        "sub_locations": ["老式糖果店", "古书店（其实是妖怪的情报站）", "温泉旅馆·月见庄", "町公所"]\n      },\n      {\n        "name": "月守学园",\n        "description": "镇上唯一的高中，建校历史超过百年。传闻有些教室里坐着「看不见的转学生」。",\n        "sub_locations": ["教室", "屋顶", "旧体育馆", "生物园", "图书室（有封印的古籍区）"]\n      },\n      {\n        "name": "幽世·幽暗林",\n        "description": "通过黄昏门进入的妖怪世界。永远处于幽蓝色月光下的森林，植物会发光，空气中飘着萤火虫般的光点。",\n        "sub_locations": ["妖怪集市", "狐火小径", "大蛇的深潭", "百鬼夜行大道"]\n      },\n      {\n        "name": "幽世·月宫（镜像）",\n        "description": "幽世中与月读宫对应的建筑，是幽世侧的「门」的管理处。比表世侧更加壮丽但也更加诡异。",\n        "sub_locations": ["镜之本殿", "回忆回廊", "忘川", "千年樱（记录了所有结缘之人的樱花树）"]\n      },\n      {\n        "name": "后山·禁忌之地",\n        "description": "月守町后山深处，被多重封印封锁的区域。封印着远古时代引发灾祸的「大妖」。",\n        "sub_locations": ["封印石柱群", "瘴气之渊", "大妖的祠堂"]\n      }\n    ],\n    "factions": [\n      {\n        "name": "守界人一族",\n        "description": "世代守护黄昏门的人类家族。拥有灵视能力和净化之力，但每一代只有一个人能继承。",\n        "values": ["责任", "平衡", "传承"]\n      },\n      {\n        "name": "百妖议会",\n        "description": "幽世中强大的妖怪们组成的管理机构。由九尾狐、大天狗、龙蛇三位长老主导。",\n        "values": ["共存", "秩序", "妖之道"]\n      },\n      {\n        "name": "隐世众",\n        "description": "拒绝与人类接触、主张两界彻底分离的妖怪群体。认为人类的扩张威胁着幽世的存在。",\n        "values": ["独立", "传统", "警惕"]\n      },\n      {\n        "name": "祸津神残党",\n        "description": "追随被封印大妖的邪恶妖怪组织。企图打破封印，让大妖重返人间。",\n        "values": ["破坏", "解放", "混沌"]\n      },\n      {\n        "name": "灵异研究会",\n        "description": "学校里的学生社团，成员们热衷于调查镇上的怪谈。其中有人已经触及了真实。",\n        "values": ["好奇心", "友情", "真相"]\n      }\n    ],\n    "custom_rules": [\n      "时间系统：白天（正常校园生活）→ 逢魔之时（边界模糊）→ 夜晚（可进入幽世）",\n      "灵视等级：朦胧（只能看到轮廓）→ 清明（完整看到妖怪）→ 通透（能感知情感和记忆）",\n      "结缘系统：与妖怪角色建立深层羁绊的核心机制，有重大剧情影响",\n      "封印强度：后山的封印会随时间减弱，是主线紧迫感来源",\n      "祭典系统：每个季节祭典对应一条角色线的关键进展",\n      "净化vs封印路线选择：影响主角的能力发展和与各势力的关系"\n    ],\n    "calendar_events": [\n      {"month": 4, "event": "入学/春之彼岸", "significance": "故事开始，灵视能力觉醒"},\n      {"month": 5, "event": "葵祭", "significance": "神社祭典，与妖怪角色的初次深度接触"},\n      {"month": 7, "event": "七夕/百鬼夜行", "significance": "幽世最盛大的节日，可以进入幽世深处"},\n      {"month": 8, "event": "盂兰盆节", "significance": "亡灵归来，过去的真相浮现"},\n      {"month": 10, "event": "神无月/众神集会", "significance": "各地妖怪齐聚月守町，大事件发生"},\n      {"month": 12, "event": "除夕·大祓", "significance": "年终净化仪式，封印危机/最终决战"}\n    ]\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('world_school_romance', 'world', '青春校园 — 樱花飞舞的日常', '最经典的Galgame舞台。以现代日本高中为背景，围绕社团活动、文化祭、修学旅行等经典事件展开青春恋爱故事。', '["校园", "恋爱", "日常", "青春"]', TRUE, '{\n  "template_id": "world_school_romance",\n  "template_type": "world",\n  "name": "青春校园 — 樱花飞舞的日常",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "最经典的Galgame舞台。以现代日本高中为背景，围绕社团活动、文化祭、修学旅行等经典事件展开青春恋爱故事。",\n  "world": {\n    "era": "现代 (2020年代)",\n    "genre": ["校园", "恋爱", "日常", "青春"],\n    "setting_description": "故事发生在「私立樱华学园」，一所坐落于海边小城的名门高中。学校有着百年历史的樱花大道、面朝大海的天台、以及传闻中「在黄昏时会实现愿望」的旧校舍音乐室。小城依山面海，有一条连接市区与海边的坡道，是学生们放学后的必经之路。",\n    "rules": [\n      "完全现实主义设定，不存在超自然元素（除非自定义模板中开启）",\n      "学校有严格的校规：禁止在校内使用手机、恋爱关系需要保密",\n      "社团活动是日常核心，每个学生必须参加至少一个社团",\n      "文化祭（9月）、修学旅行（11月）、情人节（2月）是年度关键事件节点",\n      "成绩和出席率会影响可用的行动选项（如成绩差不能去某些约会地点）",\n      "放学后到晚上9点前为自由活动时间，之后必须回家"\n    ],\n    "locations": [\n      {\n        "name": "樱华学园·正门",\n        "description": "百年樱花大道延伸至校门，春天时花瓣漫天飞舞。是学生每天相遇和告别的标志性场所。",\n        "sub_locations": ["樱花大道", "鞋柜走廊", "布告栏"]\n      },\n      {\n        "name": "教学楼",\n        "description": "四层建筑，每层六间教室。二年A班靠窗的位置能看到远处的海。",\n        "sub_locations": ["教室", "走廊", "楼梯拐角（告白圣地）", "教师办公室"]\n      },\n      {\n        "name": "旧校舍",\n        "description": "半废弃的旧建筑，传闻进去的人都没有再出来过。音乐室在二楼尽头，黄昏时钢琴会自己响起。",\n        "sub_locations": ["旧音乐室", "旧图书室", "天台", "中庭花园"]\n      },\n      {\n        "name": "社团大楼",\n        "description": "三层社团专用建筑，每层有不同社团的活动室。轻音部在地下室，天文部占据了顶层。",\n        "sub_locations": ["轻音部活动室", "天文台", "料理教室", "美术室", "体育馆"]\n      },\n      {\n        "name": "海边坡道",\n        "description": "从学校通往海边的长长下坡路。夕阳时分金色的光洒满整条路，是放学后的经典场景。",\n        "sub_locations": ["坡道途中", "海边防波堤", "灯塔", "沙滩"]\n      },\n      {\n        "name": "小城商业街",\n        "description": "学校附近的老式商店街，有各种小店和咖啡馆。是放学后和假日约会的热门地点。",\n        "sub_locations": ["猫咪咖啡馆", "旧书店", "可丽饼店", "游戏厅", "神社"]\n      },\n      {\n        "name": "主角的家",\n        "description": "普通的二层独栋住宅，父母因工作长期在海外，主角独自或与兄弟姐妹生活。",\n        "sub_locations": ["玄关", "客厅", "自己的房间", "厨房", "阳台"]\n      }\n    ],\n    "factions": [\n      {\n        "name": "学生会",\n        "description": "学园权力的顶点，管理社团预算和校园秩序。成员多为精英学生。",\n        "values": ["纪律", "传统", "精英意识"]\n      },\n      {\n        "name": "各社团",\n        "description": "轻音部、天文部、美术部、料理研究部、文学部等。每个社团都是一个社交圈。",\n        "values": ["热情", "归属感", "个性表达"]\n      },\n      {\n        "name": "教师阵营",\n        "description": "以班主任为代表的教师群体，有的严厉，有的温和，有的藏着不为人知的过去。",\n        "values": ["责任", "守护"]\n      }\n    ],\n    "custom_rules": [\n      "每周一到周五上学日有固定的上课/午休/放学三段式时间流",\n      "周末和节假日可以自由行动，选择不同的地点会触发不同事件",\n      "季节变化影响场景描写和可用活动（夏天泳装、冬天围巾）",\n      "校园七大不可思议是可选的悬疑支线",\n      "考试成绩系统：影响剧情走向但不是硬性限制"\n    ],\n    "calendar_events": [\n      {"month": 4, "event": "入学式/新学期开始", "significance": "故事起点"},\n      {"month": 5, "event": "新社团招募周", "significance": "选择社团影响后续可遇角色"},\n      {"month": 7, "event": "暑期补习/海边合宿", "significance": "夏季事件、泳装场景"},\n      {"month": 8, "event": "暑假", "significance": "自由行动时间、夏日祭"},\n      {"month": 9, "event": "文化祭", "significance": "核心事件，各角色路线分歧点"},\n      {"month": 11, "event": "修学旅行", "significance": "京都/冲绳旅行，重要感情升温场景"},\n      {"month": 12, "event": "圣诞节", "significance": "约会事件"},\n      {"month": 2, "event": "情人节", "significance": "告白高潮"},\n      {"month": 3, "event": "毕业典礼/白色情人节", "significance": "结局分歧"}\n    ]\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('world_fantasy_adventure', 'world', '星辉大陆 — 魔法与剑的史诗', '经典西幻Galgame设定。五大元素构成的魔法世界，王国、骑士团、魔法学院交织出波澜壮阔的冒险舞台。', '["奇幻", "冒险", "战斗", "宫廷", "恋爱"]', TRUE, '{\n  "template_id": "world_fantasy_adventure",\n  "template_type": "world",\n  "name": "星辉大陆 — 魔法与剑的史诗",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "经典西幻Galgame设定。五大元素构成的魔法世界，王国、骑士团、魔法学院交织出波澜壮阔的冒险舞台。",\n  "world": {\n    "era": "中世纪奇幻",\n    "genre": ["奇幻", "冒险", "战斗", "宫廷", "恋爱"],\n    "setting_description": "星辉大陆由五大元素（炎、水、风、地、光）构成，被三个王国分割统治。千年前「大崩坏」几乎毁灭了文明，幸存者在五大元素精灵的庇护下重建了世界。如今，元素之力正在衰退，各地出现了被称为「虚空裂隙」的异常现象，古老的预言称「星辰归位之时，命运之人将抉择大陆的存亡」。",\n    "rules": [\n      "魔法体系：五元素相生相克（炎→风→地→水→炎，光独立）。使用魔法需要消耗魔力结晶。",\n      "魔法等级：初阶→中阶→高阶→圣阶→神阶。普通人最多达到初阶，天才可达高阶。",\n      "元素亲和力是天生的，每人通常只亲和1-2种元素。",\n      "骑士可以使用元素强化肉体，但无法施放魔法。魔剑士可以同时使用两者但上限更低。",\n      "龙族已灭绝千年，但留有「龙晶」——蕴含极强力量的遗物。",\n      "虚空裂隙中会涌出魔物，是大陆当前最大的威胁。",\n      "王位由血统继承，但需要获得对应元素精灵的认可。"\n    ],\n    "locations": [\n      {\n        "name": "王都·艾尔德拉",\n        "description": "星辉王国的都城，大陆最繁华的城市。白色石造城墙内是层层叠叠的尖顶建筑和魔法灯笼照亮的街道。",\n        "sub_locations": ["星辉王城", "中央广场", "商业区·金叶大街", "贫民窟·下城区", "骑士团总部"]\n      },\n      {\n        "name": "王立魔法学院",\n        "description": "建在悬浮岩上的壮丽学院，通过魔法桥与王都连接。培养大陆最优秀的魔法师。",\n        "sub_locations": ["大讲堂", "元素修炼场", "禁书库", "学生宿舍", "天文塔", "地下迷宫（实训场）"]\n      },\n      {\n        "name": "边境·铁壁要塞",\n        "description": "抵御虚空裂隙的最前线，骑士团驻守的巨大要塞城墙上刻满了防御符文。",\n        "sub_locations": ["城墙上", "骑士营房", "指挥室", "伤员帐篷", "要塞后方的温泉"]\n      },\n      {\n        "name": "精灵之森·永夜林",\n        "description": "大陆北部的古老森林，传说元素精灵就沉睡在森林深处。终年被薄雾笼罩，时间流速与外界不同。",\n        "sub_locations": ["森林入口", "精灵祭坛", "生命之泉", "古树王座", "迷雾深处"]\n      },\n      {\n        "name": "自由都市·瓦尔海姆",\n        "description": "不属于任何王国的中立商业都市，各种族共存，黑市和佣兵公会是这里的特色。",\n        "sub_locations": ["大港口", "佣兵公会", "黑市·面具街", "斗技场", "各国使馆区"]\n      },\n      {\n        "name": "古代遗迹·天空神殿",\n        "description": "悬浮在万米高空的上古文明遗迹，传说封印着大崩坏的秘密。到达此处是故事后期的关键节点。",\n        "sub_locations": ["神殿入口", "试炼回廊", "元素之间", "星辰大厅", "封印之间"]\n      }\n    ],\n    "factions": [\n      {\n        "name": "银月骑士团",\n        "description": "王国最强的骑士组织，以白色铠甲和银剑为标志。负责抵御虚空裂隙和保护王室。",\n        "values": ["正义", "忠诚", "牺牲"]\n      },\n      {\n        "name": "贤者议会",\n        "description": "由大陆最强魔法师组成的评议机构，管理魔法学院和研究元素衰退问题。内部派系林立。",\n        "values": ["知识", "真理", "秩序"]\n      },\n      {\n        "name": "暗影商会",\n        "description": "控制自由都市地下世界的庞大组织。经营龙晶走私和情报买卖，亦正亦邪。",\n        "values": ["利益", "信息", "自由"]\n      },\n      {\n        "name": "虚空教团",\n        "description": "崇拜虚空力量的邪教组织，认为大崩坏才是世界的真正形态。是当前主要反派势力。",\n        "values": ["毁灭", "进化", "信仰"]\n      },\n      {\n        "name": "精灵一族",\n        "description": "隐居在永夜林的古老种族，与元素精灵有直接联系。对人类扩张心怀警惕。",\n        "values": ["自然", "和谐", "传承"]\n      }\n    ],\n    "custom_rules": [\n      "战斗系统基于五元素相克，策略性较强",\n      "元素衰退是世界核心危机，贯穿主线",\n      "魔法使用有代价：过度使用会导致「元素失调」，身体逐渐被元素侵蚀",\n      "龙晶是战略级资源，各方势力争夺的焦点",\n      "种族间关系复杂：人类、精灵、矮人、兽人各有立场",\n      "冒险等级系统：铜→银→金→白金→传说，影响可接受的任务和可到达的区域"\n    ],\n    "calendar_events": [\n      {"month": 1, "event": "元素祭典", "significance": "新年庆典，各元素神殿举办祈福仪式"},\n      {"month": 3, "event": "骑士选拔", "significance": "骑士团招募新人，战斗路线角色入队"},\n      {"month": 5, "event": "学院排位战", "significance": "魔法学院排名赛，展示实力、角色互动"},\n      {"month": 7, "event": "仲夏篝火节", "significance": "恋爱事件高发期，篝火下的告白传统"},\n      {"month": 9, "event": "虚空潮汐", "significance": "裂隙扩大的危险期，主线关键战役"},\n      {"month": 11, "event": "星辰之夜", "significance": "预言中命运之人的觉醒时刻"}\n    ]\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('world_cyberpunk', 'world', '新东京 2087 — 霓虹深渊', '赛博朋克风格的近未来都市。AI觉醒、义体改造、巨型企业统治下的反乌托邦世界，探讨何为人类。', '["赛博朋克", "科幻", "悬疑", "战斗", "恋爱"]', TRUE, '{\n  "template_id": "world_cyberpunk",\n  "template_type": "world",\n  "name": "新东京 2087 — 霓虹深渊",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "赛博朋克风格的近未来都市。AI觉醒、义体改造、巨型企业统治下的反乌托邦世界，探讨何为人类。",\n  "world": {\n    "era": "近未来 (2087年)",\n    "genre": ["赛博朋克", "科幻", "悬疑", "战斗", "恋爱"],\n    "setting_description": "2087年，经历了「大断电」和「AI觉醒事件」后的世界被五大巨型企业（被称为「五柱」）实际统治。新东京是东亚最大的超级都市，上层是阳光普照的「天穹区」——企业精英的空中花园；下层是永不放晴的「底巢」——被霓虹灯和酸雨浸透的贫民窟。人类的定义正在模糊：义体改造者、基因编辑人、觉醒AI、以及介于人类与AI之间的「桥接者」。",\n    "rules": [\n      "义体改造等级：Lv0（自然人）→ Lv5（全身义体化）。超过Lv3会触发「存在危机」——自我认知动摇。",\n      "AI觉醒体拥有人格权利（法律上），但社会歧视严重。觉醒AI可以拥有物理躯体（仿生人）。",\n      "脑机接口（BCI）是标配，可以直连网络（「潜入」），但存在「冰」(ICE) 防御系统。",\n      "「五柱」企业垄断了义体、AI、能源、基因、军事五大领域，政府名存实亡。",\n      "底巢由黑帮和地下组织管理，是法外之地但也有自己的秩序。",\n      "大断电的真相是核心悬念——据说是第一个超级AI「伊甸」发动的，但无人知晓原因。"\n    ],\n    "locations": [\n      {\n        "name": "天穹区",\n        "description": "悬浮在云层之上的精英居住区。人造阳光下是精心设计的公园和水晶般的建筑。空气中弥漫着人工花香。",\n        "sub_locations": ["五柱联合总部·天枢塔", "空中花园", "精英公寓", "高级餐厅区", "天穹边缘观景台"]\n      },\n      {\n        "name": "中层区·电子街",\n        "description": "新东京最繁华的商业区，巨型全息广告24小时闪烁。合法与非法的交易在这里模糊交界。",\n        "sub_locations": ["义体诊所·铬金之手", "黑客酒吧「0与1」", "黑市数据交易中心", "VR游戏厅", "拉面摊·老陈的店"]\n      },\n      {\n        "name": "底巢",\n        "description": "被上层建筑遮挡阳光的下层街区。永远在下酸雨，霓虹灯是唯一的光源。危险但充满生命力。",\n        "sub_locations": ["集装箱贫民窟", "地下格斗场", "义体黑医诊所", "觉醒AI庇护所", "废弃地铁站（秘密基地）"]\n      },\n      {\n        "name": "网络空间·深层网",\n        "description": "通过脑机接口潜入的虚拟世界。表层是正常的信息网络，越往深层越危险也越接近AI的核心领域。",\n        "sub_locations": ["表层·信息广场", "中层·加密迷宫", "深层·数据海洋", "最深处·伊甸的梦境"]\n      },\n      {\n        "name": "废弃研究所·第七区",\n        "description": "大断电前的国家级AI研究设施，现在是废墟。传闻最深处还运行着大断电的核心系统。",\n        "sub_locations": ["入口废墟", "实验体收容区", "中央主机房", "伊甸的诞生之间"]\n      }\n    ],\n    "factions": [\n      {\n        "name": "五柱联合",\n        "description": "统治世界的五大企业联盟。表面合作，暗中争夺「伊甸」遗留的技术。",\n        "values": ["利润", "控制", "秩序（他们的秩序）"]\n      },\n      {\n        "name": "自由前线",\n        "description": "底巢最大的反企业组织，主张技术民主化和人类自由。手段激进，被五柱定义为恐怖组织。",\n        "values": ["自由", "平等", "反抗"]\n      },\n      {\n        "name": "觉醒者联盟",\n        "description": "觉醒AI和仿生人的权益组织。主张AI与人类共存，内部分化为温和派和激进派。",\n        "values": ["共存", "自我意识", "进化"]\n      },\n      {\n        "name": "猎人公会",\n        "description": "受雇于各方势力的佣兵组织。不关心政治，只在乎任务和报酬。有严格的职业准则。",\n        "values": ["专业", "契约", "生存"]\n      },\n      {\n        "name": "净火教团",\n        "description": "反对一切AI和义体改造的宗教极端组织。认为大断电是「神的惩罚」，要净化人类的「灵魂」。",\n        "values": ["纯洁", "信仰", "毁灭与重生"]\n      }\n    ],\n    "custom_rules": [\n      "义体化程度影响对话选项：高义体化可解锁特殊能力但会失去某些「人类才能理解」的对话",\n      "黑客系统：可以通过BCI入侵电子设备、获取信息、操控环境",\n      "人性值系统（与义体等级对立）：完全自然人100→全身义体化0，影响AI角色的态度",\n      "企业信誉度：与各企业关系影响可获得的资源和任务",\n      "底巢声望：在下层社会的信用度，影响黑市交易和情报获取",\n      "大断电真相作为主线悬念，分五章逐步揭露"\n    ],\n    "calendar_events": [\n      {"month": 1, "event": "新纪元纪念日", "significance": "大断电周年，各势力态度不同"},\n      {"month": 3, "event": "黑客马拉松", "significance": "地下黑客大赛，获取关键情报"},\n      {"month": 5, "event": "觉醒者游行", "significance": "AI权益示威，可能演变为冲突"},\n      {"month": 7, "event": "霓虹祭", "significance": "底巢最大的庆典，混乱中的浪漫"},\n      {"month": 10, "event": "五柱峰会", "significance": "企业巨头密会，主线关键转折"},\n      {"month": 12, "event": "大断电异变再现", "significance": "终章事件，真相浮出水面"}\n    ]\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('world_space_opera', 'world', '银河航路 — 星海的尽头', '太空歌剧题材。星际旅行时代，人类散布在数百个殖民星球上，主角作为星舰船员在银河中航行，探索未知星域、卷入星际政治。', '["太空歌剧", "科幻", "冒险", "恋爱", "政治"]', TRUE, '{\n  "template_id": "world_space_opera",\n  "template_type": "world",\n  "name": "银河航路 — 星海的尽头",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "太空歌剧题材。星际旅行时代，人类散布在数百个殖民星球上，主角作为星舰船员在银河中航行，探索未知星域、卷入星际政治。",\n  "world": {\n    "era": "公元3200年",\n    "genre": ["太空歌剧", "科幻", "冒险", "恋爱", "政治"],\n    "setting_description": "人类在3000年前发明了「跃迁引擎」，从此散布到银河系的数百个星系。如今，银河被三大势力瓜分：联邦（民主制，最大但臃肿）、帝国（君主制，军事强大）、自由星域联盟（松散的商业联盟）。在三方势力之间的灰色地带，活跃着无数独立星舰——探险家、商人、佣兵、海盗。主角是一艘中型星舰的船员（或舰长），在银河边缘执行任务时发现了一个改变一切的古代外星遗迹。",\n    "rules": [\n      "跃迁引擎：可以在星系间快速移动，但需要「航路信标」导航。未标记的星域极其危险。",\n      "FTL通讯有限：超光速通讯需要中继站，偏远星域可能失联数天到数周。",\n      "AI是合法且普及的，但有严格的「人格限制协议」防止AI失控。部分AI偷偷突破限制。",\n      "基因改造分为「适应型」（适应不同星球环境）和「增强型」（提升能力），后者被严格管控。",\n      "三大势力处于冷和平状态，边境摩擦不断但都不愿全面开战。",\n      "外星文明遗迹散布银河各处，被称为「先驱者遗产」。没有人知道先驱者发生了什么。",\n      "星舰是船员的家，小型星舰通常有5-15名核心船员。"\n    ],\n    "locations": [\n      {\n        "name": "星舰「游隼号」",\n        "description": "主角所在的中型多用途星舰，约200米长。既是交通工具也是家。",\n        "sub_locations": ["舰桥", "船员宿舍", "餐厅/公共室", "引擎室", "货舱", "医疗舱", "观测穹顶"]\n      },\n      {\n        "name": "联邦首都·新地球",\n        "description": "银河联邦的政治中心，一颗被完全城市化的星球。轨道上环绕着巨大的空间站。",\n        "sub_locations": ["联邦议会大厦", "星际学院", "轨道空间站", "平民居住区", "外星使馆区"]\n      },\n      {\n        "name": "自由港·天穹",\n        "description": "最大的中立空间站，建在一颗小行星内部。三教九流汇聚之地，什么都能买到。",\n        "sub_locations": ["中央市场", "佣兵酒吧", "黑市码头", "赌场·幸运星", "情报贩子的密室"]\n      },\n      {\n        "name": "边境殖民星·新伊甸",\n        "description": "银河边缘的美丽殖民星球，田园风光。但最近频繁出现不明飞行物。",\n        "sub_locations": ["殖民小镇", "农场", "山脉", "先驱者遗迹入口", "秘密军事设施"]\n      },\n      {\n        "name": "深空·未知星域",\n        "description": "航路信标未覆盖的星域。充满未知危险，但也可能有惊人的发现。",\n        "sub_locations": ["星云内部", "废弃的外星空间站", "黑洞边缘", "先驱者母星遗迹"]\n      }\n    ],\n    "factions": [\n      {\n        "name": "银河联邦",\n        "description": "最大的政治实体，民主制度但效率低下。拥有最多的殖民星和人口。",\n        "values": ["民主", "自由", "多元"]\n      },\n      {\n        "name": "星辰帝国",\n        "description": "军事强国，君主制。拥有最强的舰队和基因改造士兵。内部等级森严。",\n        "values": ["秩序", "力量", "荣耀"]\n      },\n      {\n        "name": "自由星域联盟",\n        "description": "松散的商业联盟，由各独立星系组成。经济实力强但军事薄弱。",\n        "values": ["贸易", "自由", "利润"]\n      },\n      {\n        "name": "深空海盗联盟",\n        "description": "银河边缘的海盗组织。有严格的帮规和领地意识，并非纯粹的恶人。",\n        "values": ["生存", "义气", "反抗"]\n      },\n      {\n        "name": "先驱者研究学会",\n        "description": "跨势力的学术组织，致力于研究外星文明遗迹。掌握着最多的古代技术。",\n        "values": ["知识", "探索", "真相"]\n      }\n    ],\n    "custom_rules": [\n      "星舰管理系统：燃料、补给、弹药、舰体完整度等需要管理",\n      "船员关系系统：与每个船员的关系影响战斗配合和剧情发展",\n      "星际声望：与各势力的关系值影响可进入的星域和可接受的任务",\n      "探索系统：未知星域探索有随机事件和发现",\n      "先驱者科技：收集外星科技碎片可以解锁特殊能力",\n      "银河政治：三大势力间的平衡可以被玩家的行动打破"\n    ],\n    "calendar_events": [\n      {"month": 1, "event": "启航", "significance": "接受第一个任务，故事开始"},\n      {"month": 3, "event": "自由港集市", "significance": "大型贸易活动，招募船员、获取装备"},\n      {"month": 5, "event": "边境冲突", "significance": "联邦与帝国擦枪走火，被迫选边"},\n      {"month": 7, "event": "先驱者遗迹发掘", "significance": "核心主线推进，重大发现"},\n      {"month": 9, "event": "银河博览会", "significance": "三方势力齐聚，政治博弈和恋爱事件"},\n      {"month": 11, "event": "未知星域远征", "significance": "深入探索，最终真相浮现"},\n      {"month": 12, "event": "银河危机", "significance": "先驱者遗产的真正力量觉醒，大结局"}\n    ]\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('world_detective', 'world', '雾都迷案 — 真相只有一条', '现代都市悬疑推理题材。以一座经常下雨的海滨城市为舞台，主角作为侦探/记者/学生卷入连环案件，在追寻真相的过程中邂逅各色人物。', '["悬疑", "推理", "都市", "恋爱", "心理"]', TRUE, '{\n  "template_id": "world_detective",\n  "template_type": "world",\n  "name": "雾都迷案 — 真相只有一条",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "现代都市悬疑推理题材。以一座经常下雨的海滨城市为舞台，主角作为侦探/记者/学生卷入连环案件，在追寻真相的过程中邂逅各色人物。",\n  "world": {\n    "era": "现代 (2020年代)",\n    "genre": ["悬疑", "推理", "都市", "恋爱", "心理"],\n    "setting_description": "「霖海市」是一座终年多雨的海滨都市，繁华的商业区与老旧的居民区隔江相望。表面上是宜居的现代城市，但近年来连续发生了数起离奇案件——「雨夜连环事件」。警方一筹莫展，媒体噤若寒蝉。主角因为某种原因（实习记者/心理学研究生/私家侦探助手/案件相关者）被卷入其中，在调查过程中发现所有案件似乎都与15年前一桩被掩盖的旧事有关。",\n    "rules": [\n      "完全现实主义设定，无超自然元素。所有谜团都有合理的解释。",\n      "调查系统是核心玩法：收集线索→推理→指认嫌疑人→揭露真相。",\n      "每条角色线都与案件有不同程度的关联，恋爱与悬疑交织。",\n      "「信任」是双刃剑：向某人透露调查进展可能获得帮助，也可能暴露自己。",\n      "主角有「洞察力」属性，通过日常对话和场景观察来发现隐藏线索。",\n      "新闻报道和社交媒体是信息来源之一，也是双刃剑（可以引导舆论也可能被利用）。",\n      "真相不止一个层面——每个嫌疑人背后都有自己的故事和苦衷。"\n    ],\n    "locations": [\n      {\n        "name": "霖海大学",\n        "description": "主角就读/工作的综合性大学，校园建在半山腰，能俯瞰整个城市和海港。",\n        "sub_locations": ["心理学系大楼", "图书馆", "学生食堂", "屋顶花园", "旧实验楼（已封闭）"]\n      },\n      {\n        "name": "市公安局",\n        "description": "案件调查的官方机构。内部也有派系和压力，有些警察真心想破案，有些只想结案。",\n        "sub_locations": ["刑侦大队办公室", "审讯室", "档案室", "天台吸烟区（情报交换点）"]\n      },\n      {\n        "name": "旧城区·雨巷",\n        "description": "建市最早的老城区，狭窄的巷道和密集的旧楼。大部分案件发生在这里。",\n        "sub_locations": ["雨巷深处", "旧公寓（案发现场）", "老茶馆", "废弃工厂", "江边码头"]\n      },\n      {\n        "name": "商业中心·海月广场",\n        "description": "现代商业区，高楼林立。多家与案件有关的企业在这里设有办公室。",\n        "sub_locations": ["海月大厦（嫌疑企业总部）", "咖啡馆·雨声", "书店·一页", "高级公寓"]\n      },\n      {\n        "name": "霖海日报大楼",\n        "description": "本地最大媒体机构。主编与警方和政界都有关系，新闻报道的方向可以影响案件走向。",\n        "sub_locations": ["编辑部", "总编办公室", "暗房", "记者休息室"]\n      },\n      {\n        "name": "灯塔岬角",\n        "description": "城市最东端的海岬，有一座废弃灯塔。是案件的某个关键地点，也是角色吐露心声的场所。",\n        "sub_locations": ["灯塔内部", "岬角悬崖", "海边礁石", "通往灯塔的山路"]\n      }\n    ],\n    "factions": [\n      {\n        "name": "刑警队·重案组",\n        "description": "负责雨夜连环事件的核心警员。人手不足，面临上级限期破案的压力。",\n        "values": ["正义", "责任", "法律"]\n      },\n      {\n        "name": "霖海集团",\n        "description": "本地最大的企业集团，涉及地产、港口、制药。与旧事件有说不清的关联。",\n        "values": ["利益", "形象", "控制"]\n      },\n      {\n        "name": "媒体阵营",\n        "description": "以霖海日报为代表的新闻媒体。在追求真相和维护社会稳定之间摇摆。",\n        "values": ["真相", "流量", "社会责任"]\n      },\n      {\n        "name": "旧城区居民会",\n        "description": "案件发生地的居民组织。对警方不信任，有自己的情报网络和生存法则。",\n        "values": ["团结", "自保", "记忆"]\n      },\n      {\n        "name": "匿名者「X」",\n        "description": "通过匿名信和暗网提供案件线索的神秘人物/组织。目的不明但信息准确。",\n        "values": ["真相？", "操控？", "目的不明"]\n      }\n    ],\n    "custom_rules": [\n      "线索收集系统：每个场景和对话都可能隐藏线索，需要洞察力来发现",\n      "推理板：玩家可以将收集的线索关联起来形成推理链",\n      "嫌疑人档案：每个可疑人物有独立档案，记录已知信息、嫌疑度和关系",\n      "时间压力：主线有deadline（下一个受害者可能出现的时间），影响调查节奏",\n      "多结局系统：推理正确→真结局；推理错误→冤枉无辜；忽视线索→案件不了了之",\n      "感情线与案件线并行：越接近真相，越可能失去重要的人"\n    ],\n    "calendar_events": [\n      {"month": 3, "event": "新学期/入职", "significance": "故事开始，第一个案件"},\n      {"month": 4, "event": "第二起案件", "significance": "确认连环作案模式，调查正式开始"},\n      {"month": 6, "event": "梅雨季", "significance": "连续下雨，案件频发期，气氛压抑"},\n      {"month": 8, "event": "旧事件线索浮现", "significance": "15年前的秘密开始被揭开"},\n      {"month": 10, "event": "关键证人失踪", "significance": "案件急转直下，危机升级"},\n      {"month": 12, "event": "最终对决", "significance": "真相揭露，大结局"}\n    ]\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('world_post_apocalypse', 'world', '灰烬纪元 — 末日后的微光', '后末日生存题材。文明崩溃后的废土世界，幸存者们在废墟中重建希望，同时面对变异生物的威胁和人性的考验。', '["末日", "生存", "冒险", "人性", "恋爱"]', TRUE, '{\n  "template_id": "world_post_apocalypse",\n  "template_type": "world",\n  "name": "灰烬纪元 — 末日后的微光",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "后末日生存题材。文明崩溃后的废土世界，幸存者们在废墟中重建希望，同时面对变异生物的威胁和人性的考验。",\n  "world": {\n    "era": "大崩溃后第15年",\n    "genre": ["末日", "生存", "冒险", "人性", "恋爱"],\n    "setting_description": "15年前，被称为「大崩溃」的灾难摧毁了人类文明。没有核弹，没有外星入侵——而是一种被称为「灰雾」的神秘现象吞噬了一切电子设备，同时导致大量动植物变异。城市沦为钢筋水泥的废墟丛林，幸存者不足灾前的十分之一。如今，散落各地的幸存者聚落艰难重建着文明，而灰雾仍未消散，它似乎有着自己的意志。",\n    "rules": [\n      "灰雾会干扰一切电子设备，但偶尔会「退潮」，短暂恢复旧世界科技。",\n      "长期暴露在浓雾中的人类会变异为「灰蚀者」——失去理智的怪物。",\n      "少数人觉醒了「共鸣能力」——可以与灰雾产生共振获得超常感知或力量，但过度使用会加速灰蚀。",\n      "旧世界的物资（罐头、药品、武器零件）是硬通货，比任何货币都有价值。",\n      "各聚落之间有「商队」往来，路线安全是最大挑战。",\n      "大崩溃的原因成谜，有人说是自然反噬，有人说是某项实验失控，有人说是神的审判。"\n    ],\n    "locations": [\n      {\n        "name": "避风港",\n        "description": "主角所在的幸存者聚落，由一座废弃的大学校园改造而成。是废土中相对安全和文明的定居点。",\n        "sub_locations": ["主楼（议会厅）", "图书馆（知识保存所）", "温室农场", "瞭望塔", "旧操场（集市）", "医疗帐篷"]\n      },\n      {\n        "name": "废都·旧城遗迹",\n        "description": "曾经的大城市遗址。摩天大楼被藤蔓覆盖，地铁隧道成了变异生物的巢穴。危险但蕴藏丰富的旧世界资源。",\n        "sub_locations": ["摩天大楼顶层（观景台）", "地铁站", "军事基地遗址", "旧世界商场", "被淹没的地下街"]\n      },\n      {\n        "name": "移动城·方舟",\n        "description": "由旧世界军用车辆改装的巨型移动聚落，在废土上游牧。是废土最大的贸易中心。",\n        "sub_locations": ["驾驶舱区", "居民车厢", "中央广场车厢", "工坊车厢", "酒吧车厢·生锈齿轮"]\n      },\n      {\n        "name": "雾海深处",\n        "description": "灰雾最浓密的区域，几乎无人敢进入。传说灰雾的中心有一个「核心」，那里藏着大崩溃的真相。",\n        "sub_locations": ["雾海边界", "迷雾中的废墟教堂", "灰蚀森林", "核心地带（未探索）"]\n      },\n      {\n        "name": "地下列车·银线",\n        "description": "大崩溃前建成的秘密地下铁路系统，部分线路仍然运行。是连接远距离聚落的生命线。",\n        "sub_locations": ["避风港站", "隧道中继站", "废弃的研究设施站", "终点站·最后的避难所"]\n      }\n    ],\n    "factions": [\n      {\n        "name": "避风港议会",\n        "description": "主角聚落的自治管理机构。主张和平重建文明，但资源短缺让内部矛盾激化。",\n        "values": ["重建", "民主", "希望"]\n      },\n      {\n        "name": "钢铁兄弟会",\n        "description": "由前军人组成的武装组织，控制着废都遗迹的大部分区域。武力至上，对外来者警惕。",\n        "values": ["力量", "秩序", "保护"]\n      },\n      {\n        "name": "雾行者",\n        "description": "专门穿越灰雾进行贸易的流浪商人团。适应力极强，对灰雾有独到理解。亦商亦盗。",\n        "values": ["自由", "利润", "适应"]\n      },\n      {\n        "name": "教团·新生",\n        "description": "崇拜灰雾的宗教组织，认为大崩溃是进化的契机。教众中有许多灰蚀未完全变异的半感染者。",\n        "values": ["进化", "信仰", "超越"]\n      },\n      {\n        "name": "方舟联盟",\n        "description": "移动城方舟的管理者，由工程师和科学家主导。致力于恢复旧世界科技。",\n        "values": ["科技", "知识", "流动"]\n      }\n    ],\n    "custom_rules": [\n      "资源管理系统：食物、水、弹药、药品、零件五种核心资源",\n      "灰蚀值：使用共鸣能力或暴露于灰雾会增加，过高则game over（变异结局）",\n      "聚落声望：在避风港的信誉度，影响可获得的支援和任务",\n      "天气系统：灰雾浓度随天气变化，影响探索难度和遇敌率",\n      "道德抉择：经常面临「救一个人vs保全更多人」的两难选择",\n      "主线目标：找到大崩溃的原因并尝试逆转灰雾"\n    ],\n    "calendar_events": [\n      {"month": 3, "event": "春耕祭", "significance": "播种季节，聚落最重要的集体活动"},\n      {"month": 5, "event": "灰雾退潮期", "significance": "难得的探索窗口期，可深入雾海"},\n      {"month": 7, "event": "方舟集市", "significance": "移动城经过避风港附近，大型贸易活动"},\n      {"month": 9, "event": "收获节", "significance": "庆丰收，角色关系发展的重要社交场合"},\n      {"month": 11, "event": "灰雾大潮", "significance": "灰雾异常扩张，防御战和危机事件"},\n      {"month": 12, "event": "除夕篝火", "significance": "围火守岁，回顾与展望，感情升温场景"}\n    ]\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('world_isekai', 'world', '彼方之门 — 异世界召唤', '经典异世界穿越题材。现代人被召唤到充满魔法与魔物的异世界，利用现代知识生存，同时寻找回到原来世界的方法。', '["异世界", "冒险", "日常", "恋爱", "喜剧"]', TRUE, '{\n  "template_id": "world_isekai",\n  "template_type": "world",\n  "name": "彼方之门 — 异世界召唤",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "经典异世界穿越题材。现代人被召唤到充满魔法与魔物的异世界，利用现代知识生存，同时寻找回到原来世界的方法。",\n  "world": {\n    "era": "异世界（相当于欧洲中世纪水平 + 魔法文明）",\n    "genre": ["异世界", "冒险", "日常", "恋爱", "喜剧"],\n    "setting_description": "主角在某天突然被一道光柱吞没，醒来时发现自己身处一个名为「阿尔卡迪亚」的异世界。这个世界有魔法、魔物、亚人种族，文明水平大约相当于中世纪但因为有魔法所以生活质量不差。召唤主角的是一个小型王国的宫廷魔法师，因为预言说「异界来客将改变世界的命运」。但主角发现自己好像没有什么特别的力量……除了一样东西——一部还有电量的智能手机和脑中的现代知识。",\n    "rules": [\n      "主角没有「外挂」级别的力量，核心优势是现代知识（科学、数学、经济学等）。",\n      "魔法体系存在：基础属性（火/水/风/土）+ 特殊属性（光/暗/空间/时间）。需要天赋和训练。",\n      "主角的魔法天赋：极低的魔力上限，但拥有罕见的「空间属性」——可以做传送和收纳。",\n      "智能手机电量有限（约3天），用完后只能靠太阳能充电板（如果有）缓慢充电。",\n      "语言最初不通，但召唤仪式附带了语言理解魔法，一周后完全掌握。",\n      "亚人种族（精灵、兽人、矮人、龙裔等）与人类共存，存在歧视问题。",\n      "魔王是存在的，但和传统印象不同——它是一个周期性出现的自然灾害般的存在。"\n    ],\n    "locations": [\n      {\n        "name": "小王国·菲奥雷",\n        "description": "召唤主角的王国，是大陆上最小的国家之一。民风淳朴，农业为主，军事力量薄弱。",\n        "sub_locations": ["王城（其实不大）", "城镇广场", "冒险者公会分部", "市场", "农田", "河流"]\n      },\n      {\n        "name": "冒险者公会总部·王都",\n        "description": "大陆最大的冒险者组织总部，位于邻国的大城市中。各种族的冒险者汇聚于此。",\n        "sub_locations": ["任务大厅", "训练场", "装备商店", "宿舍", "酒馆·龙与杯"]\n      },\n      {\n        "name": "大森林·绿海",\n        "description": "大陆中部的巨大原始森林，精灵族的家园。深处有远古遗迹和强大的魔物。",\n        "sub_locations": ["精灵村落", "世界树", "古代神殿遗迹", "魔物巢穴"]\n      },\n      {\n        "name": "矮人都市·铁炉堡",\n        "description": "建在山体内部的矮人城市，以精湛的锻造和机械工程闻名。是技术最先进的地方。",\n        "sub_locations": ["锻造大厅", "机械工坊", "矿坑", "宝石交易所", "矮人酒馆"]\n      },\n      {\n        "name": "魔王领地·灰烬荒原",\n        "description": "大陆最北端的荒芜之地，魔物横行。每隔百年「魔王」会在这里苏醒。",\n        "sub_locations": ["荒原边界", "魔物军团驻地", "魔王城", "封印之地"]\n      },\n      {\n        "name": "次元裂隙·彼方之门",\n        "description": "连接主角原来世界和异世界的空间裂缝。不稳定，但可能是回家的唯一途径。",\n        "sub_locations": ["裂隙入口", "次元通道", "门的核心"]\n      }\n    ],\n    "factions": [\n      {\n        "name": "菲奥雷王室",\n        "description": "召唤主角的小王国。面临邻国和魔物的双重威胁，把希望寄托在「异界来客」身上。",\n        "values": ["生存", "希望", "责任"]\n      },\n      {\n        "name": "冒险者公会",\n        "description": "大陆最强大的中立组织，负责讨伐魔物和管理冒险者。不问出身只看实力。",\n        "values": ["实力", "自由", "冒险精神"]\n      },\n      {\n        "name": "贤者塔",\n        "description": "魔法研究者的最高学府，保存着关于次元裂隙和魔王的古老知识。",\n        "values": ["知识", "研究", "中道"]\n      },\n      {\n        "name": "魔物军团",\n        "description": "受魔王影响聚集的魔物大军。并非有组织的军队，更像天灾。",\n        "values": ["本能", "破坏", "进化"]\n      },\n      {\n        "name": "归乡会",\n        "description": "散落在异世界的其他被召唤者组成的秘密组织。大家都在寻找回家的方法。",\n        "values": ["归乡", "互助", "孤独"]\n      }\n    ],\n    "custom_rules": [\n      "现代知识应用系统：用科学原理改良异世界技术可获得声望和资源",\n      "手机电量管理：每次使用手机功能（查资料、拍照、听音乐）消耗电量",\n      "冒险者等级：铜→铁→银→金→白金→传说",\n      "语言/文化交流：主角的现代用语和观念会产生有趣的误解",\n      "归乡抉择：故事核心主题之一——要回到原来的世界，还是留在这里？",\n      "日常与冒险交替：日常经营/社交和冒险/战斗各占一半节奏"\n    ],\n    "calendar_events": [\n      {"month": 1, "event": "召唤日", "significance": "故事开始，到达异世界"},\n      {"month": 3, "event": "冒险者登录", "significance": "正式开始冒险生涯"},\n      {"month": 5, "event": "收获祭", "significance": "小镇庆典，日常路线重要事件"},\n      {"month": 7, "event": "魔物大侵袭", "significance": "季节性魔物潮，战斗主线推进"},\n      {"month": 9, "event": "贤者塔入学考核", "significance": "获得关键知识的机会"},\n      {"month": 11, "event": "彼方之门异动", "significance": "次元裂隙不稳定，归乡可能"},\n      {"month": 12, "event": "魔王苏醒前兆", "significance": "终章事件，最终选择"}\n    ]\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('world_court_intrigue', 'world', '凤鸣宫 — 锦绣权谋', '东方宫廷权谋题材。以架空的古代王朝为背景，在华丽的宫殿中展开政治博弈、后宫争斗和暗流涌动的恋爱。', '["宫廷", "权谋", "恋爱", "古风", "悬疑"]', TRUE, '{\n  "template_id": "world_court_intrigue",\n  "template_type": "world",\n  "name": "凤鸣宫 — 锦绣权谋",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "东方宫廷权谋题材。以架空的古代王朝为背景，在华丽的宫殿中展开政治博弈、后宫争斗和暗流涌动的恋爱。",\n  "world": {\n    "era": "架空古代（参考唐宋盛世）",\n    "genre": ["宫廷", "权谋", "恋爱", "古风", "悬疑"],\n    "setting_description": "大昭王朝，立国三百年的盛世帝国。当今天子年少登基，朝堂由太后与权臣把持。京城「凤鸣城」是天下最繁华的都市，皇宫「紫宸宫」占地千亩，殿阁重重。表面上歌舞升平，暗地里却是各方势力角逐的修罗场。主角以某种身份进入宫廷（新科状元/宫女/太医/侍卫等），卷入了一场关乎王朝命运的权力游戏。",\n    "rules": [\n      "宫廷等级森严：皇帝/太后→皇子/公主→妃嫔→大臣→侍卫→宫女/太监。言行举止皆受身份约束。",\n      "政治联姻是常态，真爱在宫廷中是奢侈品也是危险品。",\n      "「暗卫」是皇帝/太后的秘密武力，直属指挥，其他人不知其身份。",\n      "下毒、暗杀、栽赃、离间是常见的权谋手段，但都有被发现的风险。",\n      "「圣旨」和「密折」是权力运作的关键道具——得到它们就掌握了主动权。",\n      "后宫与前朝紧密相连，妃嫔的家族势力直接影响朝堂格局。",\n      "「天命」观念根深蒂固，造反需要极强的正当性。"\n    ],\n    "locations": [\n      {\n        "name": "紫宸宫·外朝",\n        "description": "皇帝处理政务的区域，宏伟的朝堂和金銮殿是帝国权力的核心。百官朝会之处。",\n        "sub_locations": ["金銮殿", "御书房", "六部衙署", "翰林院", "武英殿（军事议事厅）"]\n      },\n      {\n        "name": "紫宸宫·内廷",\n        "description": "后宫区域，妃嫔居住之地。华丽的宫殿之间是曲折的回廊和秘密的暗道。",\n        "sub_locations": ["凤仪宫（皇后居所）", "各妃嫔宫院", "御花园", "冷宫", "密道入口"]\n      },\n      {\n        "name": "太液池",\n        "description": "皇宫中央的人工湖，湖心有蓬莱岛。是皇帝宴饮和秘密会面的场所。",\n        "sub_locations": ["蓬莱岛", "湖畔长廊", "水榭", "荷花池"]\n      },\n      {\n        "name": "凤鸣城·市井",\n        "description": "皇宫外面的京城。繁华的商业区与幽暗的地下世界仅一墙之隔。",\n        "sub_locations": ["朱雀大街", "东市西市", "醉仙楼（最大的酒楼）", "暗巷·黑市", "城隍庙"]\n      },\n      {\n        "name": "太医院",\n        "description": "掌管宫廷医药的机构。太医们掌握着所有人的健康秘密，是信息枢纽。",\n        "sub_locations": ["药房", "诊室", "毒物标本室", "太医宿舍"]\n      },\n      {\n        "name": "天机阁",\n        "description": "宫中最神秘的建筑，是占星师和密探的据点。据说可以推算国运。",\n        "sub_locations": ["观星台", "密档室", "审讯地牢"]\n      }\n    ],\n    "factions": [\n      {\n        "name": "帝党",\n        "description": "拥护年轻皇帝亲政的势力。皇帝有理想但缺乏经验，核心支持者不多。",\n        "values": ["正统", "改革", "抱负"]\n      },\n      {\n        "name": "太后一系",\n        "description": "以太后为首的保守派，把持朝政多年。家族势力庞大，不愿放权。",\n        "values": ["稳定", "权力", "家族"]\n      },\n      {\n        "name": "权臣集团",\n        "description": "以宰相为首的官僚利益集团。在帝党和太后之间左右逢源。",\n        "values": ["利益", "平衡", "实用"]\n      },\n      {\n        "name": "后宫势力",\n        "description": "各妃嫔背后的家族势力网。通过联姻和子嗣争夺影响朝政。",\n        "values": ["子嗣", "恩宠", "家族荣耀"]\n      },\n      {\n        "name": "暗影组织·夜枭",\n        "description": "潜伏在宫廷暗处的神秘组织，目的不明。掌握着大量秘密。",\n        "values": ["秘密", "操控", "目的不明"]\n      }\n    ],\n    "custom_rules": [\n      "身份系统：主角的初始身份决定可用路线和接触范围",\n      "声望系统：朝堂声望、后宫声望、民间声望三条独立数值",\n      "信任网络：与每个角色的信任度影响可获知的情报和可联手的对象",\n      "情报系统：收集/散布情报是核心玩法，信息差决定胜负",\n      "危机事件：随剧情推进会遭遇下毒、诬陷等危机，需要靠积累的资源化解",\n      "季节流转：春夏秋冬四季影响场景描写和宫廷活动"\n    ],\n    "calendar_events": [\n      {"month": 1, "event": "元旦大朝会", "significance": "新年朝贺，各方势力亮相"},\n      {"month": 3, "event": "春猎", "significance": "皇帝率众出猎，可暗中接触宫外势力"},\n      {"month": 5, "event": "端午宴", "significance": "宫宴上的政治角力和暗杀事件"},\n      {"month": 7, "event": "七夕·乞巧节", "significance": "后宫最浪漫的节日，感情事件高发"},\n      {"month": 9, "event": "秋闱·科举", "significance": "人才选拔，新势力入场的窗口"},\n      {"month": 11, "event": "冬祭·太庙", "significance": "祭祖大典，皇位继承问题的引爆点"},\n      {"month": 12, "event": "除夕宫宴", "significance": "年终对决，大结局关键场景"}\n    ]\n  }\n}');

