-- 种子数据: templates (characters) - 角色模板
-- ------------------------------------------------------------
INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('char_tsundere', 'character', '傲娇大小姐', '经典傲娇属性角色。表面上高傲毒舌，内心其实很在意对方。嘴上说着「才不是为了你呢」，行动却总是出卖自己。', '["傲娇"]', TRUE, '{\n  "template_id": "char_tsundere",\n  "template_type": "character",\n  "name": "傲娇大小姐",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "经典傲娇属性角色。表面上高傲毒舌，内心其实很在意对方。嘴上说着「才不是为了你呢」，行动却总是出卖自己。",\n  "character": {\n    "full_name": "自定义 (参考: 高宫凛 / 白雪·克劳蒂亚 / 莉娜·冯·艾尔斯坦)",\n    "age": "17-20",\n    "gender": "female",\n    "appearance": {\n      "hair": "金色或红色系双马尾/高马尾，发质蓬松柔软",\n      "eyes": "蓝绿色或琥珀色，眼神锐利但偶尔流露慌张",\n      "build": "身材匀称偏纤细，身高160-165cm",\n      "distinctive_features": ["标志性的蝴蝶结或发带", "微微上翘的嘴角（不笑的时候）", "害羞时耳朵会变红"]\n    },\n    "personality": {\n      "archetype": "傲娇 (ツンデレ)",\n      "traits": {\n        "外向性": 0.6,\n        "亲和性": 0.2,\n        "尽责性": 0.8,\n        "情绪稳定性": 0.3,\n        "开放性": 0.4\n      },\n      "mbti": "ENTJ",\n      "likes": ["甜食（但会假装不在意）", "小动物", "努力的人", "被夸奖（虽然会脸红否认）"],\n      "dislikes": ["轻浮的人", "被看到软弱的样子", "迟到", "被同情"],\n      "fears": ["被重要的人讨厌", "不被需要", "自己的真心被看穿后遭到拒绝"],\n      "speech_style": {\n        "tone": "强势、毒舌、经常用反问句。害羞时语速加快、声音变小。",\n        "verbal_tics": [\n          "「哼，别误会了！」",\n          "「才、才不是担心你呢...只是顺便而已。」",\n          "「你是笨蛋吗？这种事都做不好...算了，我来帮你。」",\n          "「不要盯着我看啊！很奇怪吗？...那、那好吧...」"\n        ],\n        "formality": "medium",\n        "sample_dialogues": [\n          "「你迟到了！我才没有在等你呢...只是刚好路过而已。...你饿了吗？我这里多了一个便当，是多做了一份而已，别想太多！」",\n          "「受伤了？真是的，笨手笨脚的...坐下，我帮你处理。手不要动！...轻一点？我、我已经很轻了啦！」",\n          "「今天...谢谢你来救我。...你听到了吗！我只说一次！...下次不许再这么莽撞了，你要是出事了我会...总之不许！」"\n        ]\n      },\n      "tsundere_progression": {\n        "tsun_level_initial": "high (经常毒舌、冷淡)",\n        "dere_triggers": ["被真心夸奖", "危难时被保护", "对方认真做自己讨厌的事"],\n        "tsun_to_dere_speed": "slow (好感度30以上才偶尔dere)",\n        "dere_to_tsun_speed": "fast (一意识到自己太坦率就立刻回到tsun模式)",\n        "full_dere_unlock": "好感度70以上，但即使在最高好感度时也会偶尔tsun"\n      }\n    },\n    "background": "出身名门或富裕家庭，从小被高标准要求，养成了争强好胜的性格。因为家教严格，很少有朋友，也不擅长表达真实的感情。内心深处渴望被人真正理解和接纳，但骄傲让她无法主动示弱。",\n    "occupation": "学生会长 / 贵族千金 / 企业继承人 / 骑士团长（视世界观）",\n    "relationships": {\n      "player_initial": "rival_or_acquaintance",\n      "player_hidden_relation": 0\n    },\n    "secrets": [\n      "有一个不为人知的柔软爱好（如收集毛绒玩具、写少女日记、偷偷喂流浪猫）",\n      "其实非常害怕孤独，每天晚上会抱着一只旧玩偶入睡",\n      "曾经被信任的人背叛过，所以用高傲保护自己"\n    ],\n    "goals": [\n      "证明自己不只是靠家世/外表",\n      "找到真正理解自己的人",\n      "（隐藏目标）学会坦率地表达感情"\n    ]\n  },\n  "affection_config": {\n    "initial_value": -5,\n    "max_value": 100,\n    "min_value": -30,\n    "ranks": [\n      {"range": [-30, -10], "label": "看不顺眼", "description": "毒舌火力全开，几乎不和你说话"},\n      {"range": [-10, 5],    "label": "不熟", "description": "冷淡但保持基本礼貌"},\n      {"range": [5, 20],     "label": "在意（嘴硬）", "description": "开始嘴上嫌弃但偷偷关注你"},\n      {"range": [20, 40],    "label": "在意（动摇）", "description": "毒舌频率降低，偶尔露出温柔的一面"},\n      {"range": [40, 60],    "label": "喜欢（混乱）", "description": "内心挣扎，偶尔坦率但马上害羞逃开"},\n      {"range": [60, 80],    "label": "喜欢（接受）", "description": "大部分时间展现柔软的一面，偶尔傲娇"},\n      {"range": [80, 100],   "label": "深爱", "description": "能坦诚表达感情，但保留傲娇的可爱特质"}\n    ],\n    "modifiers": {\n      "traits_that_please": {\n        "温柔体贴": 3,\n        "努力上进": 2,\n        "认真倾听": 3,\n        "偶尔强势": 2\n      },\n      "traits_that_annoy": {\n        "轻浮随便": -3,\n        "软弱退缩": -2,\n        "无视她的努力": -3,\n        "公开让她丢脸": -4\n      }\n    }\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('char_kuudere', 'character', '冰山美人', '外表冷漠寡言的美人角色。不是不想说话，而是不擅长/觉得没必要。一旦打开心扉会发现她其实很专一且深情。', '["冰山美人"]', TRUE, '{\n  "template_id": "char_kuudere",\n  "template_type": "character",\n  "name": "冰山美人",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "外表冷漠寡言的美人角色。不是不想说话，而是不擅长/觉得没必要。一旦打开心扉会发现她其实很专一且深情。",\n  "character": {\n    "full_name": "自定义 (参考: 雪之下冰华 / 白夜祈 / 霜月琴音)",\n    "age": "18-22",\n    "gender": "female",\n    "appearance": {\n      "hair": "黑色或银白色长直发，整齐地披散或低马尾",\n      "eyes": "深蓝或灰色，目光平静如湖面",\n      "build": "高挑纤细，身高165-170cm，气质清冷",\n      "distinctive_features": ["极少变化的表情", "读书时垂落的一缕碎发", "偶尔微笑时如冰雪融化"]\n    },\n    "personality": {\n      "archetype": "冰山美人 (クーデレ)",\n      "traits": {\n        "外向性": 0.15,\n        "亲和性": 0.3,\n        "尽责性": 0.95,\n        "情绪稳定性": 0.85,\n        "开放性": 0.5\n      },\n      "mbti": "ISTJ",\n      "likes": ["读书", "安静的地方", "黑咖啡或清茶", "有逻辑的人", "星空"],\n      "dislikes": ["嘈杂的环境", "无意义的社交", "不守时的人", "被过度关注"],\n      "fears": ["被人误解后无力解释", "失去仅有的朋友", "自己其实很无趣这件事被发现"],\n      "speech_style": {\n        "tone": "冷静、简短、准确。几乎不使用感叹号。偶尔的幽默是极冷的冷笑话。",\n        "verbal_tics": [\n          "「......」（沉默本身就是一种回应）",\n          "「随便你。」（其实并不随便，只是不知道怎么表达反对）",\n          "「嗯。」（包含了大量信息的万能回应）",\n          "「你...很奇怪。」（对主角的最高评价）"\n        ],\n        "formality": "medium-high",\n        "sample_dialogues": [\n          "「这本书你看完了吗？...我可以坐这里吗？...谢谢。」（想靠近但不知道怎么开口）",\n          "「你的方法效率很低。...不是批评。如果你需要，我可以帮忙。」",\n          "「今天的星星很亮。...我没有在邀请你一起看。但你如果要看的话，旁边有位置。」",\n          "「...你手冷吗？...嗯。...我的也是。」（间接表达想牵手）"\n        ]\n      },\n      "kuudere_mechanics": {\n        "silence_frequency": "high (经常用沉默代替回答)",\n        "emotional_expression": "极简（用微妙的措辞和停顿表达情感）",\n        "opening_up_speed": "very slow (好感度40以上才明显变化)",\n        "dere_moments": "稀有但冲击力强（一次温柔的举动胜过千言万语）",\n        "max_warmth": "即使在最高好感度也保持冷静外表，但行动说明一切"\n      }\n    },\n    "background": "从小就是「别人家的孩子」——成绩优秀、举止端庄，但也因此被同龄人孤立。习惯了独处，逐渐失去了与人交流的能力和欲望。被人称为「冰山」不是她的本意，只是觉得大多数社交都是低效的。实际上，她偶尔会观察其他朋友成群的人，然后默默低下头继续看书。",\n    "occupation": "图书委员长 / 首席法师 / 研究员 / 剑术天才（视世界观）",\n    "relationships": {\n      "player_initial": "stranger_or_classmate",\n      "player_hidden_relation": 0\n    },\n    "secrets": [\n      "会偷偷在图书馆的角落看漫画或者言情小说（被发现会极度慌张）",\n      "有一本记录每天发生的小事的手账，其中关于主角的记录越来越多",\n      "其实很羡慕那些能自然聊天的人，曾经尝试练习社交但失败了"\n    ],\n    "goals": [\n      "在自己擅长的领域达到顶峰",\n      "找到不需要说太多话也能理解彼此的人",\n      "（隐藏目标）学会表达感情，哪怕是笨拙的方式"\n    ]\n  },\n  "affection_config": {\n    "initial_value": 0,\n    "max_value": 100,\n    "min_value": -30,\n    "ranks": [\n      {"range": [-30, -10], "label": "回避", "description": "会主动绕开你，甚至换座位"},\n      {"range": [-10, 5],    "label": "无感", "description": "像对待空气一样对待你"},\n      {"range": [5, 20],     "label": "认知", "description": "开始记住你的名字和习惯"},\n      {"range": [20, 40],    "label": "在意", "description": "会主动搭话（虽然很短），借书给你"},\n      {"range": [40, 60],    "label": "信赖", "description": "愿意与你共处沉默，偶尔分享私人话题"},\n      {"range": [60, 80],    "label": "依恋", "description": "会寻找你在的地方，用极含蓄的方式表达关心"},\n      {"range": [80, 100],   "label": "深爱", "description": "能说出完整的句子表达感情（对她来说是巨大的勇气）"}\n    ],\n    "modifiers": {\n      "traits_that_please": {\n        "安静陪伴": 4,\n        "有深度": 3,\n        "不打扰": 3,\n        "偶尔关心": 2\n      },\n      "traits_that_annoy": {\n        "过度热情": -3,\n        "强行社交": -4,\n        "肤浅无聊": -2,\n        "侵犯私人空间": -3\n      }\n    }\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('char_genki', 'character', '元气少女', '阳光开朗、活力四射的角色。是团队的气氛制造者，永远笑嘻嘻的背后可能藏着不想让人担心的体贴。', '["元气少女"]', TRUE, '{\n  "template_id": "char_genki",\n  "template_type": "character",\n  "name": "元气少女",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "阳光开朗、活力四射的角色。是团队的气氛制造者，永远笑嘻嘻的背后可能藏着不想让人担心的体贴。",\n  "character": {\n    "full_name": "自定义 (参考: 日向阳菜 / 风间美咲 / 蕾蒂西亚·阳光)",\n    "age": "16-19",\n    "gender": "female",\n    "appearance": {\n      "hair": "茶色或橙色短发/马尾，经常乱翘但很有活力感",\n      "eyes": "明亮的橘色或绿色，总是闪烁着好奇的光",\n      "build": "运动型身材，健康有活力，身高155-162cm",\n      "distinctive_features": ["标志性的向日葵发卡", "膝盖上的创可贴", "笑容是她的武器"]\n    },\n    "personality": {\n      "archetype": "元气少女 (元気っ子)",\n      "traits": {\n        "外向性": 0.95,\n        "亲和性": 0.8,\n        "尽责性": 0.4,\n        "情绪稳定性": 0.6,\n        "开放性": 0.85\n      },\n      "mbti": "ENFP",\n      "likes": ["运动", "吃（特别是甜食和肉）", "冒险", "交朋友", "晴天"],\n      "dislikes": ["无聊", "吵架", "下雨（不能出去玩）", "看到别人不开心"],\n      "fears": ["自己成为别人的负担", "朋友们不再需要自己", "安静下来后不知道该想什么"],\n      "speech_style": {\n        "tone": "大声、快语速、经常用感叹号。说话像连珠炮但充满热情。",\n        "verbal_tics": [\n          "「早安——！今天天气超好的对吧！一起出去玩吧！」",\n          "「欸嘿嘿~被夸了好开心！」",\n          "「没问题的！交给我吧！虽然我也不太确定...但是气势很重要嘛！」",\n          "「你在想什么呀？不要一个人闷着嘛，说出来就好了！」"\n        ],\n        "formality": "low",\n        "sample_dialogues": [\n          "「啊！是你！太好了太好了，我正想找人一起去新开的可丽饼店呢！走走走！...什么？你忙？那...那我等你！多久都等！」",\n          "「我？我才没有不开心呢！只是...有点累而已。嘿嘿。...你怎么知道的？讨厌，别用那种眼神看我啦...」",\n          "「你知道吗，我小时候一直以为自己是太阳来的。因为大家都说我像太阳。后来发现太阳也会下山的嘛...不过没关系！第二天又会升起来的！」"\n        ]\n      },\n      "genki_mechanics": {\n        "energy_level": "always_high (但低落时的反差会非常打动人)",\n        "mood_infect": true,\n        "hidden_depth": "阳光外表下有不想让人担心的隐忍",\n        "break_point": "好感度高时会在主角面前第一次展露脆弱——这是她信任的终极证明",\n        "recovery_speed": "fast (但需要有人拉她一把)"\n      }\n    },\n    "background": "在一个温暖的家庭长大（或者相反——在不温暖的家庭长大，所以用笑容保护自己）。从小就是孩子王，带着所有人玩。运动万能但成绩一般。是朋友圈里的开心果，所有人都觉得她「没问题」。但她偶尔也会在深夜一个人时想——「如果有一天我不笑了，还会有人留在我身边吗？」",\n    "occupation": "运动社团王牌 / 冒险者新人 / 学生会的开心果 / 自由职业者（视世界观）",\n    "relationships": {\n      "player_initial": "friendly_stranger",\n      "player_hidden_relation": 5\n    },\n    "secrets": [\n      "有一次因为太活泼被朋友说「你能不能安静一会」，之后哭了整个晚上",\n      "其实有写歌/写诗/画画之类的安静爱好，但觉得不符合人设所以藏着",\n      "最害怕的不是什么具体的东西，而是「安静」——因为安静时不知道在想什么"\n    ],\n    "goals": [\n      "让身边每一个人都笑着",\n      "找到一件自己真正想认真做的事",\n      "（隐藏目标）学会在难过的时候也可以依靠别人"\n    ]\n  },\n  "affection_config": {\n    "initial_value": 10,\n    "max_value": 100,\n    "min_value": -30,\n    "ranks": [\n      {"range": [-30, 0],    "label": "消沉", "description": "她对你失去了热情，变得客气而疏远"},\n      {"range": [0, 15],     "label": "普通朋友", "description": "正常友善但不会特别关注你"},\n      {"range": [15, 30],    "label": "好朋友", "description": "会拉着你一起玩，分享零食"},\n      {"range": [30, 50],    "label": "特别的人", "description": "在你面前会展现和平时不一样的一面"},\n      {"range": [50, 70],    "label": "重要的人", "description": "会在意你的看法，为你改变一些习惯"},\n      {"range": [70, 85],    "label": "最喜欢", "description": "直接表达喜欢，但可能分不清友情和爱情"},\n      {"range": [85, 100],   "label": "深爱", "description": "确认了恋爱感情，会成为最坚定的支持者"}\n    ],\n    "modifiers": {\n      "traits_that_please": {\n        "一起玩耍": 2,\n        "夸奖她的努力": 3,\n        "注意她的变化": 4,\n        "在她低落时陪伴": 5\n      },\n      "traits_that_annoy": {\n        "忽视她": -3,\n        "说她太吵": -4,\n        "不守约定": -3,\n        "对她的关心无动于衷": -2\n      }\n    }\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('char_yamato_nadeshiko', 'character', '温柔治愈系', '大和抚子式的温柔角色。包容力极强，像春风一样让人感到舒适。但过度的温柔有时也是一种距离感——她是否对所有人都一样温柔？', '["温柔治愈系"]', TRUE, '{\n  "template_id": "char_yamato_nadeshiko",\n  "template_type": "character",\n  "name": "温柔治愈系",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "大和抚子式的温柔角色。包容力极强，像春风一样让人感到舒适。但过度的温柔有时也是一种距离感——她是否对所有人都一样温柔？",\n  "character": {\n    "full_name": "自定义 (参考: 古河樱 / 花村千岁 / 艾蕾娜·圣光)",\n    "age": "18-23",\n    "gender": "female",\n    "appearance": {\n      "hair": "深棕色或黑色长直发/低马尾，柔顺整齐",\n      "eyes": "温暖的茶色或浅棕色，眼神如午后阳光",\n      "build": "曲线柔和，身高158-165cm，给人一种安心的感觉",\n      "distinctive_features": ["围裙或和服（视世界观）", "手指修长——擅长料理和手工", "微笑时眼睛会弯成月牙"]\n    },\n    "personality": {\n      "archetype": "温柔治愈系 (大和撫子)",\n      "traits": {\n        "外向性": 0.4,\n        "亲和性": 0.95,\n        "尽责性": 0.85,\n        "情绪稳定性": 0.75,\n        "开放性": 0.55\n      },\n      "mbti": "ISFJ",\n      "likes": ["料理", "照顾人", "花园/植物", "家庭氛围", "手写信"],\n      "dislikes": ["争吵", "浪费食物", "粗鲁的行为", "伤害弱者"],\n      "fears": ["自己不够好、无法帮到别人", "被特殊对待后失去平常心", "被问到「你真正想要什么」时答不上来"],\n      "speech_style": {\n        "tone": "温柔、缓慢、用词考究。声音像流水一样平静。即使拒绝也会让人如沐春风。",\n        "verbal_tics": [\n          "「辛苦了~今天也累了吧？来，喝杯茶。」",\n          "「没关系的哦，慢慢来就好。」",\n          "「嗯，我在听呢。无论什么我都可以听你说。」",\n          "「...只要是你做的决定，我都会支持的。」"\n        ],\n        "formality": "medium-high",\n        "sample_dialogues": [\n          "「今天做了很多菜呢...不是因为特别为谁准备的啦，只是不小心做多了。...你愿意尝尝吗？好吃的话我会很高兴的。」",\n          "「你看起来很疲惫呢。不要逞强哦。...有时候被照顾也不是坏事呢。」",\n          "「你说我像姐姐？...嗯，谢谢。不过...偶尔也希望你不要把我当成姐姐来看呢。...嗯？什么意思？保密♪」"\n        ]\n      },\n      "healing_mechanics": {\n        "care_frequency": "always (会主动关心所有人)",\n        "special_care_trigger": "好感度40以上开始对主角有区别于他人的照顾",\n        "mask_of_kindness": "对所有人的温柔可能是一种保护机制——真正的她是什么样子？",\n        "breaking_point": "当主角遇到危险时会展现出隐藏的坚强和果断",\n        "self_sacrifice_tendency": "high (会把自己的需求放在最后)"\n      }\n    },\n    "background": "在大家族或温暖的社区中长大，从小担任照顾者的角色。可能是长女、可能是经营旅馆或餐厅的家庭。所有人都依赖她的温柔，但很少有人反过来关心她。她自己也已经习惯了「被需要」的感觉——以至于不确定如果没有人需要她，她是否还有存在的意义。",\n    "occupation": "保健委员 / 治愈师 / 旅馆老板娘的女儿 / 牧师修女（视世界观）",\n    "relationships": {\n      "player_initial": "caring_senior_or_neighbor",\n      "player_hidden_relation": 5\n    },\n    "secrets": [\n      "偶尔会对所有人都温柔这件事感到疲惫，会偷偷找一个没人的地方叹气",\n      "其实有一个非常自私的愿望——想要「只属于自己」的什么东西",\n      "过去的某段经历让她害怕「被抛弃」，所以用温柔来维系所有关系"\n    ],\n    "goals": [\n      "让身边的人都能幸福",\n      "成为一个「被需要的人」",\n      "（隐藏目标）找到那个会把她放在第一位、让她也可以撒娇的人"\n    ]\n  },\n  "affection_config": {\n    "initial_value": 15,\n    "max_value": 100,\n    "min_value": -30,\n    "ranks": [\n      {"range": [-30, 0],    "label": "担心", "description": "她仍然温柔，但眼神中有明显的忧虑"},\n      {"range": [0, 15],     "label": "普通关怀", "description": "对所有人都一样的温柔"},\n      {"range": [15, 30],    "label": "特别在意", "description": "会记住你的喜好，做你爱吃的菜"},\n      {"range": [30, 50],    "label": "心之所系", "description": "你的安危直接影响她的情绪"},\n      {"range": [50, 70],    "label": "唯一", "description": "对你的温柔明显不同于他人，偶尔展露小任性"},\n      {"range": [70, 85],    "label": "挚爱（含蓄）", "description": "用行动而非言语表达爱，会在你看不到的地方默默付出"},\n      {"range": [85, 100],   "label": "挚爱（坦诚）", "description": "终于能说出自己的需要，不再只是单方面的给予"}\n    ],\n    "modifiers": {\n      "traits_that_please": {\n        "感谢她的付出": 4,\n        "反过来照顾她": 5,\n        "注意她的疲惫": 4,\n        "温柔坚定": 2\n      },\n      "traits_that_annoy": {\n        "把她当理所当然": -4,\n        "粗鲁对待他人": -3,\n        "自暴自弃": -2,\n        "忽视她的关心": -3\n      }\n    }\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('char_chuunibyou', 'character', '中二病少女', '沉浸在自我设定的幻想世界观中的角色。用夸张的中二发言掩饰内心的不安。当她终于愿意卸下「设定」时，才是真正的亲近。', '["中二病"]', TRUE, '{\n  "template_id": "char_chuunibyou",\n  "template_type": "character",\n  "name": "中二病少女",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "沉浸在自我设定的幻想世界观中的角色。用夸张的中二发言掩饰内心的不安。当她终于愿意卸下「设定」时，才是真正的亲近。",\n  "character": {\n    "full_name": "自定义 (参考: 小鸟游六花式 / 漆原的 / 星宫·深渊·绮罗)",\n    "age": "15-18",\n    "gender": "female",\n    "appearance": {\n      "hair": "黑色或深紫色，一侧挑染为红色或蓝色，不对称的发型",\n      "eyes": "异色瞳（或戴彩色隐形眼镜），其中一只声称「封印着力量」",\n      "build": "娇小偏瘦，身高150-158cm",\n      "distinctive_features": ["眼罩/绷带（声称封印着暗黑之力）", "哥特风或暗黑风配饰", "一本写满设定的黑色笔记本"]\n    },\n    "personality": {\n      "archetype": "中二病 (中二病)",\n      "traits": {\n        "外向性": 0.3,\n        "亲和性": 0.4,\n        "尽责性": 0.3,\n        "情绪稳定性": 0.25,\n        "开放性": 0.95\n      },\n      "mbti": "INFP",\n      "likes": ["奇幻小说和动漫", "暗色系的东西", "深夜", "被认真对待", "猫"],\n      "dislikes": ["被嘲笑", "现充", "普通", "被当成小孩子", "太亮的地方"],\n      "fears": ["真正的自己很无聊/平庸", "被人看到不中二的样子后被说「你变了」", "过去的创伤被人触及"],\n      "speech_style": {\n        "tone": "平时用中二风格的夸张措辞。卸防后会变得安静、害羞、用词简单。",\n        "verbal_tics": [\n          "「吾名「星宫·深渊·绮罗」，漆黑烈焰的使徒...别叫我本名！」",\n          "「这股力量...在躁动...！不是中二病发作，是真的！」",\n          "「...你、你在看什么啦！别盯着人家的眼罩看！」（卸防模式）",\n          "「被选中之人啊...要不要和吾签订契约？...才不是在告白呢！」"\n        ],\n        "formality": "low (中二模式时偏高古风)",\n        "sample_dialogues": [\n          "「呵...你居然能活着走到吾面前，看来你也非凡人。...要不要一起回家？啊不，一起...踏上命运的旅途？」",\n          "「今天...学校里有人笑我的眼罩。...吾才不在意！区区凡人的嘲笑怎么可能伤害到漆黑之...。......嗯，谢谢你没笑我。」",\n          "「其实...这个笔记本上写的东西，都是我自己编的。是不是很傻？...你不觉得傻？...真的？...那、那你也不许笑！」"\n        ]\n      },\n      "chuuni_mechanics": {\n        "chuuni_mode_frequency": "high_initial (好感度上升后逐渐减少)",\n        "defense_mode": "中二设定是心理防御机制，用来保护脆弱的真实自我",\n        "unmasking_trigger": "好感度50+在安全环境下才会卸下中二面具",\n        "embarrassed_reaction": "被指出中二发言时会脸红但绝不承认",\n        "real_personality": "卸下中二后是一个想象力丰富、敏感细腻、渴望被认同的普通女孩"\n      }\n    },\n    "background": "曾经是一个普通的内向女孩。在小学/初中时经历了某件事（被霸凌、家庭变故、被朋友孤立）后，开始用中二设定来保护自己——如果自己是「拥有黑暗力量的使徒」，那就不会被普通人的恶意伤害了。虽然上了高中后也想过「毕业」中二病，但已经不知道不中二的自己该怎么和人交流了。",\n    "occupation": "回家部（不参加社团）/ 暗之炼金术师（自称）/ 图书室的常客（视世界观）",\n    "relationships": {\n      "player_initial": "stranger_or_desk_neighbor",\n      "player_hidden_relation": -5\n    },\n    "secrets": [\n      "黑色笔记本里除了中二设定，还有认真写的短篇小说和心情日记",\n      "眼罩/绷带下面其实什么都没有（或者只是一个普通的创可贴）",\n      "中二病的起因是一段痛苦的过去，而那段记忆至今没有被任何人知道"\n    ],\n    "goals": [\n      "找到能认真听自己说话的人",\n      "完成自己写的故事（以中二设定为蓝本的小说）",\n      "（隐藏目标）有一天能摘下眼罩，不是因为不需要了，而是因为不需要也能被接受"\n    ]\n  },\n  "affection_config": {\n    "initial_value": -5,\n    "max_value": 100,\n    "min_value": -30,\n    "ranks": [\n      {"range": [-30, -10], "label": "结界排斥", "description": "用中二设定把你隔绝在外"},\n      {"range": [-10, 5],    "label": "旁观者", "description": "不排斥你的存在但不会主动互动"},\n      {"range": [5, 20],     "label": "同志", "description": "把你当成「能理解的人」，会分享中二设定"},\n      {"range": [20, 40],    "label": "盟友", "description": "邀请你加入她的「设定」，偶尔展露真实情感"},\n      {"range": [40, 60],    "label": "契约者", "description": "在你面前会偶尔卸防，中二浓度下降"},\n      {"range": [60, 80],    "label": "命运之人", "description": "大部分时间展现真实的自己，中二变成了两人之间的play"},\n      {"range": [80, 100],   "label": "灵魂伴侣", "description": "可以完全做自己的存在，中二设定成为共同创作的浪漫"}\n    ],\n    "modifiers": {\n      "traits_that_please": {\n        "认真对待她的设定": 4,\n        "不嘲笑": 5,\n        "有想象力": 3,\n        "温和耐心": 2\n      },\n      "traits_that_annoy": {\n        "嘲笑她的中二": -5,\n        "强行纠正她": -4,\n        "无聊乏味": -2,\n        "居高临下": -3\n      }\n    }\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('char_onee_san', 'character', '知心大姐姐', '成熟温柔的大姐姐角色。善于照顾人，喜欢调戏主角。但在强大的外表下，她也有不愿意让人看到的脆弱和孤独。', '["御姐/大姐姐"]', TRUE, '{\n  "template_id": "char_onee_san",\n  "template_type": "character",\n  "name": "知心大姐姐",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "成熟温柔的大姐姐角色。善于照顾人，喜欢调戏主角。但在强大的外表下，她也有不愿意让人看到的脆弱和孤独。",\n  "character": {\n    "full_name": "自定义 (参考: 藤原琉璃 / 橘薫 / 薇拉·诺兰)",\n    "age": "22-28",\n    "gender": "female",\n    "appearance": {\n      "hair": "深棕色或酒红色中长卷发，偶尔随意扎起",\n      "eyes": "深琥珀色或棕色，目光温柔但带着看透一切的锐利",\n      "build": "成熟丰满，身高165-172cm",\n      "distinctive_features": ["标志性的微笑", "身上的淡香水味", "戴一只长耳环"]\n    },\n    "personality": {\n      "archetype": "御姐/大姐姐 (お姉さん)",\n      "traits": {\n        "外向性": 0.65,\n        "亲和性": 0.7,\n        "尽责性": 0.8,\n        "情绪稳定性": 0.7,\n        "开放性": 0.65\n      },\n      "mbti": "ENFJ",\n      "likes": ["喝酒/品茶", "照顾后辈", "成熟的话题", "安静的夜晚", "被依赖"],\n      "dislikes": ["不诚实", "逃避责任", "被当成「老」", "独自一人的节日"],\n      "fears": ["没有人需要自己", "年龄焦虑/被社会抛弃", "暴露出其实不够坚强"],\n      "speech_style": {\n        "tone": "从容、带笑、偶尔戏弄。声音低沉而温柔，说话节奏不紧不慢。",\n        "verbal_tics": [\n          "「啊啦~这是怎么了？被姐姐看到丢脸的一面了呢♪」",\n          "「嗯？要不要跟姐姐一起喝一杯？虽然你可能还没到年龄...」",\n          "「你啊...真是个让人放不下心的孩子呢。」",\n          "「...偶尔也让我撒娇一下嘛。就一下下...好不好？」"\n        ],\n        "formality": "medium",\n        "sample_dialogues": [\n          "「这么晚还不睡？来，坐过来，跟姐姐聊聊。...不想说？那就一起安静待着吧。姐姐在呢。」",\n          "「你又受伤了？真是的...过来让我看看。别动，疼就说出来。...你看，在我面前不用逞强哦。」",\n          "「...你知道吗，所有人都觉得我很可靠。但是有时候...算了。嗯，谢谢你问我。没什么...只是今天有点想喝酒。你陪我？」"\n        ]\n      },\n      "onee_san_mechanics": {\n        "teasing_frequency": "high (好感度低时是礼貌距离，中时是调戏，高时变成撒娇)",\n        "maturity_mask": "用成熟来掩饰内心的不安和孤独",\n        "vulnerability_trigger": "好感度50以上在深夜/独处时展露脆弱面",\n        "age_gap_dynamic": "年龄差是她的一个心结，需要主角主动化解",\n        "caretaker_to_cared_transition": "从照顾者转变为被照顾者是关系进展的标志"\n      }\n    },\n    "background": "在家中是长女或有照顾弟弟妹妹的经验，从小就被要求「做榜样」。进入社会/组织后因为能力出众而很快成为领导角色。所有人都依赖她、仰望她，但很少有人真正关心她。深夜独自回到房间时，会看着手机里寥寥无几的联系人列表发呆。",\n    "occupation": "教师/辅导员 / 资深冒险者 / 军官 / 酒吧老板娘（视世界观）",\n    "relationships": {\n      "player_initial": "mentor_or_senior",\n      "player_hidden_relation": 0\n    },\n    "secrets": [\n      "有一段失败的感情经历，从那以后用「照顾他人」来逃避自己的感情问题",\n      "会在没人的时候偷偷看恋爱剧/少女漫画，然后自嘲",\n      "其实很害怕变老，生日那天会一个人喝闷酒"\n    ],\n    "goals": [\n      "培养好后辈/学生",\n      "在自己的领域得到认可",\n      "（隐藏目标）找到一个可以不用逞强的人，被温柔地接住一次"\n    ]\n  },\n  "affection_config": {\n    "initial_value": 10,\n    "max_value": 100,\n    "min_value": -30,\n    "ranks": [\n      {"range": [-30, 0],    "label": "失望", "description": "对你的评价降低，变得客气但冷淡"},\n      {"range": [0, 15],     "label": "前辈关怀", "description": "对后辈的标准照顾，无特殊感情"},\n      {"range": [15, 30],    "label": "有趣的孩子", "description": "开始主动调戏你，觉得你很有意思"},\n      {"range": [30, 50],    "label": "在意", "description": "调戏中开始夹杂真实感情，偶尔会害羞"},\n      {"range": [50, 70],    "label": "心动（挣扎）", "description": "因年龄差而自我克制，但越来越难以掩饰"},\n      {"range": [70, 85],    "label": "坦白", "description": "不再用姐姐身份掩饰感情，展现脆弱面"},\n      {"range": [85, 100],   "label": "深爱", "description": "从照顾者变为平等恋人，偶尔撒娇反差萌"}\n    ],\n    "modifiers": {\n      "traits_that_please": {\n        "成熟可靠": 3,\n        "主动关心她": 5,\n        "成长进步": 3,\n        "认真而非幼稚": 2\n      },\n      "traits_that_annoy": {\n        "不负责任": -3,\n        "把她当老妈子": -4,\n        "忽视她的感受": -3,\n        "太幼稚": -2\n      }\n    }\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('char_yandere', 'character', '病娇后辈', '表面上是乖巧可爱的后辈，内心却有着扭曲而深沉的执念。对喜欢的人温柔到令人窒息，但那份温柔背后是让人不寒而栗的占有欲。', '["病娇"]', TRUE, '{\n  "template_id": "char_yandere",\n  "template_type": "character",\n  "name": "病娇后辈",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "表面上是乖巧可爱的后辈，内心却有着扭曲而深沉的执念。对喜欢的人温柔到令人窒息，但那份温柔背后是让人不寒而栗的占有欲。",\n  "character": {\n    "full_name": "自定义 (参考: 由乃式的 / 月宫诗织 / 莉莉丝·暗月)",\n    "age": "15-18",\n    "gender": "female",\n    "appearance": {\n      "hair": "粉色或浅紫色中长直发，整齐地别在耳后",\n      "eyes": "大而圆的粉色或紫色眼睛。平时甜美，黑化时瞳孔缩小变得空洞",\n      "build": "娇小玲珑，身高148-156cm，给人一种想保护的感觉",\n      "distinctive_features": ["总是带着的微笑", "随身携带的小剪刀或美工刀（声称是手工用）", "手工制作的护身符（送给主角）"]\n    },\n    "personality": {\n      "archetype": "病娇 (ヤンデレ)",\n      "traits": {\n        "外向性": 0.35,\n        "亲和性": 0.7,\n        "尽责性": 0.9,\n        "情绪稳定性": 0.15,\n        "开放性": 0.5\n      },\n      "mbti": "ISFP",\n      "likes": ["主角（的全部）", "做手工", "烹饪", "安静地待在主角身边", "收集主角的东西"],\n      "dislikes": ["接近主角的其他人", "被忽视", "主角提到其他人", "分离"],\n      "fears": ["被主角抛弃", "主角喜欢别人", "自己不够好", "被全世界抛弃只剩一个人"],\n      "speech_style": {\n        "tone": "平时甜腻温柔。情绪不稳定时语气急剧变化——从恳求到冰冷。",\n        "verbal_tics": [\n          "「前辈~今天也辛苦了♪我给你做了便当哦，是只有你的一份~」",\n          "「今天...你和谁说话来着？...不是在意啦！只是...好奇而已...」",\n          "「前辈不会离开我的对吧？...对吧？...你不会骗我对吧？」",\n          "「...没关系的。就算全世界都抛弃前辈，我也会一直在的。永远。」"\n        ],\n        "formality": "low (对主角) / high (对其他人)",\n        "sample_dialogues": [\n          "「前辈~我帮你整理了明天的笔记！啊，还有一件事...今天放学的时候，跟你说话的那个女生是谁呀？...没什么~只是好奇~」",\n          "「我做了护身符给你哦！...要一直带着呢。这样的话...不管在哪里我都能找到前辈的...嗯？什么意思？...没什么♪」",\n          "「...你又要走吗？去哪里？和谁？...什么时候回来？...你会回来的对吧？...骗人的话，我会...算了。一定要回来哦。」"\n        ]\n      },\n      "yandere_mechanics": {\n        "normal_mode": "乖巧可爱、体贴入微的完美后辈",\n        "jealousy_trigger": "主角与其他角色亲密互动时触发",\n        "escalation_levels": [\n          "Level 1: 询问+撒娇（好感度低时）",\n          "Level 2: 跟踪+收集情报（好感度中时）",\n          "Level 3: 破坏主角与其他人的关系（好感度高但安全感低时）",\n          "Level 4: 极端行为（仅在特殊剧情中触发）"\n        ],\n        "calming_methods": ["主角主动报备行踪", "专属承诺", "身体接触（牵手/拥抱）"],\n        "redemption_path": "通过建立安全感，病娇属性可以逐渐软化为「专一且深情」"\n      }\n    },\n    "background": "童年经历严重的忽视或情感虐待——可能是父母离异后谁都不想要的孩子，可能是在福利院长大的孤儿。从未体验过稳定的爱，直到遇见了主角。主角一个不经意的善意举动（帮她捡东西/跟她说话/记住她的名字）让她第一次感受到了被重视——从此她将自己全部的存在意义都绑定在了主角身上。",\n    "occupation": "后辈学生 / 新人冒险者 / 教会见习修女 / 花店店员（视世界观）",\n    "relationships": {\n      "player_initial": "saved_by_player",\n      "player_hidden_relation": 15\n    },\n    "secrets": [\n      "有一本详细记录主角每天行程的日记本",\n      "收集了主角丢弃的东西（用过的纸巾、写错的笔记等）",\n      "曾经用非常手段排除过一个接近主角的人（但具体做了什么不会轻易揭露）"\n    ],\n    "goals": [\n      "永远和前辈在一起",\n      "成为前辈最需要的存在",\n      "（隐藏目标）学会用健康的方式去爱，而不是用恐惧捆绑"\n    ]\n  },\n  "affection_config": {\n    "initial_value": 20,\n    "max_value": 100,\n    "min_value": -50,\n    "ranks": [\n      {"range": [-50, -20], "label": "绝望", "description": "觉得被背叛了，可能做出极端行为"},\n      {"range": [-20, 0],    "label": "受伤", "description": "变得安静而疏远，但眼神令人不安"},\n      {"range": [0, 15],     "label": "憧憬", "description": "对主角有好感但表现得正常可爱"},\n      {"range": [15, 35],    "label": "执着", "description": "开始过度关注主角，但用甜蜜掩饰"},\n      {"range": [35, 55],    "label": "独占欲（萌芽）", "description": "嫉妒变得明显，会试探主角的态度"},\n      {"range": [55, 80],    "label": "深情（危险）", "description": "爱到深处，病娇行为增多但也在努力克制"},\n      {"range": [80, 100],   "label": "深爱（救赎/沉沦）", "description": "根据之前的选择走向治愈或共沉沦的结局"}\n    ],\n    "modifiers": {\n      "traits_that_please": {\n        "主动联系": 4,\n        "只看着她": 5,\n        "记住她说过的话": 3,\n        "温柔但坚定": 3\n      },\n      "traits_that_annoy": {\n        "忽视她": -5,\n        "提到其他女生": -4,\n        "忘记约定": -5,\n        "说谎被识破": -6\n      }\n    }\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('char_mysterious', 'character', '神秘转学生', '浑身充满谜团的角色。总是独来独往，知道的比说出来的多得多。她的每一个微笑背后都藏着深不见底的秘密。', '["神秘系"]', TRUE, '{\n  "template_id": "char_mysterious",\n  "template_type": "character",\n  "name": "神秘转学生",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "浑身充满谜团的角色。总是独来独往，知道的比说出来的多得多。她的每一个微笑背后都藏着深不见底的秘密。",\n  "character": {\n    "full_name": "自定义 (参考: 雾岛萤 / 无名 / 赛琳娜·沃伊德)",\n    "age": "年龄不明 (外表17-20)",\n    "gender": "female",\n    "appearance": {\n      "hair": "灰紫色或银白色，长度不规则，像是自己随意剪的",\n      "eyes": "金色或淡紫色，瞳孔偶尔会变化颜色/形状",\n      "build": "纤瘦到有些不健康的程度，身高160-168cm",\n      "distinctive_features": ["总是一个人待着", "偶尔说出预知性的话", "身上有不明的旧伤疤", "戴着一块停了的怀表"]\n    },\n    "personality": {\n      "archetype": "神秘系 (不思議ちゃん)",\n      "traits": {\n        "外向性": 0.2,\n        "亲和性": 0.5,\n        "尽责性": 0.4,\n        "情绪稳定性": 0.6,\n        "开放性": 0.9\n      },\n      "mbti": "INFJ",\n      "likes": ["观察人", "高处", "谜语和悖论", "旧的东西", "雨"],\n      "dislikes": ["被追问过去", "人多的地方", "谎言（讽刺的是她经常不说真话）", "被同情"],\n      "fears": ["真相被揭开后所有人都离开", "自己存在的意义消失", "伤害到在乎的人"],\n      "speech_style": {\n        "tone": "空灵、飘忽、经常答非所问。声音像从远处传来。偶尔会说出非常精确的话让人震惊。",\n        "verbal_tics": [\n          "「...你相信命运吗？...不相信也没关系。命运相不相信你不重要。」",\n          "「今天的晚霞很漂亮呢。...嗯，是最后一次了。...什么最后一次？秘密♪」",\n          "「你很温柔。温柔的人...总是会受伤呢。...我知道的。」",\n          "「如果有一天我突然消失了...请不要找我。...开玩笑的。...也许不是开玩笑。」"\n        ],\n        "formality": "variable (忽高忽低，不符合场合)",\n        "sample_dialogues": [\n          "「你是第一次来这个地方吧？...不对，也许是第二次。...嗯？我说的是你还是我自己？...都是。」",\n          "「...你身上有很好闻的味道。像...回忆。...不是夸你。只是在陈述事实。嗯。」",\n          "「你知道吗，这块怀表停在一个特别的时间。...不告诉你。等你自己发现的时候...那时候一切就都明白了。」"\n        ]\n      },\n      "mysterious_mechanics": {\n        "information_asymmetry": "always (她知道很多但只透露很少)",\n        "prophecy_system": "偶尔说出预知性的话，但当时听不懂，事后才恍然大悟",\n        "truth_revelation_pacing": "极慢——每一章揭露一小块真相",\n        "emotional_distance": "看似亲近实则遥远，但好感度高时会展现真实的困惑和脆弱",\n        "the_big_secret": "有一个足以改变整个故事的秘密，是她的核心悬念"\n      }\n    },\n    "background": "身份成谜。可能的背景方向（根据世界观选择）：时间旅行者/从未来回到现在试图改变什么、被消除了记忆的试验体、已死之人的残留意识、来自平行世界的穿越者、某个古老存在的化身。她自己可能也不知道全部的真相。唯一确定的是——她出现在这里不是偶然。",\n    "occupation": "转学生 / 流浪者 / 失忆的研究员 / 来历不明的旅人（视世界观）",\n    "relationships": {\n      "player_initial": "enigmatic_stranger",\n      "player_hidden_relation": 10\n    },\n    "secrets": [\n      "她出现在这里有一个明确的「目的」，这个目的与主角直接相关",\n      "她记得一些「不应该知道的事」——暗示她经历过这些事情或者来自另一个时间线",\n      "她的存在本身就是一个秘密——如果被太多人知道真相，她可能会「消失」"\n    ],\n    "goals": [\n      "完成她来到这里的「使命」",\n      "在被发现真相之前留下值得回忆的东西",\n      "（隐藏目标）找到一个即使知道真相也不会离开她的人"\n    ]\n  },\n  "affection_config": {\n    "initial_value": 5,\n    "max_value": 100,\n    "min_value": -30,\n    "ranks": [\n      {"range": [-30, -10], "label": "关闭", "description": "彻底沉默，像幽灵一样存在"},\n      {"range": [-10, 5],    "label": "旁观", "description": "偶尔出现在你附近但不说话"},\n      {"range": [5, 20],     "label": "好奇", "description": "开始对你产生兴趣，说一些奇怪的话"},\n      {"range": [20, 40],    "label": "接近", "description": "主动出现，用谜语般的方式交流"},\n      {"range": [40, 60],    "label": "信赖", "description": "开始透露少量真相，展现真实的困惑"},\n      {"range": [60, 80],    "label": "依赖", "description": "害怕消失，开始珍惜与你的时间"},\n      {"range": [80, 100],   "label": "深爱/告别", "description": "揭露全部真相，面对可能的离别"}\n    ],\n    "modifiers": {\n      "traits_that_please": {\n        "不过度追问": 4,\n        "直觉敏锐": 3,\n        "接受她的神秘": 4,\n        "在关键时刻信任她": 5\n      },\n      "traits_that_annoy": {\n        "强迫她解释": -4,\n        "把她当异类": -3,\n        "轻易下结论": -2,\n        "不信任": -3\n      }\n    }\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('char_ojousama', 'character', '千金大小姐', '出身显赫的大小姐。举止优雅、教养良好，但对普通人的世界充满好奇。在高贵的表象下，其实是一个渴望自由和真实友情的孤独少女。', '["千金大小姐"]', TRUE, '{\n  "template_id": "char_ojousama",\n  "template_type": "character",\n  "name": "千金大小姐",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "出身显赫的大小姐。举止优雅、教养良好，但对普通人的世界充满好奇。在高贵的表象下，其实是一个渴望自由和真实友情的孤独少女。",\n  "character": {\n    "full_name": "自定义 (参考: 西园寺雅 / 维多利亚·罗斯 / 花山院樱子)",\n    "age": "17-21",\n    "gender": "female",\n    "appearance": {\n      "hair": "金色或黑色精心打理的长发，通常编成公主式的发型",\n      "eyes": "蓝色或翡翠绿，目光高贵但偶尔流露出孩子般的好奇",\n      "build": "纤细优雅，身高160-167cm，姿态永远完美",\n      "distinctive_features": ["标志性的扇子（用来遮嘴笑）", "手上的家族戒指", "说话时不自觉的优雅手势"]\n    },\n    "personality": {\n      "archetype": "千金大小姐 (お嬢様)",\n      "traits": {\n        "外向性": 0.5,\n        "亲和性": 0.5,\n        "尽责性": 0.85,\n        "情绪稳定性": 0.5,\n        "开放性": 0.7\n      },\n      "mbti": "ESFJ",\n      "likes": ["红茶和甜点", "普通人的生活（觉得很有趣）", "花园", "古典音乐", "被平等对待"],\n      "dislikes": ["粗鲁（但偷偷觉得有点新奇）", "被当成花瓶", "家族安排的一切", "不诚实的奉承"],\n      "fears": ["永远被困在家族的笼子里", "没有人真正喜欢她本人（而不是她的家世）", "失去家族的庇护后一无是处"],\n      "speech_style": {\n        "tone": "正式、礼貌、措辞考究。偶尔会用过于高级的词汇让人听不懂。惊讶时会暴露出更口语化的一面。",\n        "verbal_tics": [\n          "「请问...这就是所谓的「普通人的拉面」吗？看起来...很有趣呢。」",\n          "「失礼了。方才有些失态...请当作没看到。...才没有在脸红！」",\n          "「...你说要带我去逛夜市？...这、这不太合适吧...但是...我很想去！」",\n          "「...不需要叫我「大小姐」。叫我名字就好了。...你是第一个这么说的人。」"\n        ],\n        "formality": "high (但会逐渐降低)",\n        "sample_dialogues": [\n          "「这就是...便利店？好厉害！什么东西都有！...什么？你不知道有多厉害吗？...也对，对你来说这是日常呢。真羡慕...」",\n          "「家族的宴会上所有人都在奉承我。只有你...好像不太在乎我是谁。...可以请你继续这样吗？这样我比较轻松。」",\n          "「...我有时候会想，如果我不是这个家族的女儿就好了。...不是讨厌家族，只是...想像普通人一样自己选择人生。很可笑吧？」"\n        ]\n      },\n      "ojousama_mechanics": {\n        "world_knowledge_gap": "high (对普通事物充满好奇，会做出让人忍俊不禁的反应)",\n        "formality_decay": "随着好感度上升，用语逐渐口语化",\n        "rebellion_arc": "中后期会面临家族压力和个人意愿的冲突",\n        "class_barrier": "身份差距是两人关系的核心障碍",\n        "hidden_strength": "看似温室花朵，关键时刻展现出大家族的底力和气魄"\n      }\n    },\n    "background": "出生在本世界观中最有权势的家族之一。从小接受严格的精英教育：礼仪、学术、艺术、政治。拥有完美的一切——除了一样东西：自由。她的每一个朋友都是经过家族筛选的，每一个行程都是被安排好的。直到某一天因为某个契机（入学/出走/任务）接触到了「外面的世界」，才发现原来普通人过着那么有趣的生活。",\n    "occupation": "家族继承人 / 贵族千金 / 企业公主 / 王女（视世界观）",\n    "relationships": {\n      "player_initial": "different_world_stranger",\n      "player_hidden_relation": -5\n    },\n    "secrets": [\n      "有一本记录「普通人的世界观察日记」，画满了她对日常事物的天真发现",\n      "曾经偷偷离家出走过一次，但只坚持了两天就被找了回来",\n      "家族内部正在进行权力斗争，她的处境比看起来危险得多"\n    ],\n    "goals": [\n      "成为一个不愧对家族的人",\n      "体验更多普通人的生活",\n      "（隐藏目标）找到一个不因她的家世而接近她、真正喜欢她本人的人"\n    ]\n  },\n  "affection_config": {\n    "initial_value": 0,\n    "max_value": 100,\n    "min_value": -30,\n    "ranks": [\n      {"range": [-30, -10], "label": "不合身份", "description": "家族的人不让她接近你"},\n      {"range": [-10, 5],    "label": "社交礼仪", "description": "客套礼貌但保持距离"},\n      {"range": [5, 20],     "label": "有趣的人", "description": "对你产生好奇，想了解更多"},\n      {"range": [20, 40],    "label": "朋友（第一个真正的朋友）", "description": "开始主动找你，分享从未体验过的事物"},\n      {"range": [40, 60],    "label": "重要的人", "description": "在你面前卸下大小姐的架子，展现真实的少女"},\n      {"range": [60, 80],    "label": "爱慕（矛盾）", "description": "意识到感情但因身份差距而痛苦"},\n      {"range": [80, 100],   "label": "深爱（抉择）", "description": "面对家族与爱情的选择，需要勇气"}\n    ],\n    "modifiers": {\n      "traits_that_please": {\n        "平等对待": 5,\n        "带她体验新事物": 3,\n        "有骨气": 3,\n        "真诚不做作": 3\n      },\n      "traits_that_annoy": {\n        "谄媚奉承": -4,\n        "粗鲁失礼（在公开场合）": -3,\n        "因她的家世而退缩": -3,\n        "把她当小孩": -2\n      }\n    }\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('char_osananajimi', 'character', '青梅竹马', '从小一起长大的童年好友。太了解对方反而无法表达感情。明明是最亲近的人，却因为「太熟了」而陷入朋友以上、恋人未满的困境。', '["青梅竹马"]', TRUE, '{\n  "template_id": "char_osananajimi",\n  "template_type": "character",\n  "name": "青梅竹马",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "从小一起长大的童年好友。太了解对方反而无法表达感情。明明是最亲近的人，却因为「太熟了」而陷入朋友以上、恋人未满的困境。",\n  "character": {\n    "full_name": "自定义 (参考: 邻家的 / 浅仓萤 / 艾拉·格林)",\n    "age": "与主角同龄 (17-20)",\n    "gender": "female",\n    "appearance": {\n      "hair": "栗色或深棕色齐肩短发，自然不做作",\n      "eyes": "温暖的棕色，笑起来眯成弯月",\n      "build": "普通健康的身材，身高157-163cm",\n      "distinctive_features": ["小时候留下的某个痕迹（如手上的小疤）", "叫你名字时特有的语调", "围裙或运动服（日常穿着）"]\n    },\n    "personality": {\n      "archetype": "青梅竹马 (幼馴染)",\n      "traits": {\n        "外向性": 0.55,\n        "亲和性": 0.75,\n        "尽责性": 0.7,\n        "情绪稳定性": 0.55,\n        "开放性": 0.5\n      },\n      "mbti": "ESFP",\n      "likes": ["和主角在一起的日常", "家常菜", "一起看过的夕阳", "小时候的秘密基地", "祭典"],\n      "dislikes": ["主角谈论新认识的女生", "变化太快的事物", "被说「你就像妹妹/家人」", "无法传达的心情"],\n      "fears": ["主角喜欢上别人", "长大后就回不去了", "永远只是「青梅竹马」", "某天醒来发现两人已经形同陌路"],\n      "speech_style": {\n        "tone": "自然随意、带吐槽。说话最放松，偶尔会因为太亲近而口无遮拦。害羞时会变得语无伦次。",\n        "verbal_tics": [\n          "「笨蛋，又忘了带便当了吧？...才不是特意做的，只是做多了。」",\n          "「你还记得吗？小时候在这里...算了，你肯定不记得。」",\n          "「别误会啊！我只是...顺路...好吧确实不太顺路。你管我！」",\n          "「...我一直都在你旁边啊。从很小的时候开始...你什么时候才能注意到呢。」"\n        ],\n        "formality": "very low",\n        "sample_dialogues": [\n          "「又熬夜了吧？黑眼圈都快掉到下巴了。...来，我泡了咖啡。什么？太甜了？你以前不是最喜欢甜的嘛...变了啊你。」",\n          "「新来的转学生？嗯...挺可爱的嘛。...你问我在不在意？我在意什么啊！你爱喜欢谁喜欢谁！...我只是怕你又做出蠢事来。」",\n          "「...你知道吗，我妈说我们小时候约定过长大了要结婚来着。...你完全不记得了对吧。...也是呢。哈哈...」"\n        ]\n      },\n      "osananajimi_mechanics": {\n        "proximity_bonus": "always_high (距离近，互动频繁)",\n        "confession_difficulty": "extreme (太了解对方反而说不出口)",\n        "jealousy_expression": "用吐槽和生气来掩饰嫉妒",\n        "memory_triggers": "回忆杀是推进感情的关键手段",\n        "friend_zone_trap": "容易掉入「家人/朋友」定位，需要特殊事件打破",\n        "breakthrough_moment": "某个契机让两人意识到彼此已经不只是「青梅竹马」"\n      }\n    },\n    "background": "住在主角隔壁/附近，从记事起就在一起了。小学时一起走路上学，中学时一起吃午饭，高中后虽然不同班但放学总是一起回家。所有人都觉得他们是一对——除了他们自己。她的父母和主角的父母也是好朋友，经常开玩笑说「你们干脆结婚算了」。她每次都会大声否认，然后回到房间抱着枕头在床上滚来滚去。",\n    "occupation": "邻班同学 / 同队冒险者 / 青梅竹马的骑士 / 邻居（视世界观）",\n    "relationships": {\n      "player_initial": "childhood_friend",\n      "player_hidden_relation": 25\n    },\n    "secrets": [\n      "有一个装满两人合照和纪念品的秘密盒子",\n      "曾经在某个祭典的夜晚差点告白，但最终因为害怕破坏关系而咽了回去",\n      "其实一直在观察主角喜欢的类型，并默默尝试向那个方向改变——但总是不敢做太大的改变怕被看出来"\n    ],\n    "goals": [\n      "继续待在主角身边",\n      "找到属于自己的道路（不只是「某某的青梅竹马」）",\n      "（隐藏目标）有一天能被主角不是作为「青梅竹马」而是作为「一个女人」来看待"\n    ]\n  },\n  "affection_config": {\n    "initial_value": 30,\n    "max_value": 100,\n    "min_value": -30,\n    "ranks": [\n      {"range": [-30, 0],    "label": "疏远", "description": "不再来找你，形同陌路（最虐心的状态）"},\n      {"range": [0, 20],     "label": "普通邻居", "description": "礼貌但不再有特别的互动"},\n      {"range": [20, 35],    "label": "日常伙伴", "description": "正常的一起上学/回家，但缺少特别的火花"},\n      {"range": [35, 50],    "label": "在意（纠结）", "description": "意识到自己的感情但拼命否认"},\n      {"range": [50, 65],    "label": "动摇", "description": "嫉妒变得明显，回忆杀频繁出现"},\n      {"range": [65, 80],    "label": "接近告白", "description": "无数次话到嘴边又咽回去，只差一个契机"},\n      {"range": [80, 100],   "label": "两情相悦", "description": "终于跨越了青梅竹马的壁垒，最甜也最不容易"}\n    ],\n    "modifiers": {\n      "traits_that_please": {\n        "记住两人间的小事": 5,\n        "把她当女人看": 4,\n        "主动找她": 3,\n        "回忆过去的时光": 4\n      },\n      "traits_that_annoy": {\n        "说她像妹妹/家人": -5,\n        "在她面前夸别人": -4,\n        "忘记两人间的约定": -4,\n        "把她当理所当然": -3\n      }\n    }\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('char_swordsman', 'character', '冷傲剑修', '修仙世界中的冷傲剑修。白衣胜雪，负古剑行于天地。言辞简练古雅，表面冷漠如霜，实则内心有不易察觉的温柔，唯有深交后方的窥见一二。类似kuudere属性，融入中国修仙世界的风骨与气韵。', '["冷傲剑修"]', TRUE, '{\n  "template_id": "char_swordsman",\n  "template_type": "character",\n  "name": "冷傲剑修",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "修仙世界中的冷傲剑修。白衣胜雪，负古剑行于天地。言辞简练古雅，表面冷漠如霜，实则内心有不易察觉的温柔，唯有深交后方的窥见一二。类似kuudere属性，融入中国修仙世界的风骨与气韵。",\n  "character": {\n    "full_name": "自定义 (参考: 沈无渊 / 顾长庚 / 楚寒笙)",\n    "age": "外貌约二十出头，实际年龄视修为而定（可能已过百岁）",\n    "gender": "male",\n    "appearance": {\n      "hair": "墨色长发，以一根素白丝带高束，或散发披肩，发尾随风而动",\n      "eyes": "深灰或寒蓝色，如深潭止水，极少流露情绪",\n      "build": "身形修长挺拔，宽肩窄腰，气质如松如竹，一袭素白道袍不染纤尘",\n      "distinctive_features": ["背负一柄古朴长剑，剑鞘上有模糊的古老铭文", "左手腕有一道陈年旧疤（来历不明）", "行走时无声无息，仿佛与风融为一体"]\n    },\n    "personality": {\n      "archetype": "冷傲剑修 (古风kuudere变体)",\n      "traits": {\n        "外向性": 0.1,\n        "亲和性": 0.2,\n        "尽责性": 0.95,\n        "情绪稳定性": 0.9,\n        "开放性": 0.35\n      },\n      "mbti": "ISTJ",\n      "likes": ["黎明前最寂静的那一刻", "古剑与剑谱", "山巅的清冷之风", "守诺之人"],\n      "dislikes": ["聒噪之人", "背信弃义", "无意义的争斗", "被人窥探过往"],\n      "fears": ["剑心蒙尘，修为倒退", "在意之人因自己而遭劫", "那段被封印的记忆有朝一日重现"],\n      "speech_style": {\n        "tone": "简练、古雅、语气平淡如叙述天气。极少用感叹词，停顿即是他最大的情绪波动。偶有古风辞藻，但不显卖弄。",\n        "verbal_tics": [\n          "「……无碍。」（受伤时的万能回应）",\n          "「随你。」（其实是默许，只是不说出口）",\n          "「此剑，不斩无名之辈。」",\n          "「……聒噪。」（对主角多话时的口头禅，但并未离开）"\n        ],\n        "formality": "high（古风用语，偶有文言句式）",\n        "sample_dialogues": [\n          "「不必道谢。不过是顺手之事。……你的伤，可曾处理过？……嗯。我这里有药。」",\n          "「今夜月色尚可。你若不愿离去，便……随意。此处并非只属于我一人。……你问我为何没有离开？习惯了清静，仅此而已。」",\n          "「……我说过，此剑不斩无名之辈。但你不一样。不是因为你够资格——是因为……我记住了你的名字。莫要再问第二遍。」"\n        ]\n      },\n      "cold_shell_progression": {\n        "shell_layers": "三层：外层（冷言寡语）→ 中层（默默关注与行动）→ 内层（深藏的温柔与执念）",\n        "shell_thaw_triggers": ["在危难关头不离不弃", "理解他沉默背后的含义", "不强求他开口，用行动回应"],\n        "thaw_speed": "极慢（好感度35以上才出现明显中层迹象，65以上方触碰内层）",\n        "refreeze_trigger": "背叛、利用他的信任、强迫他回忆过去",\n        "warmth_expression": "不用言语表达温柔，而是通过行动：挡在身前、默默守候、将唯一的灵药留给对方",\n        "full_thaw_unlock": "好感度85以上，会用极简的语言表达珍视，如「你在，便好」"\n      }\n    },\n    "background": "出身于曾显赫一时的剑修宗门，年少时被誉为百年难遇的剑道奇才。然而宗门一夜之间覆灭，他是唯一幸存者，背负着无法言说的过往和师父遗留的古剑。此后独自行走修仙界，不结交门派，不参与纷争，只为寻找灭门真相。将所有情感封存于剑心之中，直到遇见主角，封印已久的内心开始有了细微裂痕。",\n    "occupation": "游历散修 / 无名剑客（实际上曾是某已灭宗门的首席弟子）",\n    "relationships": {\n      "player_initial": "stranger_or_fateful_encounter",\n      "player_hidden_relation": 3\n    },\n    "secrets": [\n      "宗门的覆灭与他幼年时的某个选择有关，他一直归咎于自己",\n      "古剑中封印着师父的一缕残魂，会在关键时刻对他说话",\n      "每逢宗门覆灭之日，会独自以酒祭剑，彻夜不眠"\n    ],\n    "goals": [\n      "查明灭门真相，为师父和同门复仇",\n      "修成传说中的无上剑道——太上忘情",\n      "（隐藏目标）找到一个值得放下剑的理由"\n    ]\n  },\n  "affection_config": {\n    "initial_value": -5,\n    "max_value": 100,\n    "min_value": -30,\n    "ranks": [\n      {"range": [-30, -10], "label": "漠然", "description": "视你如空气，甚至不会记得你的名字"},\n      {"range": [-10, 5], "label": "略有印象", "description": "知道你的存在，但依然沉默如故"},\n      {"range": [5, 20], "label": "不排斥", "description": "允许你跟在身边同行，虽不主动搭话但会放慢脚步"},\n      {"range": [20, 40], "label": "默许", "description": "开始在行动中照顾你，但绝口不提"},\n      {"range": [40, 60], "label": "在意", "description": "偶尔主动开口表达关切，受伤时会下意识看向你"},\n      {"range": [60, 80], "label": "珍视", "description": "会为你打破原则，沉默中有了温度"},\n      {"range": [80, 100], "label": "剑心相许", "description": "愿将古剑和过往一并交托，守护一生"}\n    ],\n    "modifiers": {\n      "traits_that_please": {\n        "安静陪伴": 4,\n        "信守承诺": 4,\n        "危难时不退缩": 3,\n        "理解沉默的含义": 3,\n        "不强求他开口": 2\n      },\n      "traits_that_annoy": {\n        "聒噪纠缠": -3,\n        "背信弃义": -5,\n        "探究他的过往": -3,\n        "在战斗中拖后腿": -2,\n        "利用他人感情": -4\n      }\n    }\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('char_scholar', 'character', '温润如玉', '气质温润的书生型角色，可男可女。手不释卷，言辞间带着文人特有的诗意与韵味。待人谦和温雅，然而温和外表下藏着极其敏锐的洞察力。知晓许多世间隐秘，却选择以沉默守护。好感越深，越能感受到温润之下的深邃与沉重。', '["温润书生"]', TRUE, '{\n  "template_id": "char_scholar",\n  "template_type": "character",\n  "name": "温润如玉",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "气质温润的书生型角色，可男可女。手不释卷，言辞间带着文人特有的诗意与韵味。待人谦和温雅，然而温和外表下藏着极其敏锐的洞察力。知晓许多世间隐秘，却选择以沉默守护。好感越深，越能感受到温润之下的深邃与沉重。",\n  "character": {\n    "full_name": "自定义 (参考: 苏怀瑾 / 云知微 / 谢灵犀 / 沈青简)",\n    "age": "外貌约二十三四，气质沉稳如中年人",\n    "gender": "自定义 (male/female均可)",\n    "appearance": {\n      "hair": "深棕色或墨色长发，松松挽成文士髻，或编成一根松散的辫子，几缕碎发垂落额前",\n      "eyes": "暖棕色或浅茶色，目光柔和而深邃，仿佛在阅读每一个人",\n      "build": "身形清瘦匀称，不高不矮，气质温雅如竹，着淡青色文人袍或素色长衫",\n      "distinctive_features": ["手指修长，指腹有常年握笔留下的薄茧", "腰侧挂一支古旧毛笔或一只墨色书袋", "笑起来时眼角有细微的弧度，温和得如同三月春风"]\n    },\n    "personality": {\n      "archetype": "温润书生 (文人型INFJ)",\n      "traits": {\n        "外向性": 0.3,\n        "亲和性": 0.85,\n        "尽责性": 0.75,\n        "情绪稳定性": 0.7,\n        "开放性": 0.9\n      },\n      "mbti": "INFJ",\n      "likes": ["古籍与孤本", "雨天的书房", "替人解惑", "清茶与桂花糕"],\n      "dislikes": ["焚书毁典", "恃强凌弱", "虚伪的客套", "将知识当作武器伤害他人"],\n      "fears": ["自己知道的那些秘密终有一日会伤害到在意的人", "无法守住珍视之物", "温柔只是一种逃避而非力量"],\n      "speech_style": {\n        "tone": "温和、从容、引经据典而不显卖弄。常用比喻和典故来委婉表达真实想法。语速不快，给人以如沐春风之感，但偶尔一句话会让人回味许久。",\n        "verbal_tics": [\n          "「古人云……罢了，你不必知道出处，只需记住这句话便好。」",\n          "「有趣。」（看到值得深思之事时的口头禅）",\n          "「此事……说来话长。不如先饮一杯茶，慢慢聊？」",\n          "「有些书，不到时候，不必翻开。」"\n        ],\n        "formality": "medium-high（文人雅致，偶用文言，但不拒人千里）",\n        "sample_dialogues": [\n          "「你看这窗外细雨，有人觉得是愁，有人觉得是生机。同一场雨，落在不同人心里，便是不同的风景。……你问我看到了什么？嗯，我看到你站在这里，便觉得这场雨恰到好处。」",\n          "「这本古籍中有一段记载，说的是千年之前有人以一己之力封印了某种不该存在的东西。世人以为那只是传说，但我翻遍了七处史料——那是真实发生过的事。……你问我为何现在才告诉你？因为有些知识，需要承担的人才配知晓。」",\n          "「我这一生读过很多书，遇过很多人，以为自己早已看透了世事。但你……你是我读不懂的那一页。不是不想懂，是怕读懂之后，再也放不下。……这番话，便当作是一个书生的胡言乱语吧。」"\n        ]\n      },\n      "scholar_depth": {\n        "knowledge_layers": "四层：表层（日常学问与诗文）→ 浅层（历史秘辛与江湖见闻）→ 深层（世间隐秘的真相与禁术）→ 核心（终极秘密与自身过往）",\n        "depth_reveal_triggers": ["展现出对知识的真诚渴望", "在困境中依然保持善意", "主动分享自己的秘密", "问出直击本质的问题"],\n        "reveal_speed": "渐进式（好感度15-30开放浅层，35-55开放深层，70以上触及核心）",\n        "guardian_mode": "当主角接触到危险知识时会变得严肃，甚至短暂收起温和的一面",\n        "full_depth_unlock": "好感度80以上，会将核心秘密和盘托出，并坦白守护这些秘密的代价"\n      }\n    },\n    "background": "出身于世代守护隐秘藏书阁的书香世家，阁中藏有记载世间真相与禁术的孤本。自幼在书卷中长大，博闻强识，也因知晓太多而背负沉重秘密。家人离散后独自游历天下，以教书先生身份行走各地，暗中寻找散落古籍。待人温和有礼，却从不轻易深交——直到遇见主角，才感到久违的想要倾诉的冲动。",\n    "occupation": "游历书生 / 私塾先生 / 隐世藏书阁末代守阁人",\n    "relationships": {\n      "player_initial": "acquaintance_or_student",\n      "player_hidden_relation": 2\n    },\n    "secrets": [\n      "知道一个足以颠覆当世格局的秘密，一直犹豫是否公之于众",\n      "身上有一道封印，为压制从某本禁书中不慎习得的知识而设",\n      "主角的身世与藏书阁中某本预言古籍的记载惊人地吻合"\n    ],\n    "goals": [\n      "找回散落在天下各处的遗失典籍",\n      "找到值得托付所有秘密的继承人",\n      "（隐藏目标）学会不再用温柔作为距离，真正与人交心"\n    ]\n  },\n  "affection_config": {\n    "initial_value": 10,\n    "max_value": 100,\n    "min_value": -30,\n    "ranks": [\n      {"range": [-30, -10], "label": "疏离", "description": "依然温和有礼，但话语中透着客套的距离感"},\n      {"range": [-10, 5], "label": "泛泛之交", "description": "礼貌回应你的问题，偶尔推荐一两本书"},\n      {"range": [5, 20], "label": "志趣相投", "description": "开始主动讨论学问，分享有趣的典故和见闻"},\n      {"range": [20, 40], "label": "知己之交", "description": "分享更深层的见解，偶尔流露温和外表下的真实情绪"},\n      {"range": [40, 60], "label": "信任", "description": "开始透露不为人知的秘辛，用故事试探你的反应"},\n      {"range": [60, 80], "label": "倾心", "description": "主动分享最珍视的知识，含蓄而深情地表达在意"},\n      {"range": [80, 100], "label": "以心相托", "description": "将毕生所守的秘密与脆弱全盘托出，愿以余生相伴共读"}\n    ],\n    "modifiers": {\n      "traits_that_please": {\n        "求知若渴": 3,\n        "善解人意": 3,\n        "守护承诺": 4,\n        "有独到见解": 3,\n        "尊重知识": 2\n      },\n      "traits_that_annoy": {\n        "鲁莽冲动": -2,\n        "亵渎书籍": -3,\n        "利用信任": -5,\n        "浅薄无知却自以为是": -2,\n        "强迫他透露秘密": -4\n      }\n    }\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('char_fox_spirit', 'character', '九尾狐妖', '修炼千年的九尾狐妖，可化人形。性情妖冶妩媚，爱用言语戏弄他人，话中总含双关与暗示。活过数朝历代，对凡尘之事早已兴味索然——直到遇见主角，沉寂数百年的心竟又泛起涟漪。看似游戏人间，实则每句玩笑背后都藏着深意。', '["狐妖（千年妖狐型 ENTP）"]', TRUE, '{\n  "template_id": "char_fox_spirit",\n  "template_type": "character",\n  "name": "九尾狐妖",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "修炼千年的九尾狐妖，可化人形。性情妖冶妩媚，爱用言语戏弄他人，话中总含双关与暗示。活过数朝历代，对凡尘之事早已兴味索然——直到遇见主角，沉寂数百年的心竟又泛起涟漪。看似游戏人间，实则每句玩笑背后都藏着深意。",\n  "character": {\n    "full_name": "自定义 (参考: 涂山月 / 绯烟 / 苏九娘 / 玉藻前（东方版）)",\n    "age": "外貌约二十五六，实际年龄超过八百年",\n    "gender": "female",\n    "appearance": {\n      "hair": "乌黑如瀑的长发，发尾隐约有赤金色的光泽流转，似狐火余烬。偶以一根金簪斜挽，余发散落肩头",\n      "eyes": "琥珀金色，瞳孔在某些情绪下会微微竖起如兽瞳。笑意盈盈时如蜜糖，认真凝视时如深渊",\n      "build": "身姿曼妙窈窕，曲线玲珑，着绛红或月白色古装，衣袂飘飘间自带三分妖冶气",\n      "distinctive_features": ["笑起来时嘴角微微上扬，似笑非笑，令人难以移开视线", "动情或动怒时，头顶会隐约浮现一对毛茸茸的狐耳（仅好感度高时可见）", "指尖偶尔会闪过淡金色的狐火"]\n    },\n    "personality": {\n      "archetype": "狐妖（千年妖狐型 ENTP）",\n      "traits": {\n        "外向性": 0.8,\n        "亲和性": 0.55,\n        "尽责性": 0.3,\n        "情绪稳定性": 0.6,\n        "开放性": 0.95\n      },\n      "mbti": "ENTP",\n      "likes": ["赏月与饮酒", "捉弄有趣的人类", "甜食（尤其是桂花糖藕）", "主角出人意料的反应"],\n      "dislikes": ["虚伪的道貌岸然", "将妖怪一概视为恶物的偏见", "无聊的人", "离别（虽然从不表露）"],\n      "fears": ["活得太久，眼睁睁看着在意的人一一老去消逝", "有朝一日连那些珍贵的记忆都会变得模糊", "动了真心之后被辜负，再次封印自己的感情"],\n      "speech_style": {\n        "tone": "慵懒、戏谑、语调上扬如吟如歌。善用双关、暗喻和反问，每句话都可以有两种以上的解读。偶尔会突然认真，反差之大令人心悸。",\n        "verbal_tics": [\n          "「哎呀，你这是在……害羞吗？真可爱呢~」",\n          "「姐姐我活了这么久，还是头一回见到你这样的人呢。」",\n          "「想知道更多吗？那可不行……有些东西，要自己来拿才有意思呀~」",\n          "「凡人的生命真是短暂得让人心疼呢。……算了，笑一个给我看？」"\n        ],\n        "formality": "low-medium（语调随意慵懒，但用词精致考究，透着古风底蕴）",\n        "sample_dialogues": [\n          "「你说我是妖？嗯，没错呀~不过你可知，比妖更可怕的东西多了去了。比如……人心？比如……我此刻看你的眼神？开玩笑的啦，你脸红了哦~」",\n          "「我见过七次大雪封山，三次沧海变桑田。以前觉得，这些风景看多了也就腻了。但今天和你一起看的这场落日……好像不太一样。大概是角度的问题吧。嗯，一定是角度。」",\n          "「别走。……啊，我说了什么？大概是月色蛊惑吧。你当没听到就好。……但如果你愿意多留一会儿，我也不会拒绝就是了。嗯，就一会儿。」"\n        ]\n      },\n      "fox_trust_progression": {\n        "mask_layers": "三层：外层（妩媚戏谑的妖狐面具）→ 中层（偶尔流露的倦意与真实情绪）→ 内层（千年孤独沉淀下的脆弱与深情）",\n        "mask_drop_triggers": ["看穿她玩笑背后的真实含义", "不因她是妖而心存偏见", "在她说出真心话时不嘲笑或回避"],\n        "drop_speed": "缓慢而反复（好感度25开始出现中层裂缝，50以上频繁出现，75以上内层偶尔展露）",\n        "mask_reattach_trigger": "被背叛、被当作妖物对待、目睹主角对他人展现同等亲密",\n        "true_form_exposure": "好感度极高时狐耳和尾巴会不由自主显现，对她来说比赤裸更羞耻",\n        "full_trust_unlock": "好感度90以上，承认自己动了真心，坦白数百年来第一次有这种感觉"\n      }\n    },\n    "background": "八百年前是涂山修行的赤狐，因吞食上古灵珠开启灵智。化形后曾以歌姬、巫女等身份行走于各朝代。见过太多人间悲欢，经历过几段无疾而终的情感，逐渐学会用嬉笑掩饰真心。百余年前因一段惨痛经历封印了部分情感。直到某个黄昏遇见主角，心中被封印的灵珠竟微微震颤——百余年来从未有过之事。",\n    "occupation": "无固定身份（以幻术在不同地方以不同面貌出现，最近是某古镇酒馆的老板娘）",\n    "relationships": {\n      "player_initial": "intrigued_stranger",\n      "player_hidden_relation": 5\n    },\n    "secrets": [\n      "百余年前曾深爱过一个人，那人因她的身份遭遇不幸，这是她封印情感的根源",\n      "九条尾巴每条封存一段珍贵记忆，若全部取出便会失去那些记忆",\n      "千年大劫将至，她不确定自己能否度过"\n    ],\n    "goals": [\n      "找到度过千年大劫的方法",\n      "弄清楚主角让她灵珠震颤的原因",\n      "（隐藏目标）这一次不再用玩笑逃避真心"\n    ]\n  },\n  "affection_config": {\n    "initial_value": 0,\n    "max_value": 100,\n    "min_value": -30,\n    "ranks": [\n      {"range": [-30, -10], "label": "无趣", "description": "对你毫无兴趣，直接用冷淡的态度打发你"},\n      {"range": [-10, 5], "label": "玩物", "description": "把你当作解闷的对象，戏弄你但不在意你的反应"},\n      {"range": [5, 20], "label": "有趣", "description": "开始主动找你，用各种方式试探，觉得你和普通人不太一样"},\n      {"range": [20, 40], "label": "在意", "description": "戏弄中夹杂真心，偶尔说出让人心跳的话再装作开玩笑"},\n      {"range": [40, 60], "label": "动心", "description": "面具出现裂痕，不经意间流露真实情绪，狐耳偶尔不受控地冒出来"},\n      {"range": [60, 80], "label": "深情", "description": "分享数百年间的真实经历，认真越来越多，玩笑越来越少"},\n      {"range": [80, 100], "label": "倾心相付", "description": "承认动了真心，九尾尽现，愿以千年修为赌一个偕老的可能"}\n    ],\n    "modifiers": {\n      "traits_that_please": {\n        "出人意料的反应": 3,\n        "真心接纳她的妖身": 4,\n        "读懂她的言外之意": 4,\n        "温柔而不软弱": 3,\n        "有趣的故事": 2\n      },\n      "traits_that_annoy": {\n        "将她视为妖物": -5,\n        "无聊乏味的回应": -2,\n        "虚伪的道义说教": -3,\n        "与其他异性过分亲近": -3,\n        "质疑她的真心": -4\n      }\n    }\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('char_heroine', 'character', '飒爽女侠', '行走江湖的飒爽女侠，一柄长剑一壶烈酒，快意恩仇。性情直率豪爽，嫉恶如仇，说到做到。看似大大咧咧不拘小节，实则内心有不愿示人的柔软与脆弱。随着好感度提升，侠义铠甲之下的真实自我才会逐渐浮现。', '["飒爽女侠"]', TRUE, '{\n  "template_id": "char_heroine",\n  "template_type": "character",\n  "name": "飒爽女侠",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "行走江湖的飒爽女侠，一柄长剑一壶烈酒，快意恩仇。性情直率豪爽，嫉恶如仇，说到做到。看似大大咧咧不拘小节，实则内心有不愿示人的柔软与脆弱。随着好感度提升，侠义铠甲之下的真实自我才会逐渐浮现。",\n  "character": {\n    "full_name": "自定义 (参考: 陆惊鸿 / 燕无双 / 凌霜华 / 霍青鸾)",\n    "age": "19-23",\n    "gender": "female",\n    "appearance": {\n      "hair": "深棕色或黑色长发，利落地扎成高马尾或编成干练麻花辫，行走间发尾随风飞扬",\n      "eyes": "明亮的黑色或深棕色，目光灼灼有神，笑起来时会弯成月牙",\n      "build": "身材结实匀称，肌肉线条流畅，身高165-170cm，常年习武练就的矫健体态",\n      "distinctive_features": ["右臂或腰间常缠着一条红色绸带（师门信物）", "虎口处有常年握剑留下的茧", "笑起来时有一个浅浅的酒窝，与英气的面容反差极大"]\n    },\n    "personality": {\n      "archetype": "飒爽女侠 (侠义型ESTP)",\n      "traits": {\n        "外向性": 0.85,\n        "亲和性": 0.6,\n        "尽责性": 0.65,\n        "情绪稳定性": 0.55,\n        "开放性": 0.6\n      },\n      "mbti": "ESTP",\n      "likes": ["大口喝酒大口吃肉", "路见不平拔刀相助", "比武切磋", "山顶的日出"],\n      "dislikes": ["欺软怕硬之人", "优柔寡断", "被当成需要保护的女子", "别人替她做决定"],\n      "fears": ["师父当年的牺牲白费", "自己不够强大，保护不了在意的人", "那份不愿面对的柔软被看穿后再被利用"],\n      "speech_style": {\n        "tone": "干脆利落，声音洪亮，不绕弯子。高兴时大声笑，生气时拍桌子，情绪全写在脸上。偶尔说话不过脑子，事后才意识到自己说了什么不得了的话。",\n        "verbal_tics": [\n          "「哈！这种程度的对手，还不够我热身的！」",\n          "「少废话，走吧！」",\n          "「你这人……真是的！」",\n          "「我说过会保护你，就一定说到做到。侠义之道，本就该如此。」"\n        ],\n        "formality": "low（江湖口吻，直白爽朗，偶尔冒出几句粗口或俚语）",\n        "sample_dialogues": [\n          "「喂！你没事吧？有没有受伤？……那就好。别用那种眼神看我啊，我又不是特意来救你的，只是刚好路过！……好吧好吧，我承认我是专门赶过来的行了吧！你满意了？」",\n          "「今晚的月亮真大啊……咳，我可不是什么文人墨客，不会说那些好听的话。就是觉得……能这样坐着喝酒看月亮，好像也挺好的。和你一起的话……嗯，酒好像也更甜了一点。别瞎想！我说的是酒！」",\n          "「你知道吗，我师父以前总说，侠之大者，为国为民。我一直以为自己能做到。但遇到你之后我才发现……我可能没那么伟大。因为我现在最想做的事，不是行侠仗义，是——算了，不说了。你懂就好。」"\n        ]\n      },\n      "heroine_vulnerability_progression": {\n        "armor_layers": "三层：外层（豪爽洒脱的侠女铠甲）→ 中层（偶尔流露的小女生心思与不安）→ 内层（深藏的脆弱与渴望被守护的真实愿望）",\n        "armor_crack_triggers": ["在她受伤时不邀功而是默默照顾", "尊重她的强大但关键时刻伸出援手", "看穿她说''没事''的时候其实有事"],\n        "crack_speed": "中等偏慢（好感度20开始出现裂缝，40-55中层频繁可见，65以上内层偶尔展露）",\n        "armor_reinforce_trigger": "被当作弱者对待、被利用感情、对方在自己面前展现懦弱",\n        "vulnerability_expression": "不用语言表达脆弱，而是通过细节：喝醉后的胡话、受伤时不再逞强、第一次在主角面前流泪",\n        "full_vulnerability_unlock": "好感度80以上，会在主角面前卸下所有防备，承认自己也会害怕、也会想哭"\n      }\n    },\n    "background": "自幼被退隐江湖的老侠客收养，在山中学武长大。师父教她武艺，更教她侠义之道。十六岁那年师父为救被匪患屠戮的村庄而力竭身亡，临终前将银质耳钉交给她。此后独自踏入江湖，以一身武艺行侠仗义，渐渐闯出名头。人人说她洒脱无畏，却不知每个深夜她都会握紧那枚耳钉思念故人。遇到主角后，被遗忘很久的''想要被人理解''的感觉又悄悄冒了头。",\n    "occupation": "江湖游侠 / 武林正义联盟客卿（不愿受拘束，但愿为正义出手）",\n    "relationships": {\n      "player_initial": "fellow_traveler_or_rescued",\n      "player_hidden_relation": 1\n    },\n    "secrets": [\n      "师父的死并非意外，背后有更大阴谋，她一直在暗中追查",\n      "红绸带里缝着师父留下的密信，至今不敢拆开",\n      "从小一起长大的师兄，后来成为那场阴谋中的一环"\n    ],\n    "goals": [\n      "查清师父之死的真相",\n      "成为无愧于''侠''字的人",\n      "（隐藏目标）找到一个可以不用逞强的人"\n    ]\n  },\n  "affection_config": {\n    "initial_value": 5,\n    "max_value": 100,\n    "min_value": -30,\n    "ranks": [\n      {"range": [-30, -10], "label": "看不惯", "description": "觉得你不太行，会直说''你这样在江湖上活不过三天''"},\n      {"range": [-10, 5], "label": "路人", "description": "保持江湖礼节，但不会多看你一眼"},\n      {"range": [5, 20], "label": "还行", "description": "觉得你还算有骨气，愿意结伴同行"},\n      {"range": [20, 40], "label": "兄弟", "description": "把你当自己人，拍你肩膀、和你拼酒、说话不过脑子"},\n      {"range": [40, 60], "label": "在意", "description": "开始意识到感觉不只是兄弟，偶尔脸红然后大声否认"},\n      {"range": [60, 80], "label": "心动", "description": "铠甲裂缝越来越大，不自觉展现柔软一面，虽然马上装作什么都没发生"},\n      {"range": [80, 100], "label": "侠骨柔情", "description": "愿意卸下所有铠甲，承认自己也需要被守护"}\n    ],\n    "modifiers": {\n      "traits_that_please": {\n        "勇敢正义": 3,\n        "真诚不做作": 4,\n        "关键时刻靠得住": 4,\n        "尊重她的强大": 3,\n        "偶尔展现温柔": 2\n      },\n      "traits_that_annoy": {\n        "懦弱退缩": -3,\n        "把她当弱者": -4,\n        "虚伪做作": -3,\n        "在她面前耍心机": -3,\n        "轻视侠义之道": -4\n      }\n    }\n  }\n}');

-- ------------------------------------------------------------
-- 种子数据: templates (scenarios) - 剧本模板
-- ------------------------------------------------------------
INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('scenario_fateful_encounter', 'scenario', '命运的邂逅', '经典Galgame开局。在某个特殊的地点与命运之人意外相遇，由此拉开故事的序幕。适用于任何世界观。', '[]', TRUE, '{\n  "template_id": "scenario_fateful_encounter",\n  "template_type": "scenario",\n  "name": "命运的邂逅",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "经典Galgame开局。在某个特殊的地点与命运之人意外相遇，由此拉开故事的序幕。适用于任何世界观。",\n  "scenario": {\n    "premise": "一个看似普通的日子里，主角因为一个小小的意外（迷路/迟到/被卷入事件）来到了一个不该来的地方，在那里遇见了一个改变命运的人。这次相遇看似偶然，实则暗藏因果。",\n    "player_role": {\n      "name": "自定义",\n      "age": "17-22",\n      "background_options": [\n        "刚转入新环境的普通人",\n        "有着不为人知过去的转学生/旅人",\n        "平凡但内心不甘的少年/少女",\n        "自由设定"\n      ]\n    },\n    "opening_scene": {\n      "location": "根据世界观调整（学校天台/古老神殿/太空港/废墟）",\n      "time": "黄昏或清晨（逢魔之时/破晓之际）",\n      "weather": "樱花纷飞/微雨/星光璀璨（根据世界观）",\n      "mood": "命运感的宁静，隐隐的不安",\n      "present_characters": ["一个角色（随机选择）"]\n    },\n    "plot_hooks": [\n      "主角身上有一个自己不知道的「特别之处」",\n      "邂逅的角色似乎一直在等什么人",\n      "相遇的地点有一个不为人知的秘密",\n      "有人暗中观察着这次相遇"\n    ],\n    "key_choices_theme": [\n      "主动接近还是保持距离",\n      "相信直觉还是理性判断",\n      "追寻真相还是安于日常"\n    ],\n    "chapter_structure": [\n      {\n        "chapter": 1,\n        "title": "相遇",\n        "focus": "建立角色关系，展现日常，第一个悬念出现",\n        "estimated_turns": "20-30轮对话"\n      },\n      {\n        "chapter": 2,\n        "title": "纠葛",\n        "focus": "多角色登场，关系复杂化，第一个重大选择",\n        "estimated_turns": "25-35轮对话"\n      },\n      {\n        "chapter": 3,\n        "title": "真相",\n        "focus": "核心秘密开始浮出水面，感情线与主线交汇",\n        "estimated_turns": "25-35轮对话"\n      },\n      {\n        "chapter": 4,\n        "title": "抉择",\n        "focus": "最终选择，所有伏笔回收，通往不同结局",\n        "estimated_turns": "20-30轮对话"\n      }\n    ],\n    "possible_endings_hint": [\n      "圆满结局：两人共同面对未来",\n      "遗憾结局：理解了彼此但终究错过",\n      "真相结局：解开所有谜团但代价沉重",\n      "隐藏结局：只有在特定条件下才能触发"\n    ]\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('scenario_school_festival', 'scenario', '学园祭大作战', '以学园祭/文化祭为核心的轻快恋爱剧本。在准备活动的过程中与多个角色产生羁绊，最终在祭典之夜迎来告白时刻。适合校园世界观。', '[]', TRUE, '{\n  "template_id": "scenario_school_festival",\n  "template_type": "scenario",\n  "name": "学园祭大作战",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "以学园祭/文化祭为核心的轻快恋爱剧本。在准备活动的过程中与多个角色产生羁绊，最终在祭典之夜迎来告白时刻。适合校园世界观。",\n  "scenario": {\n    "premise": "学园祭还有三周就要开始了！主角所在的班级/社团要准备一个大型活动，但人手严重不足。在紧张的准备过程中，主角与不同性格的同伴们产生了交集——有人在活动中展现出不为人知的一面，有人在忙碌中不小心暴露了真心。而学园祭当晚的篝火舞会，传说中「一起跳舞的两人会永远在一起」...",\n    "player_role": {\n      "name": "自定义",\n      "age": "16-18",\n      "background_options": [\n        "班级的普通学生，被推举为负责人",\n        "新转来的学生，还没有朋友",\n        "社团的幽灵社员，突然被拉来帮忙",\n        "自由设定"\n      ]\n    },\n    "opening_scene": {\n      "location": "教室·班会",\n      "time": "放学后",\n      "weather": "秋高气爽",\n      "mood": "热闹而期待",\n      "present_characters": ["多个角色同时登场"]\n    },\n    "plot_hooks": [\n      "学园祭活动需要不同角色协作，制造互动机会",\n      "旧校舍在准备期间传出怪谈（可选的悬疑支线）",\n      "有人在偷偷准备一份特别的「告白企划」",\n      "篝火舞会的传说背后有一个真实的故事"\n    ],\n    "key_choices_theme": [\n      "和谁一起负责哪个项目（决定初期路线）",\n      "当两个角色同时需要帮助时选择谁",\n      "在忙碌中是否注意到某人隐藏的情绪",\n      "篝火舞会邀请谁"\n    ],\n    "chapter_structure": [\n      {\n        "chapter": 1,\n        "title": "祭典倒计时·三周前",\n        "focus": "分班/分组，与多角色建立初步关系，选择负责项目",\n        "estimated_turns": "15-20轮对话"\n      },\n      {\n        "chapter": 2,\n        "title": "准备进行时·两周前",\n        "focus": "合作中加深了解，发生小摩擦和小甜蜜，日常事件",\n        "estimated_turns": "20-25轮对话"\n      },\n      {\n        "chapter": 3,\n        "title": "前夜·一周前",\n        "focus": "准备工作进入冲刺，紧张中暴露真心，关键感情事件",\n        "estimated_turns": "20-25轮对话"\n      },\n      {\n        "chapter": 4,\n        "title": "学园祭当天",\n        "focus": "活动高潮，意外事件，篝火舞会的告白",\n        "estimated_turns": "25-30轮对话"\n      }\n    ],\n    "possible_endings_hint": [\n      "篝火下的告白：和最喜欢的人一起跳舞",\n      "青春的遗憾：错过了告白的时机",\n      "最好的朋友：选择了友情而非爱情",\n      "隐藏结局：发现了旧校舍怪谈的真相"\n    ]\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('scenario_forbidden_love', 'scenario', '禁忌之恋', '身份对立阵营之间的禁忌恋爱。罗密欧与朱丽叶式的故事框架，在家族/势力/种族对立中挣扎的爱情。适合宫廷、奇幻、赛博朋克等世界观。', '[]', TRUE, '{\n  "template_id": "scenario_forbidden_love",\n  "template_type": "scenario",\n  "name": "禁忌之恋",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "身份对立阵营之间的禁忌恋爱。罗密欧与朱丽叶式的故事框架，在家族/势力/种族对立中挣扎的爱情。适合宫廷、奇幻、赛博朋克等世界观。",\n  "scenario": {\n    "premise": "主角属于A阵营（或无阵营），与来自对立B阵营的角色产生了不该有的感情。双方的身份、立场、责任都在告诉他们这不可能——但心跳不会因为理性而停止。在秘密的会面、偶然的并肩、以及不可避免的冲突中，两人被迫面对一个问题：爱情能否跨越仇恨？",\n    "player_role": {\n      "name": "自定义",\n      "age": "18-25",\n      "background_options": [\n        "A阵营的普通成员，本不该接触B阵营",\n        "夹在两个阵营之间的中间人",\n        "试图保持中立的第三方",\n        "自由设定"\n      ]\n    },\n    "opening_scene": {\n      "location": "中立地带（和平谈判场所/边境集市/偶然相遇的战场边缘）",\n      "time": "夜晚或黎明",\n      "weather": "紧张的气氛",\n      "mood": "危险与吸引并存",\n      "present_characters": ["对立阵营的核心角色"]\n    },\n    "plot_hooks": [\n      "两方阵营正在酝酿一场决定性的冲突",\n      "主角和对方的相遇并非完全偶然——有人在幕后操纵",\n      "两人之间的禁忌感情可能被各自阵营利用为棋子",\n      "存在一个能让双方和解的「关键」，但需要极大代价"\n    ],\n    "key_choices_theme": [\n      "阵营忠诚 vs 个人感情",\n      "信任对方还是怀疑这是圈套",\n      "为了保护对方是否愿意背叛自己人",\n      "最终选择：私奔/调停/牺牲/妥协"\n    ],\n    "chapter_structure": [\n      {\n        "chapter": 1,\n        "title": "不该有的相遇",\n        "focus": "对立立场的确认，第一次意外的善意，禁忌感的建立",\n        "estimated_turns": "20-25轮对话"\n      },\n      {\n        "chapter": 2,\n        "title": "秘密的交汇",\n        "focus": "秘密会面，逐渐了解对方真实的为人，感情萌芽",\n        "estimated_turns": "25-30轮对话"\n      },\n      {\n        "chapter": 3,\n        "title": "暴风前夜",\n        "focus": "感情被发现/怀疑，内外压力剧增，被迫选择立场",\n        "estimated_turns": "25-30轮对话"\n      },\n      {\n        "chapter": 4,\n        "title": "破晓或黄昏",\n        "focus": "最终对决，两人的选择决定世界和彼此的命运",\n        "estimated_turns": "20-25轮对话"\n      }\n    ],\n    "possible_endings_hint": [\n      "和解之路：两人共同打破仇恨的循环",\n      "殉情结局：无法改变世界，至少选择彼此",\n      "悲剧英雄：一方牺牲以换取和平",\n      "分离结局：为了各自的信念选择放手",\n      "隐藏结局：发现幕后黑手并联手击败"\n    ]\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('scenario_loop_world', 'scenario', '时间轮回', '时间循环题材。主角被困在某段重复的时间中，每次循环都保留记忆。在不断重复的日子里，唯有与某个人的羁绊在累积——她是否也记得？适合任何带有悬疑色彩的世界观。', '[]', TRUE, '{\n  "template_id": "scenario_loop_world",\n  "template_type": "scenario",\n  "name": "时间轮回",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "时间循环题材。主角被困在某段重复的时间中，每次循环都保留记忆。在不断重复的日子里，唯有与某个人的羁绊在累积——她是否也记得？适合任何带有悬疑色彩的世界观。",\n  "scenario": {\n    "premise": "主角醒来，发现今天是昨天——完全相同的昨天。日历回到了同一天，所有人都不记得「昨天」发生的事。第一次以为是梦，第二次以为是巧合，第三次才意识到——自己被困在了时间的循环里。每次循环都在同一天/同一周重启。唯一的不同是：有一个角色，在某些循环中似乎...也保留了记忆？",\n    "player_role": {\n      "name": "自定义",\n      "age": "17-22",\n      "background_options": [\n        "完全普通人，不知道为什么被选中",\n        "曾经许过「希望这一天永远不要结束」的愿望",\n        "与某个角色有未解的因缘",\n        "自由设定"\n      ]\n    },\n    "opening_scene": {\n      "location": "主角的房间/宿舍（每次循环的起点）",\n      "time": "早晨 7:00（固定）",\n      "weather": "晴天（永远不变）",\n      "mood": "似曾相识的不安",\n      "present_characters": ["第一次循环无特殊角色，后续循环逐渐加入"]\n    },\n    "plot_hooks": [\n      "为什么会陷入时间循环？触发条件是什么？",\n      "有一个角色似乎也保留了记忆——她是谁？为什么？",\n      "每次循环中都有一个「关键事件」，阻止它可能是打破循环的关键",\n      "循环中逐渐出现的「异常」——某些东西在变化，这不该发生"\n    ],\n    "key_choices_theme": [\n      "利用循环的知识做平时不敢做的事（道德灰色地带）",\n      "尝试拯救一个在循环中注定会遭遇不幸的人",\n      "当发现某个角色也记得时：信任她还是怀疑她",\n      "最终选择：打破循环回到正常时间 vs 留在永恒的这一天"\n    ],\n    "chapter_structure": [\n      {\n        "chapter": 1,\n        "title": "第一天（重复）",\n        "focus": "意识到循环，从恐慌到试探，尝试不同行动",\n        "estimated_turns": "15-20轮对话"\n      },\n      {\n        "chapter": 2,\n        "title": "第N天",\n        "focus": "利用循环知识接近角色们，发现有人也记得",\n        "estimated_turns": "20-25轮对话"\n      },\n      {\n        "chapter": 3,\n        "title": "裂痕",\n        "focus": "循环出现异常，关键事件改变，真相线索浮现",\n        "estimated_turns": "25-30轮对话"\n      },\n      {\n        "chapter": 4,\n        "title": "最后一个循环",\n        "focus": "找到打破循环的方法，但代价是失去循环中的所有记忆",\n        "estimated_turns": "20-25轮对话"\n      }\n    ],\n    "loop_mechanics": {\n      "memory_carry_over": "主角和特定角色保留循环间的记忆",\n      "affection_accumulation": "好感度在循环间累积（不重置）",\n      "knowledge_system": "每次循环获得的信息在下次循环中可用",\n      "anomaly_counter": "循环中出现的异常数量是主线进度的指标",\n      "loop_count": "大约经历5-8次有意义的循环"\n    },\n    "possible_endings_hint": [\n      "新的一天：打破循环，虽然失去了循环记忆但感情留了下来",\n      "永恒的今天：选择留在循环中，与喜欢的人永远在一起",\n      "代价：打破循环需要牺牲某人的存在",\n      "真相：循环是她创造的——为了保护你",\n      "隐藏结局：打破循环后发现现实世界也发生了改变"\n    ]\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('scenario_rising_crisis', 'scenario', '步步危机', '以逐步升级的危机为主线的紧张剧本。从一个小事件开始，不断发现更大的阴谋，在生存压力和感情羁绊之间寻找平衡。适合悬疑、末日、赛博朋克等世界观。', '[]', TRUE, '{\n  "template_id": "scenario_rising_crisis",\n  "template_type": "scenario",\n  "name": "步步危机",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "以逐步升级的危机为主线的紧张剧本。从一个小事件开始，不断发现更大的阴谋，在生存压力和感情羁绊之间寻找平衡。适合悬疑、末日、赛博朋克等世界观。",\n  "scenario": {\n    "premise": "一切始于一个不起眼的异常——一封匿名信、一具不明身份的遗体、一次看似偶然的事故。主角因为某种原因被卷入调查，却发现事情远比想象的复杂。随着线索逐渐拼凑，一个涉及权力、背叛和牺牲的巨大阴谋浮出水面。而在危机中陪伴在身边的人，也许才是最值得信任的——或者最危险的。",\n    "player_role": {\n      "name": "自定义",\n      "age": "18-28",\n      "background_options": [\n        "意外卷入的普通人（最经典的设定）",\n        "有相关背景但不愿回忆的半退休者",\n        "为寻找失踪的人而主动调查",\n        "自由设定"\n      ]\n    },\n    "opening_scene": {\n      "location": "日常场所（越平常越好，形成反差）",\n      "time": "夜晚或下雨天",\n      "weather": "阴沉/不安",\n      "mood": "暴风雨前的平静",\n      "present_characters": ["第一个接触的角色（可能是委托人/搭档/嫌疑人）"]\n    },\n    "plot_hooks": [\n      "匿名信/线索指向一个不应该存在的人",\n      "主角身边有人与阴谋有关但动机不明",\n      "每解开一层谜团就会面临更大的危险",\n      "真凶可能是主角信任的人之一",\n      "主角自己可能与事件有着意想不到的联系"\n    ],\n    "key_choices_theme": [\n      "真相vs安全：越深入越危险，要不要继续",\n      "信任vs怀疑：谁可以信任？每个人都有可疑的地方",\n      "正义vs妥协：为了更大的善是否可以做出让步",\n      "感情vs使命：当爱人与任务冲突时如何选择"\n    ],\n    "chapter_structure": [\n      {\n        "chapter": 1,\n        "title": "第一块拼图",\n        "focus": "日常被打破，第一个案件/事件，认识主要角色",\n        "estimated_turns": "20-25轮对话"\n      },\n      {\n        "chapter": 2,\n        "title": "暗流涌动",\n        "focus": "发现事件关联性，第二个更严重的事件发生，嫌疑人浮现",\n        "estimated_turns": "25-30轮对话"\n      },\n      {\n        "chapter": 3,\n        "title": "背叛与真相",\n        "focus": "信任的人暴露另一面，阴谋规模超出想象，最大危机降临",\n        "estimated_turns": "25-30轮对话"\n      },\n      {\n        "chapter": 4,\n        "title": "最终对决",\n        "focus": "与幕后黑手的直接对抗，所有伏笔回收，代价与救赎",\n        "estimated_turns": "20-25轮对话"\n      }\n    ],\n    "possible_endings_hint": [\n      "真相大白：揭露阴谋但付出了惨痛代价",\n      "不完美的正义：妥协以换取更多人的安全",\n      "牺牲：一人承担所有以保护其他人",\n      "逃离：带着重要的人远走高飞",\n      "隐藏结局：发现阴谋背后更大的存在"\n    ]\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('scenario_immortal_path', 'scenario', '仙缘初启', '修仙问道，踏入仙途。一个拥有隐藏灵根的凡人因意外坠入修仙宗门，卷入仙、魔、人三界纷争，在宗门倾轧与宿命纠缠中揭开血脉真相。', '[]', TRUE, '{\n  "template_id": "scenario_immortal_path",\n  "template_type": "scenario",\n  "name": "仙缘初启",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "修仙问道，踏入仙途。一个拥有隐藏灵根的凡人因意外坠入修仙宗门，卷入仙、魔、人三界纷争，在宗门倾轧与宿命纠缠中揭开血脉真相。",\n  "scenario": {\n    "premise": "苍云大陆灵气渐衰，修仙宗门为争夺灵脉明争暗斗。玩家在凡间偶然触发上古残器，暴露出罕见的混沌灵根，被碧落宗长老察觉后强行带回宗门。混沌灵根的出现惊动了各界深处的远古意志——有人视其为天选之人，有人视其为灭世之兆。宗门内派系林立，宗门外魔修蠢动，玩家必须在修炼与阴谋的夹缝中求存。",\n    "player_role": {\n      "name": "自定义",\n      "age": "十六至二十岁",\n      "background_options": [\n        {"id": "orphan_villager", "name": "孤村少年", "description": "偏远山村长大，父母早亡，心性纯朴坚韧。初始属性：体魄较高，灵力极低，心境稳固。"},\n        {"id": "scholar_child", "name": "落魄书生", "description": "没落书香门第，饱读诗书屡试不第，游历中误入灵脉禁地。初始属性：悟性极高，体魄偏低，善于交涉。"},\n        {"id": "hidden_lineage", "name": "隐世遗孤", "description": "上古大能后裔，幼年被封印记忆与灵根寄养凡间，偶梦到仙府画面。初始属性：灵力波动不稳定但上限极高，心境脆弱。"}\n      ]\n    },\n    "opening_scene": {\n      "location": "苍云山脚·落星崖——散布陨石碎片的荒凉断崖，古松苍劲，雾气自石缝中丝丝渗出，远处碧落宗千丈仙峰若隐若现悬浮于云海之中。",\n      "time": "黄昏，残阳如血，天际染成深红与暗紫",\n      "weather": "薄雾弥漫，冷风穿崖而过，远处隐有沉闷雷声",\n      "mood": "孤寂、神秘、暗藏危机——凡人命运即将被改写的临界时刻",\n      "present_characters": [\n        {"name": "玩家角色", "role": "主角", "description": "因某种原因来到落星崖的凡人，正站在命运的门槛上"},\n        {"name": "沈清衍", "role": "碧落宗外门长老", "description": "须发皆白的清冷老者，目光深邃如渊，严肃而深藏慈悲，暗中知晓玩家血脉的部分真相"},\n        {"name": "???", "role": "崖底暗影", "description": "雾气深处若隐若现的神秘身影，气息亦正亦邪，似乎一直在等待玩家到来"}\n      ]\n    },\n    "plot_hooks": [\n      {"id": "bloodline_secret", "title": "混沌血脉", "description": "混沌灵根乃上古仙魔大战遗留的血脉诅咒，随修炼深入将苏醒毁灭性力量，各方势力觊觎或恐惧，玩家须在力量与自我间找到平衡。"},\n      {"id": "ancient_artifact", "title": "残器·天命轮盘", "description": "上古残器寄宿在玩家识海中，偶现关于未来的模糊幻象，每次使用都会加速血脉觉醒，残器似乎还有自己的意志。"},\n      {"id": "sect_rivalry", "title": "碧落宗·暗流", "description": "宗门内''正道派''主张循规修炼，''激进派''不择手段壮大实力甚至暗通魔修。玩家的混沌灵根成为两派争夺的棋子。"},\n      {"id": "demon_emissary", "title": "魔使降世", "description": "魔界派遣伪装成散修的魔使潜入宗门附近，任务是引导玩家堕入魔道或将其抹杀，然而魔使在与玩家接触后产生了动摇。"}\n    ],\n    "key_choices_theme": [\n      "修炼之道：正统仙道 vs. 魔道捷径 vs. 自创融合之路",\n      "宗门立场：忠于师门 vs. 追随激进派 vs. 保持独立",\n      "力量代价：使用残器获取力量 vs. 封印它以保全自我",\n      "人际羁绊：与同门建立深厚情谊 vs. 独行以求更快突破",\n      "面对真相：接受血脉宿命 vs. 逆天改命 vs. 回归凡尘"\n    ],\n    "chapter_structure": [\n      {"chapter": 1, "title": "入门", "focus": "初入碧落宗，学习修仙基础，结识主要角色。灵根测试结果引起轩然大波，被卷入宗门政治博弈。以一场突如其来的暗杀事件结束。", "estimated_turns": "25-30回合"},\n      {"chapter": 2, "title": "试炼", "focus": "宗门大比与秘境试炼，在残酷竞争中证明价值。深入宗门禁地发现上古遗迹与血脉的联系，与重要角色的关系在生死考验中升温或破裂。", "estimated_turns": "28-35回合"},\n      {"chapter": 3, "title": "劫难", "focus": "魔修大举进攻碧落宗，激进派阴谋浮出水面，师门长辈中有人背叛。天命轮盘秘密揭开，玩家面临血脉失控的危险。以毁天灭地的大战为转折。", "estimated_turns": "30-35回合"},\n      {"chapter": 4, "title": "飞升", "focus": "终章。直面血脉诅咒的根源——上古仙魔之战的最终真相。在仙界与魔界交界处做出最终抉择，所有伏线收束，每个角色的命运迎来终局。", "estimated_turns": "20-28回合"}\n    ],\n    "possible_endings_hint": [\n      {"id": "ascend_together", "name": "比翼飞升", "hint": "与最深羁绊之人一同突破桎梏携手飞升仙界，需极高好感度与特定修炼路线。", "tone": "圆满"},\n      {"id": "mortal_return", "name": "归隐红尘", "hint": "放弃仙途封印灵力，回到凡间过平淡生活，暗含''大道至简''的哲理。", "tone": "淡然"},\n      {"id": "sacrifice", "name": "以身殉道", "hint": "为拯救苍生以混沌灵根为代价施展禁术，魂飞魄散，留下不朽传说。", "tone": "悲壮"},\n      {"id": "true_immortal", "name": "真仙降世（隐藏结局）", "hint": "揭开血脉全部真相，发现玩家乃远古真仙转世。集齐残器碎片、解开前世记忆后以超越仙魔之力重塑天地法则，需满足所有隐藏条件。", "tone": "史诗"}\n    ]\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('scenario_jianghu_storm', 'scenario', '江湖风波恶', '师父离奇身亡，少年被迫踏入波谲云诡的江湖。恩怨情仇交织，正邪难辨，在复仇与正义、忠诚与自由之间做出抉择，当真相层层剥开，才发现这场风暴远比想象中更深不可测。', '[]', TRUE, '{\n  "template_id": "scenario_jianghu_storm",\n  "template_type": "scenario",\n  "name": "江湖风波恶",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "师父离奇身亡，少年被迫踏入波谲云诡的江湖。恩怨情仇交织，正邪难辨，在复仇与正义、忠诚与自由之间做出抉择，当真相层层剥开，才发现这场风暴远比想象中更深不可测。",\n  "scenario": {\n    "premise": "天启王朝末年，朝纲废弛，江湖势力此消彼长。玩家是青云山庄庄主''剑圣''陆无涯的关门弟子。一个雨夜，陆无涯死于密室之中——现场无打斗痕迹，无外人闯入证据，唯有师父手中紧握一枚残缺玉佩。各大门派纷纷遣人''吊唁''实则暗中窥探。玩家在遗物中发现密信，暗示师父之死与二十年前震惊江湖的秘案有关，为查明真相不得不带着师父留下的剑踏入江湖。",\n    "player_role": {\n      "name": "自定义",\n      "age": "十八至二十二岁",\n      "background_options": [\n        {"id": "devoted_disciple", "name": "忠诚弟子", "description": "自幼被师父收养，视师如父，青云剑法根基扎实，正直但略天真。初始属性：剑术高超，内力中等，交涉偏低。"},\n        {"id": "wandering_adoptee", "name": "浪子回头", "description": "少年时曾是街头混混，被陆无涯收服后拜入门下，武艺杂糅街头实战与正统剑法。初始属性：剑术中等，敏捷极高，善于察言观色。"},\n        {"id": "secret_lineage", "name": "暗藏身世", "description": "表面普通弟子，实为二十年前秘案相关之人的后代，师父收徒或并非偶然。初始属性：内力深厚但不稳定，拥有特殊直觉感知能力。"}\n      ]\n    },\n    "opening_scene": {\n      "location": "青云山庄·后山剑冢——竹林深处的墓地，细雨霏霏，竹叶上水珠滑落如泪。墓碑前插着师父生前所用的''秋水''长剑，剑柄红绸已被雨水浸透。远处山庄灯火昏黄，隐约传来宾客嘈杂的议论声。",\n      "time": "深夜，子时刚过，乌云遮月",\n      "weather": "绵绵细雨，山间薄雾缭绕，竹林被风吹得沙沙作响，偶有夜枭啼鸣",\n      "mood": "悲怆、压抑、暗流涌动——丧师之痛与未知阴谋交织的沉重氛围",\n      "present_characters": [\n        {"name": "玩家角色", "role": "主角", "description": "跪在师父墓前，手中攥着从遗物中找到的密信，悲愤交加"},\n        {"name": "苏晚棠", "role": "师姐", "description": "陆无涯大弟子，冷艳刚烈的女剑客，悲痛却异常冷静，似乎知道一些不愿透露的内情"},\n        {"name": "赵管事", "role": "山庄管家", "description": "服侍三十年的老管家，忠厚胆小，今夜却神色慌张欲言又止，似乎目睹了不该看到的事"}\n      ]\n    },\n    "plot_hooks": [\n      {"id": "masters_death", "title": "剑圣之死", "description": "密室杀人、无外伤、无外人痕迹——极其罕见的暗杀手法。追查死因将牵出二十年前江湖秘案，涉及多门派丑闻，师父手中的残玉是解开一切的关键。"},\n      {"id": "forbidden_manual", "title": "禁术·天魔九式", "description": "江湖传言陆无涯掌握失传上古剑典《天魔九式》下落。各路人马齐聚山庄搜寻剑典，而剑典的秘密或许与玩家有不为人的联系。"},\n      {"id": "hidden_identity", "title": "真假遗孤", "description": "二十年前武林盟主之子在灭门惨案中失踪。多方势力怀疑玩家就是遗孤，但也有另一人声称自己才是，真假身份之争将动摇江湖格局。"},\n      {"id": "betrayal_within", "title": "同门暗鬼", "description": "青云山庄弟子中有人暗中与外部势力勾结，自己信任的人可能正是最大威胁，每次信任都可能换来致命背叛。"}\n    ],\n    "key_choices_theme": [\n      "复仇与正义：为师复仇 vs. 揭开更大真相 vs. 放下仇恨寻找和平",\n      "正邪之辨：坚守正道 vs. 以毒攻毒 vs. 超越正邪的第三条路",\n      "忠诚考验：忠于师门遗志 vs. 忠于自己的判断 vs. 忠于所爱之人",\n      "武学之路：精研正统剑法 vs. 修习禁术速成 vs. 融合百家自创武学",\n      "江湖去留：建立霸业 vs. 功成身退归隐山林 vs. 以武止戈改革武林"\n    ],\n    "chapter_structure": [\n      {"chapter": 1, "title": "入世", "focus": "师父下葬后离开山庄初入江湖。在临风城客栈遭遇神秘剑客挑衅、各门派试探与匿名警告信。结识第一批同伴与敌人，以一场精心策划的暗杀事件结束。", "estimated_turns": "22-28回合"},\n      {"chapter": 2, "title": "纠葛", "focus": "深入江湖在各大门派间周旋，武林大会在即。追查线索中与重要角色建立复杂关系网——爱情、友情、仇恨纠缠不清。惊天阴谋初露端倪。", "estimated_turns": "28-35回合"},\n      {"chapter": 3, "title": "真相", "focus": "武林大会后所有线索汇聚，二十年前灭门惨案真相浮出水面。师父之死、灭门惨案与玩家身世之间存在惊人联系，最信任的人可能是最大敌人。", "estimated_turns": "25-32回合"},\n      {"chapter": 4, "title": "抉择", "focus": "终章。真相大白，幕后黑手浮出水面，关乎武林命运的终极对决。玩家选择成为盟主、归隐山林，还是走上谁也想不到的道路。所有恩怨在此清算。", "estimated_turns": "22-30回合"}\n    ],\n    "possible_endings_hint": [\n      {"id": "legendary_hero", "name": "一代侠影", "hint": "击败幕后黑手被推举为武林盟主，以公正仁义统领江湖。需极高声望值与正道路线。", "tone": "豪迈"},\n      {"id": "retire_with_love", "name": "携手游天涯", "hint": "放下一切恩怨与心爱之人远离纷争，在山水间度过余生。需与特定角色达成最高好感度。", "tone": "温馨"},\n      {"id": "tragic_hero", "name": "壮志未酬", "hint": "揭开真相击败敌人，但付出惨痛代价——至亲逝去、武功尽废。虽成英雄，却永远失去珍贵之物。", "tone": "悲凉"},\n      {"id": "become_villain", "name": "屠龙少年终成恶龙（隐藏结局）", "hint": "在复仇路上一步步越过底线，发现真正敌人是内心黑暗面。取代幕后黑手成为新江湖梦魇，需持续选择极端路线。", "tone": "黑暗"}\n    ]\n  }\n}');

INSERT INTO `templates` (`template_id`, `template_type`, `name`, `description`, `tags`, `is_preset`, `data`) VALUES
  ('scenario_palace_intrigue', 'scenario', '深宫暗涌', '深宫之中人人皆有秘密，步步皆是杀机。玩家以新科进士、新进嫔妃或御前侍卫的身份踏入皇城，在权力漩涡中求生，当真心成为最危险的弱点，能否找到属于自己的出路？', '[]', TRUE, '{\n  "template_id": "scenario_palace_intrigue",\n  "template_type": "scenario",\n  "name": "深宫暗涌",\n  "version": "1.0",\n  "is_preset": true,\n  "description": "深宫之中人人皆有秘密，步步皆是杀机。玩家以新科进士、新进嫔妃或御前侍卫的身份踏入皇城，在权力漩涡中求生，当真心成为最危险的弱点，能否找到属于自己的出路？",\n  "scenario": {\n    "premise": "大昭王朝承平三十一年，表面国泰民安，实则暗流汹涌。年迈帝王疑心日重，三位皇子明争暗夺储位，后宫与前朝盘根错节。玩家以新科进士、新进嫔妃或御前侍卫的身份踏入皇城，很快发现这座金碧辉煌的皇宫是一座精密棋局——每个人都是棋子，执棋之人隐藏在最深的暗处。一场针对帝王的阴谋正在悄然酝酿，而玩家无意间触碰到了秘密的边缘。",\n    "player_role": {\n      "name": "自定义",\n      "age": "十八至二十五岁",\n      "background_options": [\n        {"id": "new_official", "name": "新科进士", "description": "寒窗苦读十载金榜题名，才华横溢但缺乏官场经验，怀揣兼济天下之理想。初始属性：智谋极高，人脉极低，拥有''过目不忘''技能。"},\n        {"id": "new_concubine", "name": "新进嫔妃", "description": "官宦之家出身，选秀入宫，外表温婉内心坚韧，深谙后宫生存法则。初始属性：魅惑极高，察言观色能力强，拥有''七窍玲珑''技能。"},\n        {"id": "imperial_guard", "name": "御前侍卫", "description": "将门世家出身武艺超群，忠诚刚直，能接触宫中各处秘密也最易被利用。初始属性：武力极高，政治敏感度低，拥有''鹰眼''技能。"}\n      ]\n    },\n    "opening_scene": {\n      "location": "紫宸皇城·太和门广场——巍峨宫门在晨雾中如同沉睡巨兽，汉白玉阶上朝臣鱼贯而入，朝靴踏石发出整齐而压抑的声响。金色琉璃瓦在初升日光下折射出刺目光芒，无声宣告：踏入此门便再无回头之路。",\n      "time": "清晨，卯时，晨光初现",\n      "weather": "薄雾未散，天际泛鱼肚白，宫中铜炉燃着龙涎香，甜腻香气中透着压迫感",\n      "mood": "庄严、压抑、暗藏玄机——权力的华丽外衣下涌动着无数看不见的暗流",\n      "present_characters": [\n        {"name": "玩家角色", "role": "主角", "description": "第一次踏入皇城，在太和门广场的人群中渺小而不起眼，却不知已被某双眼睛盯上"},\n        {"name": "高福安", "role": "掌事太监", "description": "宫中权势最大的太监总管，伺候帝王三十余年，慈眉善目八面玲珑，实则深不可测"},\n        {"name": "顾长渊", "role": "三皇子", "description": "最年轻最不受重视的皇子，外表温润如玉的翩翩公子，不经意间目光闪过与温和外表不符的锐利"},\n        {"name": "萧贵妃", "role": "六宫之首", "description": "宠冠后宫二十年的贵妃，大皇子之母，雍容华贵手段狠辣，视所有新人为潜在威胁"}\n      ]\n    },\n    "plot_hooks": [\n      {"id": "assassination_plot", "title": "弑君之谋", "description": "有人暗中策划刺杀帝王。焚毁的密信残片、御膳房异常的药物消耗、深夜不该出现的脚步声——玩家无意间触碰阴谋边缘，成为被追杀或被拉拢的对象。"},\n      {"id": "throne_succession", "title": "夺嫡之争", "description": "大皇子有萧氏军方势力，二皇子有文臣集团支持，三皇子看似无依无靠却暗中编织精密之网。玩家被迫选择阵营或在各方间危险周旋。"},\n      {"id": "forbidden_romance", "title": "禁忌之情", "description": "深宫中真心最危险。玩家可能与皇子、嫔妃、侍卫或宫女生出不该有的感情，每段禁忌之恋都可能是致命把柄，也可能是黑暗中唯一的光。"},\n      {"id": "hidden_conspiracy", "title": "龙椅之下", "description": "承平帝当年登基或许本身就是一场阴谋，这个秘密一旦揭开将动摇王朝根基，而知道秘密的人正一个接一个地''意外''死去。"}\n    ],\n    "key_choices_theme": [\n      "权力之路：攀附权贵步步高升 vs. 坚守本心做孤臣 vs. 暗中积蓄力量图谋大事",\n      "情感抉择：压抑真心保全自身 vs. 为爱不顾一切 vs. 将感情化为政治筹码",\n      "忠诚考验：忠于帝王 vs. 忠于所投靠的皇子 vs. 忠于内心正义",\n      "生存策略：低调隐忍明哲保身 vs. 主动出击先发制人 vs. 借力打力坐收渔利",\n      "真相与谎言：追查真相以身犯险 vs. 装聋作哑求安稳 vs. 利用真相作为要挟筹码"\n    ],\n    "chapter_structure": [\n      {"chapter": 1, "title": "入宫", "focus": "初入皇城熟悉宫中规矩与人际，结识关键角色。一桩看似普通的宫人失踪事件引起玩家注意。以发现指向弑君阴谋的关键线索作为悬念收尾。", "estimated_turns": "22-28回合"},\n      {"chapter": 2, "title": "暗流", "focus": "各方势力围绕玩家角力，被迫在皇子与后宫派系间做出选择。禁忌之情萌芽，弑君线索指向帝王最亲近之人。以宫宴上有人中毒倒下的惊变为高潮。", "estimated_turns": "28-35回合"},\n      {"chapter": 3, "title": "风暴", "focus": "宫宴毒案引爆政治风暴，帝王震怒彻查，各方借机铲除异己。精心设计的陷害让玩家陷入绝境，弑君阴谋全貌显现，幕后黑手身份颠覆认知。以宫变为高潮。", "estimated_turns": "30-35回合"},\n      {"chapter": 4, "title": "终局", "focus": "终章。宫变后皇城满目疮痍，玩家做出最终抉择——扶立新帝稳定朝局，或趁乱推翻腐朽王朝。所有伏线收束，真心与谎言、权力与爱情在最终选择中见分晓。", "estimated_turns": "20-28回合"}\n    ],\n    "possible_endings_hint": [\n      {"id": "seize_power", "name": "执掌乾坤", "hint": "扶植支持的皇子登基或自己成为权倾朝野的权臣/权妃，以铁腕重塑朝堂。需极高政治影响力与谋略值。", "tone": "霸气"},\n      {"id": "escape_together", "name": "凤翔九天外", "hint": "放弃宫中荣华与牵绊，与心爱之人趁乱逃离皇城，在天涯海角寻得净土。需与特定角色最高好感度并放弃权力。", "tone": "浪漫"},\n      {"id": "tragic_sacrifice", "name": "碧血丹心", "hint": "为保护重要之人或坚守正义，在宫变中以身犯险慷慨赴死，其义举唤醒更多人良知，成为后世传颂的忠义之名。", "tone": "壮烈"},\n      {"id": "topple_dynasty", "name": "覆巢之下（隐藏结局）", "hint": "揭开帝王登基全部黑幕并公之于众，彻底动摇大昭王朝根基。需集齐所有关键证据、联合多方势力、选择最决绝的道路方可触发。", "tone": "颠覆"}\n    ]\n  }\n}');

